// Cache for loaded forms (to use with index-based functions)
// Use window scope to ensure consistency
if (!window.loadedForms) window.loadedForms = [];
if (!window.loadedServiceForms) window.loadedServiceForms = [];
var preNewFormData = null;

// Pagination cursors for "Load more"
var _savedLastDoc = null, _sentLastDoc = null, _savedHasMore = false, _sentHasMore = false;
var _templateLastDoc = null, _templateHasMore = false;
var _serviceLastDoc = null, _serviceSentLastDoc = null, _serviceHasMore = false, _serviceSentHasMore = false;
var _lastLocalSaveTs = 0;
var _pendingFirestoreOps = window._pendingFirestoreOps || Promise.resolve();
window._pendingFirestoreOps = _pendingFirestoreOps;

document.addEventListener('click', function(e) {
    var link = e.target && e.target.closest ? e.target.closest('a[href]') : null;
    if (!link) return;

    var href = link.getAttribute('href');
    if (!href || href.charAt(0) === '#') return;

    var url;
    try {
        url = new URL(href, window.location.href);
    } catch (err) {
        return;
    }

    if ((url.protocol !== 'http:' && url.protocol !== 'https:') || url.origin === window.location.origin) {
        return;
    }

    e.preventDefault();
    e.stopPropagation();
    window.open(url.href, '_blank', 'noopener,noreferrer');
});

// Bulk select mode state (saved-modal multi-select for bulk export)
var _selectMode = false;
var _selectedSet = new Set();  // indices into active tab's loaded array
var _selectTab = null;         // 'own' | 'service'

function resetPaginationState() {
    _savedLastDoc = null; _sentLastDoc = null;
    _savedHasMore = false; _sentHasMore = false;
    _templateLastDoc = null; _templateHasMore = false;
    _serviceLastDoc = null; _serviceSentLastDoc = null;
    _serviceHasMore = false; _serviceSentHasMore = false;
}

// ── Last den ÅPNE siden på nytt når innloggingen blir klar — gjelder ALLE sider ──────────
// Bruker 18-11-2026: «ting skal ikke mangle etter refresh». Etter en oppdatering tegnes siden
// med en gang fra lokal cache (snappy), FØR Firebase-innloggingen er klar; alt som må hentes
// fra Firestore hoppes over da (currentUser er null). Denne funksjonen henter så den åpne
// sidens data på nytt, uten at brukeren må gå ut og inn igjen. Den kjøres:
//   1. så snart innlogging + tilgang (firma/admin) er kjent — _accEnforce (firstReady)
//   2. etter full synk ved innlogging (script.js) — for sider som leser synkede innstillinger.
// Ny view/side med data fra Firestore: legg inn en gren her (gate på view-ID-en, ikke på hvor
// man kom fra). Skjema-viewene (ordreseddel/servicebil/kappe/kvittering) og Verktøy trenger ingen
// gren: innholdet kommer fra økten (sessionStorage) / lokale beregninger, og prosjektfeltene
// oppdateres av _rerenderListsAfterProjectCorrection.
function refreshActiveView() {
    if (!currentUser || !db) return;
    var v = document.querySelector('.view.active');
    var id = v ? v.id : '';
    if (id === 'saved-modal') {
        _hentRefreshActiveTab();
    } else if (id === 'template-modal') {
        getTemplates().then(function(result) {
            _templateLastDoc = result.lastDoc;
            _templateHasMore = result.hasMore;
            window.loadedTemplates = result.forms;
            _projCache(result.forms);
        }).catch(function(e) { console.error('Refresh templates:', e); });
        if (typeof _homeRenderCounts === 'function') _homeRenderCounts();   // «N utkast» fra synkede lister
    } else if (id === 'timebok-view') {
        // Hent gjeldende periode på nytt; hopp over hvis vi nettopp lagret lokalt.
        var range = _timebokPeriodRange();
        getTimebokDays(range.start, range.end).then(function(days) {
            if (Date.now() - _lastLocalSaveTs < 5000) return;
            // Oppdater cache med disse dagene (merge inn i 60-vinduet).
            _timebokMergeDaysToCache(days);
            if (document.body.classList.contains('timebok-view-open') && !_timebokIsDirty()) renderTimebok();
        }).catch(function(e) { console.error('Refresh timebok:', e); });
    } else if (id === 'sjekkliste-view') {
        _sjRefreshActive();
    } else if (id === 'docs-modal') {
        // Bare om lista ikke alt er hentet i denne økten (kalles to ganger ved innlogging).
        if (typeof _docsLoad === 'function' && !_docsFetched) _docsLoad();
    } else if (id === 'settings-modal') {
        // Innstillingssiden ble tegnet FØR innlogging/admin-status var klar (Admin-sidene ble da
        // tomme, f.eks. Brukere). Tegn den åpne undersiden på nytt — men ikke midt i skriving.
        var page = sessionStorage.getItem('firesafe_settings_page');
        var pageEl = page && document.getElementById('settings-page-' + page);
        var editing = pageEl && pageEl.contains(document.activeElement) && /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName);
        if (page && document.body.classList.contains('settings-subpage-open') && !editing) showSettingsPage(page, true);
    }
}
// Lagret-lista: hent fanen som står åpen (Egne / Servicebil / Kappeskjema), ikke bare Egne.
function _hentRefreshActiveTab() {
    if (!currentUser || !db) return;
    var tab = sessionStorage.getItem('firesafe_hent_tab') || 'own';
    if (tab === 'kappe') { if (typeof loadKappeTab === 'function') loadKappeTab(); return; }
    if (tab === 'servicebil') { _hentRefreshServicebil(); return; }
    Promise.all([getSavedForms(), getSentForms()]).then(function(results) {
        if (Date.now() - _lastLocalSaveTs < 5000) return;
        var savedResult = results[0], sentResult = results[1];
        _savedLastDoc = savedResult.lastDoc;
        _sentLastDoc = sentResult.lastDoc;
        _savedHasMore = savedResult.hasMore;
        _sentHasMore = sentResult.hasMore;
        safeSetItem(STORAGE_KEY, JSON.stringify(savedResult.forms.slice(0, 50)));
        safeSetItem(ARCHIVE_KEY, JSON.stringify(sentResult.forms.slice(0, 50)));
        window.loadedForms = _mergeAndDedup(
            savedResult.forms.map(function(f) { return Object.assign({}, f, { _isSent: false }); }),
            sentResult.forms.map(function(f) { return Object.assign({}, f, { _isSent: true }); })
        );
        if (document.body.classList.contains('saved-modal-open')) {
            renderSavedFormsList(window.loadedForms, false, _savedHasMore || _sentHasMore);
        }
    }).catch(function(e) { console.error('Refresh saved forms:', e); });
}
// Servicebil-fanen: påfylling (INNTAK) + sendte service-skjemaer (UTTAK) fra Firebase.
function _hentRefreshServicebil() {
    if (!(currentUser && db && typeof getServiceForms === 'function' && typeof getServiceSentForms === 'function')) return;
    Promise.all([getServiceForms(), getServiceSentForms()]).then(function(results) {
        if (Date.now() - _lastLocalSaveTs < 5000) return;
        safeSetItem(SERVICE_STORAGE_KEY, JSON.stringify((results[0].forms || []).slice(0, 50)));
        safeSetItem(SERVICE_ARCHIVE_KEY, JSON.stringify((results[1].forms || []).slice(0, 50)));
        if (document.body.classList.contains('saved-modal-open')) renderBilHistory();
    }).catch(function() {});
}

// Helper: format date with time
function formatDateWithTime(date) {
    if (!date) return '';
    const d = new Date(date);
    const day = d.getDate().toString().padStart(2, '0');
    const month = (d.getMonth() + 1).toString().padStart(2, '0');
    const year = d.getFullYear();
    const hours = d.getHours().toString().padStart(2, '0');
    const mins = d.getMinutes().toString().padStart(2, '0');
    return `${day}.${month}.${year}, ${hours}:${mins}`;
}

// Nyeste først for ISO-tidsstempler (savedAt/createdAt/lastAt). Vanlig streng-
// sammenligning gir samme rekkefølge som localeCompare for ISO-datoer, men er mange
// ganger raskere (localeCompare går via språkbevisst ICU-sortering) — det merktes
// når Lagret sorterte 100+ skjemaer ved hvert trykk.
function _cmpIsoDesc(a, b) {
    a = a || ''; b = b || '';
    return a < b ? 1 : a > b ? -1 : 0;
}

// Skroll-nullstilling ved visningsbytte UTEN tvungen layout. Å sette scrollTop /
// window.scrollTo midt i et bytte tvinger nettleseren til å regne ut layouten for
// HELE dokumentet (alle views ligger i samme DOM) — 30–60 ms per gang på mobil, og ett
// trykk gjorde ofte 2–3 slike (closeAllModals → showView('view-form') → showView(mål)).
//  - En view som var skjult (display:none) da oppgaven startet, har ingen skrollboks og
//    vises alltid fra toppen → trenger ingen nullstilling.
//  - Bare en view som var SYNLIG ved start og vises igjen i samme oppgave (skjult og vist
//    på nytt) nullstilles — samlet i én mikrooppgave etter alle DOM-endringene.
//  - Dokument-skrollen (Hjem/PC/tastatur-layout scroller body) nullstilles bare når den
//    ikke står på 0; verdien spores i scroll-hendelsen, der lesingen er gratis.
var _svStartActiveId, _svTarget = null, _svPending = false;
var _docScrollY = null;   // null = ukjent → nullstill for sikkerhets skyld
window.addEventListener('scroll', function () { _docScrollY = window.scrollY; }, { passive: true });
window.addEventListener('load', function () { _docScrollY = window.scrollY; });
function _svScheduleScrollReset(target, prevActiveId) {
    if (!_svPending) {
        _svPending = true;
        _svStartActiveId = prevActiveId;
        Promise.resolve().then(function () {
            var t = _svTarget, startId = _svStartActiveId;
            _svPending = false; _svTarget = null; _svStartActiveId = undefined;
            if (t && t.id === startId && t.classList.contains('active')) t.scrollTop = 0;
            if (_docScrollY !== 0) { window.scrollTo(0, 0); _docScrollY = 0; }
        });
    }
    _svTarget = target;
}

// ── Innhold endres uten at siden flytter seg (gjelder hele appen) ─────────────
// Når et trykk fjerner eller legger til innhold (f.eks. «Hullet er tomt» skjuler rader),
// skal elementet brukeren trykket på stå på SAMME sted på skjermen. Det vanlige
// problemet: krymper siden mens du står langt nede, MÅ nettleseren klemme
// skrollposisjonen (det finnes ikke lenger så mye side under) → alt hopper. Da legges
// et midlertidig tomrom nederst som holder posisjonen; det fjernes av seg selv når
// det er skrollet helt ut av syne (fjerning da kan ikke flytte noe synlig).
// getAnchor: funksjon som returnerer ankeret ETTER endringen (det kan ha blitt tegnet på nytt).
function _scrollerFor(el) {
    var v = el && el.closest ? el.closest('.view') : null;
    if (v) {
        var oy = getComputedStyle(v).overflowY;
        if ((oy === 'auto' || oy === 'scroll') && v.scrollHeight > v.clientHeight) return v;
    }
    return document.scrollingElement || document.documentElement;
}
function _preserveScrollAround(getAnchor, mutate) {
    var a0 = getAnchor();
    if (!a0) { mutate(); return; }
    var sc = _scrollerFor(a0);
    var top0 = a0.getBoundingClientRect().top;
    mutate();
    var a1 = getAnchor();
    if (!a1) return;
    var delta = a1.getBoundingClientRect().top - top0;
    if (Math.abs(delta) < 1) return;
    var target = sc.scrollTop + delta;
    var max = sc.scrollHeight - sc.clientHeight;
    if (target > max) {
        var host = (a1.closest && (a1.closest('.mobile-form') || a1.closest('.view'))) || document.body;
        var sp = host.querySelector(':scope > .scroll-keep-spacer');
        if (!sp) { sp = document.createElement('div'); sp.className = 'scroll-keep-spacer'; sp.setAttribute('aria-hidden', 'true'); host.appendChild(sp); }
        sp.style.height = ((parseFloat(sp.style.height) || 0) + (target - max)) + 'px';
        _watchScrollSpacer(sc, sp);
    }
    sc.scrollTop = target;
}
// Fjern tomrommet når det er helt under synsfeltet (da kan fjerningen ikke flytte noe synlig).
function _watchScrollSpacer(sc, sp) {
    if (sp._watching) return;
    sp._watching = true;
    var target = (sc === document.scrollingElement || sc === document.documentElement) ? window : sc;
    var onScroll = function () {
        if (!sp.isConnected) { target.removeEventListener('scroll', onScroll); return; }
        var r = sp.getBoundingClientRect();
        var vh = (target === window) ? window.innerHeight : sc.getBoundingClientRect().bottom;
        if (r.top >= vh) { sp.remove(); target.removeEventListener('scroll', onScroll); }
    };
    target.addEventListener('scroll', onScroll, { passive: true });
}

// View system: show one view, hide all others
var _previousViewId = null;
function showView(viewId) {
    var target = document.getElementById(viewId);
    var alreadyActive = target.classList.contains('active');
    if (!alreadyActive) {
        // Track previous view for back navigation
        var current = document.querySelector('.view.active');
        if (current) _previousViewId = current.id;
        document.querySelectorAll('.view').forEach(function(v) {
            v.classList.remove('active');
        });
        target.classList.add('active');
        _svScheduleScrollReset(target, current ? current.id : null);
    }
    _navNote();
    // Toolbar-state (i body vs. inni modal-body) håndteres av
    // applyKeyboardLayout via MutationObserver på .view-class-endringer.
    // Når .active flyttes til en annen view, fyrer observeren og apply
    // re-evaluerer modalHost — ingen manuell håndtering trengs her.
}

function closeAllModals() {
    var actionPopup = document.getElementById('action-popup');
    if (actionPopup) actionPopup.classList.remove('active');
    _bilHistoryRendered = false;
    document.body.classList.remove('template-modal-open', 'saved-modal-open', 'settings-modal-open', 'settings-subpage-open', 'service-view-open', 'kappe-view-open', 'kvittering-view-open', 'calculator-modal-open', 'timebok-view-open', 'sjekkliste-view-open', 'docs-modal-open');
    if (typeof _docsCloseViewer === 'function' && document.body.classList.contains('doc-viewer-open')) _docsCloseViewer();
    if (typeof _docsSelExit === 'function') _docsSelExit(true);
    // Servicebil-inntak/uttak-modus + picker-overlay må også lukkes —
    // ellers blir picker-overlay synlig over hjem/lagrede når brukeren
    // navigerer vekk fra Servicebil Inntak via toolbar (Hjem etc.).
    document.body.classList.remove('servicebil-inntak-mode', 'servicebil-uttak-mode');
    if (document.body.classList.contains('picker-active') && typeof closePickerOverlay === 'function') {
        closePickerOverlay();
    }
    sessionStorage.removeItem('firesafe_settings_page');
    sessionStorage.removeItem('firesafe_form_type');
    sessionStorage.removeItem('firesafe_hent_tab');
    sessionStorage.removeItem('firesafe_defaults_tab');
    sessionStorage.removeItem('firesafe_service_current');
    sessionStorage.removeItem('firesafe_kappe_current');
    sessionStorage.removeItem('firesafe_kvittering_current');
    sessionStorage.removeItem('firesafe_servicebil_mode');
    if (typeof _sjCloseForm === 'function') _sjCloseForm();   // sjekkliste-økt (inkl. ulagrede bilder)
    showView('view-form');
}

function isModalOpen() {
    return document.body.classList.contains('template-modal-open')
        || document.body.classList.contains('saved-modal-open')
        || document.body.classList.contains('settings-modal-open')
        || document.body.classList.contains('service-view-open')
        || document.body.classList.contains('kappe-view-open')
        || document.body.classList.contains('kvittering-view-open')
        || document.body.classList.contains('calculator-modal-open')
        || document.body.classList.contains('timebok-view-open')
        || document.body.classList.contains('sjekkliste-view-open')
        || document.body.classList.contains('docs-modal-open');
}

// Update toolbar button states based on current view
function updateToolbarState() {
    // No toolbar buttons need disabling anymore — save/export are in the form view itself
}

// Status-prikk-klasse for et lagret skjema. Antall tilstander avhenger av TYPEN:
//
//  ORDRESEDDEL (tab utelatt) — TRE tilstander:
//   s-draft (oransje) = Lagret — ikke sendt ennå (i forms-samlingen)
//   s-sent  (blå)     = Sendt — venter på svar (i archive, status='sendt')
//   s-done  (grafitt) = Lukket — svar mottatt, ferdigbehandlet
//
//  KAPPESKJEMA og SERVICEBIL — TO tilstander:
//   s-draft (oransje) = Lagret
//   s-sent  (blå)     = Sendt. Punktum. De trenger ingen godkjenning, så det
//                       finnes ingen «Lukket» å gå videre til.
//
// Hvorfor TYPEN avgjør, og ikke et lagret felt: kappe/service skriver aldri
// `status` (markKappeAsSent/markServiceAsSent flytter bare til arkiv-samlingen),
// så de falt før gjennom til s-done og så ut som lukkede saker. Å begynne å
// skrive feltet ville bare fikset NYE dokumenter — alt som alt ligger i arkivet
// ville forblitt grafitt. Å avgjøre på typen fikser gammel og ny data på én gang,
// uten å migrere ett eneste dokument.
//
// `tab` er en POSITIV allowlist, ikke `tab !== 'own'`. _statusSortRank og enhver
// fremtidig kaller som glemmer argumentet sender undefined; med negasjon ville
// det stille slått ordreseddel over til to tilstander. Slik er undefined per
// konstruksjon = ordreseddel.
//
// Både 'service' og 'servicebil' godtas: _savedItemTab returnerer 'service',
// mens _selectTab/switchHentTab bruker 'servicebil'.
//
// For ordreseddel er «Lukket» alt i archive som IKKE er 'sendt'. Det dekker med
// vilje flere lagrede verdier: 'ferdig', den utgåtte 'ikke_godkjent' (skrives
// ikke lenger, men gamle dokumenter har den) og eldre arkiverte helt uten
// status-felt. Derfor vises gammel data korrekt uten at noe må migreres.
function _statusDotClass(item, tab) {
    if (!item || !item._isSent) return 's-draft';
    // Typen vinner over feltet: et kappe-dokument som via duplisering eller
    // import har fått et fremmed status-felt skal aldri rendres som lukket.
    if (tab === 'service' || tab === 'servicebil' || tab === 'kappe' || tab === 'kvittering') return 's-sent';
    if (item.status === 'sendt') return 's-sent';
    return 's-done';
}

// Sorterings-rang for status-gruppering i lista: aktivt øverst (lagret, så
// sendt/venter på svar), lukkede nederst.
// KUN ordreseddel — kalles bare fra _savedFormsStatusCompare, som igjen brukes
// på window.loadedForms. Sender derfor bevisst ingen `tab` videre: default =
// 3-tilstands. Kappe/service sorterer med egne inline-komparatorer på _isSent.
function _statusSortRank(item) {
    switch (_statusDotClass(item)) {
        case 's-draft': return 0;   // 🟡 Lagret
        case 's-sent':  return 1;   // 🔵 Sendt
        default:        return 2;   // ⚫ Lukket
    }
}

// Delt sammenligner for lagrede ordresedler: status-gruppe først, nyeste først
// innen gruppen. Brukt av både førstegangs-merge og «Last flere»-re-sortering.
function _savedFormsStatusCompare(a, b) {
    var ra = _statusSortRank(a), rb = _statusSortRank(b);
    if (ra !== rb) return ra - rb;
    return _cmpIsoDesc(a.savedAt, b.savedAt);
}
// Ikoner for «marker neste status» i lista.
var _statusSendIcon = '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 2L11 13"/><path d="M22 2l-7 20-4-9-9-4 20-7z"/></svg>';
var _statusCheckIcon = '<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';

// Kebab (tre vertikale prikker) — samler kopier/dupliser/slett i én meny.
var kebabIcon = '<svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor"><circle cx="12" cy="5" r="2"/><circle cx="12" cy="12" r="2"/><circle cx="12" cy="19" r="2"/></svg>';

// Delt knapperad for ALLE lagrede-lister (ordreseddel/service/kappe): de ekte
// handling-knappene (kopier/dupliser/slett) skjules, og en kebab åpner menyen.
// Menyvalg utløser den SKJULTE ekte knappen → eksisterende per-liste click-
// delegering ruter handlingen (ingen duplisert logikk).
function _savedItemActionsHtml(hiddenButtonsHtml, leadingHtml) {
    return '<div class="saved-item-buttons">' +
        (leadingHtml || '') +
        '<div class="saved-item-hidden-actions" hidden>' + hiddenButtonsHtml + '</div>' +
        '<button class="saved-item-action-btn saved-item-menu-btn" title="' + t('more_actions') + '">' + kebabIcon + '</button>' +
    '</div>';
}

// Er skjemaet LUKKET (grå/grønn = ferdig eller ikke godkjent)? Alt som ligger i
// archive og ikke har status 'sendt' er lukket — samme regel som _statusDotClass
// og showFormStatusMenu bruker, samlet ett sted så de tre ikke kan bli uenige.
// Kun ordreseddel har 3-tilstands status; service/kappe er alltid utkast|sendt.
function _isFormClosed(form) {
    return !!(form && form._isSent && form.status !== 'sendt');
}

// Åpne handlings-menyen for en lagret-rad (gjenbruker #action-popup).
// Ikoner for de ekstra meny-valgene (Eksporter / Merk som).
var _menuExportIcon = '<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M7 10l5 5 5-5M12 15V3"/></svg>';
var _menuMarkIcon = '<svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor"><circle cx="12" cy="12" r="8"/></svg>';

// Hvilken liste-fane raden tilhører (avgjør tilgjengelige handlinger).
function _savedItemTab(savedItem) {
    if (savedItem.closest && savedItem.closest('#service-list')) return 'service';
    if (savedItem.closest && savedItem.closest('#kappe-list')) return 'kappe';
    if (savedItem.closest && savedItem.closest('#kvittering-list')) return 'kvittering';
    return 'own';
}

function showSavedItemMenu(savedItem) {
    if (!savedItem) return;
    var hidden = savedItem.querySelector('.saved-item-hidden-actions');
    if (!hidden) return;
    var form = savedItem._formData;
    var tab = _savedItemTab(savedItem);
    var labelMap = { clipboard: 'copy_btn', copy: 'duplicate_btn', delete: 'delete_btn' };
    var iconMap = { clipboard: copyIcon, copy: duplicateIcon, delete: deleteIcon };

    // Bygg valg-liste. Rekkefølge: Kopier · Dupliser · (Merk som) · Eksporter · Slett.
    var opts = [];
    Array.prototype.slice.call(hidden.querySelectorAll('button')).forEach(function(b) {
        if (b.classList.contains('disabled')) return;
        var type = b.classList.contains('clipboard') ? 'clipboard'
            : b.classList.contains('copy') ? 'copy' : 'delete';
        if (type === 'delete') return;   // slett legges sist
        opts.push({ icon: iconMap[type], label: t(labelMap[type]), onClick: function() { closeActionPopup(); b.click(); } });
    });
    // «Merk som» — alle skjematyper (kappe/service: 2 statuser, se _statusOptionsForTab).
    if (form) {
        opts.push({ icon: _menuMarkIcon, label: t('bulk_mark_btn'), onClick: function() { _showSingleStatusMenu(savedItem); } });
    }
    // «Eksporter» — alle faner. Åpner eksport-popup (last ned / del × PDF / PNG).
    if (form) {
        opts.push({ icon: _menuExportIcon, label: t('toolbar_export'), onClick: function() { _showSingleExportMenu(savedItem); } });
    }
    // «Slett» sist (rød), om aktiv.
    var delBtn = hidden.querySelector('.delete');
    if (delBtn && !delBtn.classList.contains('disabled')) {
        opts.push({ icon: deleteIcon, label: t('delete_btn'), danger: true, onClick: function() { closeActionPopup(); delBtn.click(); } });
    }

    _actionPopupBack(null);   // topp-nivå: ingen tilbake-pil
    var titleEl = document.getElementById('action-popup-title');
    if (titleEl) titleEl.textContent = t('more_actions');
    document.getElementById('action-popup-buttons').innerHTML = '<div class="saved-item-menu">' +
        opts.map(function(o, i) {
            return '<button class="saved-item-menu-option' + (o.danger ? ' saved-item-menu-option--danger' : '') + '" data-i="' + i + '">' +
                '<span class="saved-item-menu-option-icon">' + o.icon + '</span><span>' + escapeHtml(o.label) + '</span></button>';
        }).join('') + '</div>';
    var popup = document.getElementById('action-popup');
    popup.querySelectorAll('.saved-item-menu-option').forEach(function(el) {
        el.addEventListener('click', function() { var o = opts[parseInt(el.getAttribute('data-i'), 10)]; if (o) o.onClick(); });
    });
    popup.classList.add('active');
}
window.showSavedItemMenu = showSavedItemMenu;

// «Merk som» for ÉTT skjema (samme statuser som fler-valg-menyen for typen).
function _showSingleStatusMenu(savedItem) {
    var form = savedItem && savedItem._formData;
    if (!form) return;
    _actionPopupBack(function() { showSavedItemMenu(savedItem); });   // tilbake → 3-prikker
    var titleEl = document.getElementById('action-popup-title');
    if (titleEl) titleEl.textContent = t('bulk_mark_btn');
    var tab = _savedItemTab(savedItem);
    document.getElementById('action-popup-buttons').innerHTML =
        '<div class="bulk-status-menu">' +
            _statusOptionsForTab(tab).map(function(target) {
                return '<button class="bulk-status-option" data-target="' + target + '">' +
                    '<span class="bulk-status-option-dot" style="background:' + _STATUS_COLORS[target] + '"></span>' + t(_STATUS_LABEL_KEYS[target]) + '</button>';
            }).join('') +
        '</div>';
    var popup = document.getElementById('action-popup');
    popup.querySelectorAll('.bulk-status-option').forEach(function(b) {
        b.addEventListener('click', function() {
            closeActionPopup();
            var target = b.getAttribute('data-target');
            if (_isTwoStateTab(tab)) {
                try { _applyTwoStateStatus(form, tab, target); } catch (e) { console.error('Single status (' + tab + '):', e); }
                _lastLocalSaveTs = Date.now();
                _showSavedFormsDirectly(tab);
                showNotificationModal(t('bulk_marked', 1, t(_STATUS_LABEL_KEYS[target]).toLowerCase()), true);
                return;
            }
            _applySingleStatus(form, target);
        });
    });
    popup.classList.add('active');
}
function _applySingleStatus(form, target) {
    var saved = safeParseJSON(STORAGE_KEY, []);
    var archived = safeParseJSON(ARCHIVE_KEY, []);
    try { _applyFormStatus(form, target, saved, archived); } catch (e) { console.error('Single status:', e); }
    safeSetItem(STORAGE_KEY, JSON.stringify(saved));
    safeSetItem(ARCHIVE_KEY, JSON.stringify(archived));
    _lastLocalSaveTs = Date.now();
    loadedForms = [];
    _showSavedFormsDirectly();
    var labelKey = target === 'sendt' ? 'status_sendt'
        : target === 'ferdig' ? 'status_ferdig' : 'status_lagret';
    showNotificationModal(t('bulk_marked', 1, t(labelKey).toLowerCase()), true);
}

// ── Eksport av ÉN lagret skjema (fra 3-prikker-menyen) ──────────────────────
// Samme valg som eksport-popupen ellers: Last ned / Del × PDF / PNG.
function _tabFormType(tab) { return tab === 'service' ? 'service' : tab === 'kappe' ? 'kappe' : tab === 'kvittering' ? 'kvittering' : 'ordreseddel'; }

// Bygg PDF-doc for et lagret skjema (uavhengig av fane). Service/kappe laster
// data midlertidig inn i DOM (build leser DOM) og gjenoppretter etterpå.
async function _buildPdfForTab(form, tab) {
    if (tab === 'kvittering') return await buildKvitteringPdfDoc(form);
    if (tab === 'service') {
        var prevS = null; try { prevS = getServiceFormData(); } catch (e) {}
        setServiceFormData(form);
        var d = await buildServicePdfDoc(form);
        if (prevS) { try { setServiceFormData(prevS); } catch (e) {} }
        return d;
    }
    if (tab === 'kappe') {
        var prevK = null; try { prevK = getKappeFormData(); } catch (e) {}
        setKappeFormData(form);
        var dk = await buildKappePdfDoc(form);
        if (prevK) { try { setKappeFormData(prevK); } catch (e) {} }
        return dk;
    }
    return await buildOrdreseddelPdfDoc(form);
}

// Raster-canvas for PNG-eksport av et lagret skjema (PNG er bilde → html2canvas).
async function _renderOwnCanvasFromData(form) {
    var prev = null; try { prev = getFormDataSnapshot(); } catch (e) {}
    var restoreView = _forceViewVisible('view-form');
    try {
        setFormData(form);
        await new Promise(function(r) { requestAnimationFrame(function() { requestAnimationFrame(r); }); });
        return await renderFormToCanvas();
    } finally {
        restoreView();
        if (prev) { try { setFormData(JSON.parse(prev)); } catch (e) {} }
    }
}
async function _canvasForTab(form, tab) {
    if (tab === 'service') return await _renderServiceCanvasFromData(form);
    if (tab === 'kappe') return await _renderKappeCanvasFromData(form);
    return await _renderOwnCanvasFromData(form);
}

async function _singleFormExport(form, tab, share, png, markFerdig) {
    var loading = document.getElementById('loading');
    if (loading) loading.classList.add('active');
    var type = _tabFormType(tab);
    var didShare = false;
    try {
        if (!png) {
            var pdf = await _buildPdfForTab(form, tab);
            var nameP = _filenameForForm(form, 0, type, 'pdf');
            if (share) {
                var blob = pdf.output('blob');
                var fileP = new File([blob], nameP, { type: 'application/pdf' });
                if (loading) loading.classList.remove('active');
                didShare = (await _safeShare([fileP], _singleShareText(form, type))) === 'shared';
            } else { pdf.save(nameP); }
        } else {
            var canvas = await _canvasForTab(form, tab);
            var nameG = _filenameForForm(form, 0, type, 'png');
            if (share) {
                var durl = canvas.toDataURL('image/png');
                var res = await fetch(durl); var blobG = await res.blob();
                var fileG = new File([blobG], nameG, { type: 'image/png' });
                if (loading) loading.classList.remove('active');
                didShare = (await _safeShare([fileG], _singleShareText(form, type))) === 'shared';
            } else {
                var a = document.createElement('a');
                a.download = nameG; a.href = canvas.toDataURL('image/png'); a.click();
            }
        }
    } catch (e) {
        showNotificationModal(t('export_pdf_error') + (e && e.message ? e.message : e));
    } finally {
        if (loading) loading.classList.remove('active');
    }
    // Fullført deling → sendt. Samme regel som i det åpne skjemaet og i
    // fler-valg-eksporten; her manglet den, så et skjema delt fra Lagret-lista
    // ble liggende som utkast (gul prikk).
    if (didShare) _promoteListFormToSent(form, tab, markFerdig);
}
window._singleFormExport = _singleFormExport;

// Eksport-popup for ÉN lagret skjema. _singleExportCtx holder valgt form+fane.
var _singleExportCtx = null;
function _showSingleExportMenu(savedItem) {
    if (!savedItem || !savedItem._formData) return;
    _singleExportCtx = { savedItem: savedItem, form: savedItem._formData, tab: _savedItemTab(savedItem) };
    var popup = document.getElementById('action-popup');
    _actionPopupBack(function() { showSavedItemMenu(savedItem); });   // tilbake → 3-prikker
    document.getElementById('action-popup-title').textContent = t('export_title');
    var dl = '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M7 10l5 5 5-5M12 15V3"/></svg>';
    var sh = '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><line x1="8.59" y1="13.51" x2="15.42" y2="17.49"/><line x1="15.41" y1="6.51" x2="8.59" y2="10.49"/></svg>';
    var canShare = !!(navigator.share && navigator.canShare);
    function shareBtn(png) {
        var lbl = png ? 'PNG' : 'PDF';
        if (!canShare) return '<button class="confirm-btn-ok" style="background:#E8501A;opacity:0.5;cursor:not-allowed" onclick="showNotificationModal(t(\'share_not_supported\'))">' + sh + ' ' + lbl + '</button>';
        return '<button class="confirm-btn-ok" style="background:#E8501A" onclick="closeActionPopup(); _singleFormExport(_singleExportCtx.form, _singleExportCtx.tab, true, ' + (png ? 'true' : 'false') + ', ' + mf + ')">' + sh + ' ' + lbl + '</button>';
    }
    // Tekst-seksjonen gjelder bare kappeskjema, som eneste skjematype har en
    // kort nok bestillingsliste til å stå som ren e-posttekst.
    var textSectionHtml = (_singleExportCtx.tab === 'kappe') ? _kappeTextSectionHtml(true) : '';
    // «Merk som ferdig» — kun ordreseddel (3-tilstands status), og kun når
    // skjemaet ikke allerede er lukket.
    var showFerdig = _singleExportCtx.tab === 'own' && !_isFormClosed(_singleExportCtx.form);
    var mf = showFerdig ? "document.getElementById('export-mark-ferdig')?.checked" : 'false';
    var ferdigCheckboxHtml = showFerdig
        ? '<label style="display:flex;align-items:center;gap:10px;margin-bottom:12px;cursor:pointer;font-size:14px;padding:4px 0">' +
              '<input type="checkbox" id="export-mark-ferdig" style="width:22px;height:22px;accent-color:#E8501A;flex-shrink:0">' +
              escapeHtml(t('export_mark_ferdig_label')) +
          '</label>'
        : '';
    // Kvittering er selv et bilde i en PDF → bare PDF (PNG gir ingen mening).
    var pdfOnly = _singleExportCtx.tab === 'kvittering';
    document.getElementById('action-popup-buttons').innerHTML = ferdigCheckboxHtml +
        '<div style="font-size:13px;font-weight:600;color:#555;margin-bottom:4px">' + t('export_download') + '</div>' +
        '<div class="confirm-modal-buttons" style="margin-bottom:12px">' +
            '<button class="confirm-btn-ok" style="background:#333" onclick="closeActionPopup(); _singleFormExport(_singleExportCtx.form, _singleExportCtx.tab, false, false)">' + dl + ' PDF</button>' +
            (pdfOnly ? '' : '<button class="confirm-btn-ok" style="background:#333" onclick="closeActionPopup(); _singleFormExport(_singleExportCtx.form, _singleExportCtx.tab, false, true)">' + dl + ' PNG</button>') +
        '</div>' +
        '<div style="font-size:13px;font-weight:600;color:#555;margin-bottom:4px">' + t('btn_share') + '</div>' +
        '<div class="confirm-modal-buttons">' + shareBtn(false) + (pdfOnly ? '' : shareBtn(true)) + '</div>' +
        textSectionHtml;
    popup.classList.add('active');
}
window._showSingleExportMenu = _showSingleExportMenu;

function _buildSavedItemHtml(item, index) {
    var ordrenr = item.ordreseddelNr || '';
    var dato = formatDateWithTime(item.savedAt);
    var isSent = item._isSent;
    var dotCls = _statusDotClass(item);
    var dot = '<span class="status-dot ' + dotCls + '"></span>';
    // Ingen status-knapp i lista — status vises kun via prikken (oransje/blå/grønn).
    // Markering skjer i skjemaet (Merk sendt / Merk ferdig).
    var statusBtn = '';
    var clipBtn = '<button class="saved-item-action-btn clipboard" title="' + t('copy_btn') + '">' + copyIcon + '</button>';
    var dupBtn = '<button class="saved-item-action-btn copy" title="' + t('duplicate_btn') + '">' + duplicateIcon + '</button>';
    var deleteBtn = isSent
        ? '<button class="saved-item-action-btn delete disabled" title="' + t('delete_btn') + '">' + deleteIcon + '</button>'
        : '<button class="saved-item-action-btn delete" title="' + t('delete_btn') + '">' + deleteIcon + '</button>';
    // Uke = arbeidsperioden lagret i ordreseddelen (item.dato). Bruker-persistent:
    // satt ved oppretting, bevart ved åpning. Vises i FØRSTE rad (ved siden av nr
    // og dato), så prosjektnr + prosjektnavn får hele andre rad for seg selv.
    // Strip ev. ledende «Uke» fra eldre data så vi ikke får «Uke Uke 17».
    var ukeVal = (item.dato != null) ? String(item.dato).trim().replace(/^uke\s*/i, '').trim() : '';
    var ukeInline = ukeVal ? '<span class="saved-item-uke-inline">' + escapeHtml(t('label_uke') + ' ' + ukeVal) + '</span>' : '';
    // Andre rad: kun prosjektnr + prosjektnavn (egen rad → trenger ikke wrappe).
    var subtitle = '';
    var parts = [];
    if (item.prosjektnr) parts.push(escapeHtml(item.prosjektnr));
    if (item.prosjektnavn) parts.push(escapeHtml(item.prosjektnavn));
    if (parts.length) {
        subtitle = '<div class="saved-item-subtitle">' + parts.join('<span class="bil-history-sep"></span>') + '</div>';
    }
    // Ekspanderbar beskrivelse: samle ordre-/bestillings-beskrivelsene fra skjemaet, så
    // bruker raskt kan se HVA ordreseddelen handler om uten å åpne den. Vises kun når det
    // finnes minst én beskrivelse (ellers ingen ekspander-knapp).
    var _descLines = [];
    (Array.isArray(item.orders) ? item.orders : []).forEach(function (o) {
        var d = (o && o.description != null) ? String(o.description).trim() : '';
        if (d) _descLines.push(d);
    });
    var expandBtn = _descLines.length
        ? '<button class="saved-item-action-btn saved-item-expand-btn" title="' + t('show_description') + '" aria-label="' + t('show_description') + '"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg></button>'
        : '';
    // Hver bestilling som eget nummerert kort → tydelig atskilt (ikke sammenflytende
    // avsnitt). Nummer vises kun når det er flere bestillinger.
    var _multiDesc = _descLines.length > 1;
    var detailsHtml = _descLines.length
        ? '<div class="saved-item-details" hidden>' +
              _descLines.map(function (d, i) {
                  var num = _multiDesc ? '<span class="saved-item-order-num">' + (i + 1) + '</span>' : '';
                  return '<div class="saved-item-order">' + num + '<span class="saved-item-order-text">' + escapeHtml(d) + '</span></div>';
              }).join('') +
          '</div>'
        : '';
    return '<div class="saved-item" data-index="' + index + '">' +
        '<div class="saved-item-info">' +
            '<div class="saved-item-header">' +
                '<div class="saved-item-row1">' + dot +
                    '<span class="saved-item-nr">' + (escapeHtml(ordrenr) || t('no_name')) + '</span>' +
                    ukeInline +
                    (dato ? '<span class="saved-item-date-inline">' + escapeHtml(dato) + '</span>' : '') +
                '</div>' +
            '</div>' +
            subtitle +
        '</div>' +
        _savedItemActionsHtml(statusBtn + clipBtn + dupBtn + deleteBtn, expandBtn) +
        detailsHtml +
    '</div>';
}

// Vis/skjul beskrivelse-panelet på en lagret-rad (ekspander-knappen).
function _toggleSavedItemDetails(item) {
    var details = item.querySelector('.saved-item-details');
    if (!details) return;
    var willExpand = details.hasAttribute('hidden');
    if (willExpand) details.removeAttribute('hidden'); else details.setAttribute('hidden', '');
    item.classList.toggle('expanded', willExpand);
}

function renderSavedFormsList(forms, append, hasMore) {
    // Fasit-synk før visning: prosjektet i Innstillinger eier skrivemåten.
    forms = syncFormsWithProjects(forms, 'full');
    var listEl = document.getElementById('saved-list');
    // Remove existing "load more" button
    var existingBtn = listEl.querySelector('.load-more-btn');
    if (existingBtn) existingBtn.remove();

    if (!append) {
        if (!forms || forms.length === 0) {
            listEl.innerHTML = '<div class="no-saved">' + t('no_saved_forms') + '</div>';
            return;
        }
        window.loadedForms = forms;
        listEl.innerHTML = forms.map(function(item, i) { return _buildSavedItemHtml(item, i); }).join('');
    } else {
        // «Last flere»: legg til ny side, men RE-SORTER hele lista så status-
        // grupperingen (utkast→sendt→ikke godkjent→godkjent) holder på tvers av
        // sider — ellers ville den nye siden bare blitt limt på slutten. Full
        // re-render siden posisjoner kan endre seg.
        window.loadedForms = window.loadedForms.concat(forms).sort(_savedFormsStatusCompare);
        listEl.innerHTML = window.loadedForms.map(function(item, i) { return _buildSavedItemHtml(item, i); }).join('');
    }

    // Attach form data to DOM elements
    listEl.querySelectorAll('.saved-item').forEach(function(el, i) {
        el._formData = window.loadedForms[i];
    });

    // Add "Load more" button if there are more forms
    if (hasMore) {
        listEl.insertAdjacentHTML('beforeend', '<button class="load-more-btn" onclick="loadMoreSavedForms()">' + t('load_more') + '</button>');
    }

    // Hold markerte rader og "Velg alle"-knapp i synk etter re-rendering
    if (_selectMode) {
        listEl.querySelectorAll('.saved-item').forEach(function(el) {
            var idx = parseInt(el.getAttribute('data-index'), 10);
            if (!isNaN(idx) && _selectedSet.has(idx)) el.classList.add('selected');
        });
        updateSelectionUI();
    }
}

async function loadMoreSavedForms() {
    var btn = document.querySelector('#saved-list .load-more-btn');
    if (btn) btn.textContent = '...';
    var newForms = [];
    if (_savedHasMore && _savedLastDoc) {
        var result = await getSavedForms(_savedLastDoc);
        _savedLastDoc = result.lastDoc;
        _savedHasMore = result.hasMore;
        newForms = newForms.concat(result.forms.map(function(f) { return Object.assign({}, f, { _isSent: false }); }));
    }
    if (_sentHasMore && _sentLastDoc) {
        var result2 = await getSentForms(_sentLastDoc);
        _sentLastDoc = result2.lastDoc;
        _sentHasMore = result2.hasMore;
        newForms = newForms.concat(result2.forms.map(function(f) { return Object.assign({}, f, { _isSent: true }); }));
    }
    newForms.sort(function(a, b) { return _cmpIsoDesc(a.savedAt, b.savedAt); });
    renderSavedFormsList(newForms, true, _savedHasMore || _sentHasMore);
}

// ── Skjematyper: Hjem-knapp → liste for typen (med «+ Ny») ─────────────────────
// Lagret er ikke lenger en egen side med faner i toolbaren: hver type har sin liste,
// åpnet fra den delte knappen på Hjem (navnet = lista, «+» = nytt skjema). Lista er
// den samme saved-modal-en som før (søk, Velg, eksport), bare uten fane-raden og
// med typens navn som tittel.
function _hentTitle(tab) {
    tab = tab || _hentLastTab;
    if (tab === 'servicebil' || tab === 'service') return t('tab_servicebil');
    if (tab === 'kappe') return t('hent_title_kappe');
    return t('hent_title_own');
}
function openFormList(tab) {
    if (tab === 'sjekkliste') { sjOpenOverview(); return; }
    showSavedForms(tab);
}
window.openFormList = openFormList;
// «+ Ny» i lista: nytt skjema av typen lista viser. Tilbake fra skjemaet → lista.
function hentNewForm() {
    var tab = _hentLastTab || 'own';
    if (_selectMode) toggleSelectMode();
    closeAllModals();
    // closeAllModals nullstiller fanen i økten — tilbake-knappen i skjemaet leser den.
    sessionStorage.setItem('firesafe_hent_tab', tab);
    _hentLastTab = tab;
    if (tab === 'servicebil' || tab === 'service') openServicebilView();
    else if (tab === 'kappe') openNewKappeForm();
    else closeTemplateModal();
}
window.hentNewForm = hentNewForm;
// Utkast-teller på Hjem-knappene. Leser den lokale cachen (ingen nettverk) og kjøres
// etter at Hjem er tegnet, så trykket på Hjem aldri venter på den.
function _homeRenderCounts() {
    // Undertekst på raden: «N utkast» (oransje) når typen har utkast, ellers beskrivelsen.
    var setCount = function (id, n) {
        var el = document.getElementById('home-count-' + id);
        if (!el) return;
        el.textContent = n ? t(n === 1 ? 'home_drafts_one' : 'home_drafts_many').replace('{0}', n >= 50 ? '50+' : n)
                           : t(el.getAttribute('data-desc-key'));
        el.classList.toggle('has-drafts', !!n);
    };
    setCount('sjekkliste', 0);
    setCount('own', safeParseJSON(STORAGE_KEY, []).length);
    setCount('servicebil', safeParseJSON(SERVICE_STORAGE_KEY, []).length);
    setCount('kappe', safeParseJSON(KAPPE_STORAGE_KEY, []).length);
}
window._homeRenderCounts = _homeRenderCounts;

function showSavedForms(tab) {
    // tab er valgfri: settes ved tilbake-navigasjon fra et skjema så vi lander på
    // fanen man kom fra (Ordreseddel/Servicebil/Kappeskjema). Uten arg = 'own'
    // (fersk åpning fra verktøylinja). _showSavedFormsDirectly defaulter til 'own'.
    if (isOnFormPage() && hasUnsavedChanges()) {
        _showUnsavedGuard(function() { _showSavedFormsDirectly(tab); });
        return;
    }
    _showSavedFormsDirectly(tab);
}

function _mergeAndDedup(saved, sent) {
    // Ved duplikat ordreseddelNr: behold nyeste versjon (basert på savedAt)
    var all = saved.concat(sent);
    var byNr = {};
    for (var i = 0; i < all.length; i++) {
        var nr = all[i].ordreseddelNr;
        if (!byNr[nr] || (all[i].savedAt || '') > (byNr[nr].savedAt || '')) {
            byNr[nr] = all[i];
        }
    }
    var result = [];
    for (var key in byNr) result.push(byNr[key]);
    // Gruppér på status (utkast → sendt → ikke godkjent → godkjent); nyeste først.
    return result.sort(_savedFormsStatusCompare);
}

function _showSavedFormsDirectly(tab) {
    closeAllModals();
    if (window.location.hash !== '#hent') {
        window.location.hash = 'hent';
    }

    // Nullstill søkefelt hver gang Skjemaer åpnes
    var savedSearch = document.getElementById('saved-search');
    if (savedSearch) savedSearch.value = '';
    var serviceSearch = document.getElementById('service-search');
    if (serviceSearch) serviceSearch.value = '';
    var kvSearchEl = document.getElementById('kvittering-search');
    if (kvSearchEl) kvSearchEl.value = '';
    _kvFormsAll = null;
    updateSearchClearBtn('saved-search');
    updateSearchClearBtn('service-search');
    updateSearchClearBtn('kvittering-search');

    // Show cached data immediately
    const cachedSaved = safeParseJSON(STORAGE_KEY, []);
    const cachedSent = safeParseJSON(ARCHIVE_KEY, []);
    const cachedForms = _mergeAndDedup(
        cachedSaved.map(f => ({ ...f, _isSent: false })),
        cachedSent.map(f => ({ ...f, _isSent: true }))
    );
    renderSavedFormsList(cachedForms);

    showView('saved-modal');
    document.body.classList.add('saved-modal-open');
    updateToolbarState();
    document.getElementById('saved-list').scrollTop = 0;

    switchHentTab(_accHentTab(tab || 'own'));

    // Refresh from Firestore in background
    if (currentUser && db) {
        Promise.all([getSavedForms(), getSentForms()]).then(function([savedResult, sentResult]) {
            // Hopp over Firestore-overskriving rett etter lokal save/markering
            // for å unngå race condition der stale Firestore-data overskriver localStorage
            if (Date.now() - _lastLocalSaveTs < 5000) return;
            _savedLastDoc = savedResult.lastDoc;
            _sentLastDoc = sentResult.lastDoc;
            _savedHasMore = savedResult.hasMore;
            _sentHasMore = sentResult.hasMore;
            safeSetItem(STORAGE_KEY, JSON.stringify(savedResult.forms.slice(0, 50)));
            safeSetItem(ARCHIVE_KEY, JSON.stringify(sentResult.forms.slice(0, 50)));
            window.loadedForms = _mergeAndDedup(
                savedResult.forms.map(f => ({ ...f, _isSent: false })),
                sentResult.forms.map(f => ({ ...f, _isSent: true }))
            );
            // Only update if still on saved-modal
            if (document.body.classList.contains('saved-modal-open')) {
                renderSavedFormsList(window.loadedForms, false, _savedHasMore || _sentHasMore);
            }
        }).catch(function(e) { console.error('Refresh saved forms:', e); });
    }
}

function setFormReadOnly(readOnly) {
    // Disable all form fields
    const fields = document.querySelectorAll('#mobile-form input, #mobile-form textarea, #mobile-form select, #form-container input, #form-container textarea, #form-container select');
    fields.forEach(el => el.disabled = readOnly);

    // Signering-dato er alltid disabled (system-styrt — alltid dagens for ny/draft, bevarer historisk for sendt)
    var sd = document.getElementById('signering-dato');
    var msd = document.getElementById('mobile-signering-dato');
    if (sd) sd.disabled = true;
    if (msd) msd.disabled = true;

    // Disable save button in header
    var headerSaveBtn = document.getElementById('header-save-btn');
    if (headerSaveBtn) headerSaveBtn.disabled = readOnly;

    // Show/hide sent banner
    document.getElementById('sent-banner').style.display = readOnly ? 'block' : 'none';

    // Disable signature editing
    const signaturePreview = document.getElementById('mobile-signature-preview');
    if (signaturePreview) {
        signaturePreview.style.pointerEvents = readOnly ? 'none' : '';
        signaturePreview.style.opacity = readOnly ? '0.6' : '';
    }

    // Disable "add order" button
    const addOrderBtn = document.querySelector('.mobile-add-line-btn');
    if (addOrderBtn) {
        addOrderBtn.disabled = readOnly;
        addOrderBtn.style.opacity = readOnly ? '0.5' : '';
    }

    // Disable all "delete order" buttons
    if (readOnly) {
        document.querySelectorAll('.mobile-order-header-delete').forEach(btn => {
            btn.disabled = true;
            btn.style.opacity = '0.3';
            btn.style.pointerEvents = 'none';
        });
    } else {
        document.querySelectorAll('.mobile-order-header-delete').forEach(btn => {
            btn.style.opacity = '';
            btn.style.pointerEvents = '';
        });
        updateOrderDeleteStates();
    }

    // Disable all "add material" buttons
    document.querySelectorAll('.mobile-add-mat-btn').forEach(btn => {
        btn.disabled = readOnly;
        btn.style.opacity = readOnly ? '0.5' : '';
    });

    // Disable clicking on material rows to edit
    document.querySelectorAll('.mobile-material-row').forEach(row => {
        row.style.pointerEvents = readOnly ? 'none' : '';
    });

}

function loadFormDirect(formData) {
    if (!formData) return;
    setFormData(formData);

    // Signering-dato: alltid dagens for draft (system-styrt, ikke editerbart),
    // bevares historisk kun for sendte skjema.
    // Uke: bevares ALLTID slik den ble lagret (representerer når jobben ble
    // utført — ikke når skjemaet sist ble åpnet). Uke settes bare ved
    // oppretting (nytt skjema/duplisering/clearForm) og kan endres manuelt
    // av brukeren før lagring.
    if (!formData._isSent) {
        _setSigneringDatoToday();
    }

    updateFormTypeChip();
    lastSavedData = getFormDataSnapshot();
    const isSent = !!formData._isSent;
    // Show sent banner but keep form editable
    document.getElementById('sent-banner').style.display = isSent ? 'block' : 'none';
    sessionStorage.setItem('firesafe_current_sent', isSent ? '1' : '');
    sessionStorage.setItem('firesafe_current_status', (isSent ? (formData.status || 'ferdig') : ''));
    _updateFormStatusButtons();
    closeModal();
    // Set hash based on form type
    window.location.hash = 'skjema';
    sessionStorage.setItem('firesafe_form_type', 'own');
    sessionStorage.setItem('firesafe_current', JSON.stringify(getFormData()));
    // Update form header title
    document.getElementById('form-header-title').textContent = t('form_title');
    // Skjema skal ALLTID åpnes fra toppen. closeModal() viser #view-form,
    // men `body.saved-modal-open` fjernes først etterpå — så en synkron
    // scroll-reset her treffer mens viewet ennå er display:none og fester
    // seg ikke. Nullstill etter at viewet faktisk er synlig (neste frame).
    _resetFormViewScroll();
}

// Nullstill scroll-posisjon på det aktive form-viewet (scroll-containeren
// er #view-form selv, jf. .container.form-view{overflow-y:auto}).
function _resetFormViewScroll() {
    function doReset() {
        var vf = document.getElementById('view-form');
        if (vf) vf.scrollTop = 0;
        window.scrollTo(0, 0);
    }
    doReset();
    requestAnimationFrame(function() {
        doReset();
        requestAnimationFrame(doReset);
    });
}

async function duplicateFormDirect(form) {
    if (!form) return;

    setFormData(form);
    // Tøm ordrenummer og sett nytt
    document.getElementById('ordreseddel-nr').value = '';
    document.getElementById('mobile-ordreseddel-nr').value = '';
    autoFillOrderNumber();

    // Uke og signering-dato er alltid dagens (system-styrt)
    _setUkeToToday();
    _setSigneringDatoToday();

    // Tøm kundens underskrift
    document.getElementById('kundens-underskrift').value = '';
    document.getElementById('mobile-kundens-underskrift').value = '';
    clearSignaturePreview();

    // Et duplikat er ALLTID et ferskt utkast — nullstill sendt/ferdig-state.
    // (Dupliserer du et SENDT skjema, hang firesafe_current_sent igjen, og
    // saveForm hoppet over navigeringen til lagrede-listen + viste sendt-banner.)
    sessionStorage.removeItem('firesafe_current_sent');
    sessionStorage.removeItem('firesafe_current_status');
    var _sb = document.getElementById('sent-banner');
    if (_sb) _sb.style.display = 'none';
    if (typeof _updateFormStatusButtons === 'function') _updateFormStatusButtons();

    // Reset bestillinger til 1 tomt ordrekort
    const container = document.getElementById('mobile-orders');
    container.innerHTML = '';
    container.appendChild(createOrderCard({ description: '', materials: [], timer: '' }, true));
    updateOrderDeleteStates();
    document.getElementById('work-lines').innerHTML = '';

    lastSavedData = null;
    setFormReadOnly(false);
    // Bestillingene ble nettopp tømt → oppdater «Timer uke X»-chipen så den ikke
    // henger igjen på det dupliserte skjemaets timer (_setUkeToToday kjørte FØR
    // tømmingen og fanget gamle timer).
    if (typeof updateTimerChip === 'function') updateTimerChip();
    closeModal();
    window.location.hash = 'skjema';
    sessionStorage.setItem('firesafe_form_type', 'own');
    sessionStorage.setItem('firesafe_current', JSON.stringify(getFormData()));
    // Update form header title
    document.getElementById('form-header-title').textContent = t('form_title');
    _resetFormViewScroll();
    showNotificationModal(t('duplicated_success'), true);
}

function deleteFormDirect(form) {
    if (!form) return;
    const isSent = form._isSent;
    const confirmMsg = isSent ? t('delete_sent_confirm') : t('delete_confirm');

    showConfirmModal(confirmMsg, function() {
        const col = isSent ? 'archive' : 'forms';
        const lsKey = isSent ? ARCHIVE_KEY : STORAGE_KEY;

        // Optimistic removal: update local state + DOM immediately
        removeFromOrderNumberIndex(form.ordreseddelNr);
        var arrIdx = window.loadedForms.findIndex(function(f) { return f.id === form.id; });
        if (arrIdx !== -1) window.loadedForms.splice(arrIdx, 1);
        var lsList = safeParseJSON(lsKey, []);
        var lsIdx = lsList.findIndex(function(f) { return f.id === form.id; });
        if (lsIdx !== -1) { lsList.splice(lsIdx, 1); safeSetItem(lsKey, JSON.stringify(lsList)); }
        // Remove DOM element
        document.querySelectorAll('#saved-list .saved-item').forEach(function(el) {
            if (el._formData && el._formData.id === form.id) el.remove();
        });
        // Show empty message if no items left
        if (window.loadedForms.length === 0) {
            document.getElementById('saved-list').innerHTML = '<div class="no-saved">' + t('no_saved_forms') + '</div>';
        }

        _lastLocalSaveTs = Date.now();

        enqueueUserDocDelete(col, form.id, 'Delete');
    });
}

function closeModal() {
    showView('view-form');
    document.body.classList.remove('saved-modal-open');
    updateToolbarState();
    document.getElementById('saved-search').value = '';
    var serviceSearch = document.getElementById('service-search');
    if (serviceSearch) serviceSearch.value = '';
    updateSearchClearBtn('saved-search');
    updateSearchClearBtn('service-search');
    // Reset to own tab
    switchHentTab('own');
    sessionStorage.removeItem('firesafe_hent_tab');
    // Clear URL hash
    history.replaceState(null, '', window.location.pathname);
}

function switchHentTab(tab) {
    if (_selectMode) toggleSelectMode();
    // Migrer 'service' (gammel fane som er fjernet) til 'servicebil'
    if (tab === 'service') tab = 'servicebil';
    // Kvittering-fanen er fjernet (kvitteringer ligger i Timebok) → Egne.
    if (tab === 'kvittering') tab = 'own';
    sessionStorage.setItem('firesafe_hent_tab', tab);
    _hentLastTab = tab;
    var hentTitleEl = document.getElementById('saved-modal-title');
    if (hentTitleEl && !_selectMode) hentTitleEl.textContent = _hentTitle(tab);
    const tabs = document.querySelectorAll('#saved-modal .modal-tab');
    tabs.forEach(t => t.classList.remove('active'));

    const savedList = document.getElementById('saved-list');
    const serviceList = document.getElementById('service-list');
    const kappeList = document.getElementById('kappe-list');
    const bilList = document.getElementById('bil-history-list');
    const ownSearch = document.getElementById('own-search-wrap');
    const serviceSearch = document.getElementById('service-search-wrap');
    const kappeSearch = document.getElementById('kappe-search-wrap');
    const kvList = document.getElementById('kvittering-list');
    const kvSearch = document.getElementById('kvittering-search-wrap');

    savedList.style.display = 'none';
    if (serviceList) serviceList.style.display = 'none';
    if (kappeList) kappeList.style.display = 'none';
    if (bilList) bilList.style.display = 'none';
    ownSearch.style.display = 'none';
    if (serviceSearch) serviceSearch.style.display = 'none';
    if (kappeSearch) kappeSearch.style.display = 'none';
    if (kvList) kvList.style.display = 'none';
    if (kvSearch) kvSearch.style.display = 'none';

    if (tab === 'own') {
        tabs[0].classList.add('active');
        savedList.style.display = '';
        ownSearch.style.display = '';
        savedList.scrollTop = 0;
    } else if (tab === 'servicebil') {
        // Kombinert visning: pafylling (INNTAK) + sendte service-skjemaer (UTTAK)
        if (tabs[1]) tabs[1].classList.add('active');
        if (bilList) { bilList.style.display = ''; bilList.scrollTop = 0; }
        renderBilHistory();
        _bilHistoryRendered = true;
        // Refresh uttak-data fra Firebase i bakgrunnen og re-render
        _hentRefreshServicebil();
    } else if (tab === 'kappe') {
        if (tabs[2]) tabs[2].classList.add('active');
        if (kappeList) { kappeList.style.display = ''; kappeList.scrollTop = 0; }
        if (kappeSearch) kappeSearch.style.display = '';
        loadKappeTab();
    } else if (tab === 'kvittering') {
        if (tabs[3]) tabs[3].classList.add('active');
        if (kvList) { kvList.style.display = ''; kvList.scrollTop = 0; }
        if (kvSearch) kvSearch.style.display = '';
        loadKvitteringTab();
    }
    // Chip-raden kan være bredere enn skjermen → rull aktiv chip helt inn
    // (bare horisontalt i raden; siden selv skal ikke flytte seg).
    var activeTab = document.querySelector('#saved-modal .modal-tab.active');
    var tabRow = activeTab && activeTab.parentElement;
    if (tabRow && tabRow.scrollWidth > tabRow.clientWidth) {
        var pad = 15;
        var left = activeTab.offsetLeft - tabRow.offsetLeft;
        if (left - pad < tabRow.scrollLeft) tabRow.scrollLeft = left - pad;
        else if (left + activeTab.offsetWidth + pad > tabRow.scrollLeft + tabRow.clientWidth) {
            tabRow.scrollLeft = left + activeTab.offsetWidth + pad - tabRow.clientWidth;
        }
    }
    _updateSavedTabsHint();
    // Tab-switch endrer modal-body display via inline-style. MutationObserveren
    // i tastatur-handleren overvåker class, ikke style — så vi må eksplisitt
    // trigge applyKeyboardLayout for å re-evaluere hvilken modal-body toolbar
    // skal være i. Uten dette ville toolbar bli stuck i forrige aktive modal-body.
    if (typeof window.applyKeyboardLayout === 'function') window.applyKeyboardLayout();
}

// Chip-raden i Skjemaer: vis tone + pil mot den kanten der flere chips skjuler
// seg (ellers er det umulig å vite at det finnes en fjerde type). Ingenting
// vises når alt får plass (PC/bred skjerm).
function _updateSavedTabsHint() {
    var wrap = document.getElementById('saved-tabs-wrap');
    var row = wrap && wrap.querySelector('.modal-tabs');
    if (!row) return;
    var max = row.scrollWidth - row.clientWidth;
    wrap.classList.toggle('more-left', max > 2 && row.scrollLeft > 2);
    wrap.classList.toggle('more-right', max > 2 && row.scrollLeft < max - 2);
}
function _scrollSavedTabs(dir) {
    var row = document.querySelector('#saved-tabs-wrap .modal-tabs');
    if (!row) return;
    var step = Math.max(80, row.clientWidth * 0.6);
    try { row.scrollBy({ left: dir * step, behavior: 'smooth' }); }
    catch (e) { row.scrollLeft += dir * step; }
}
window._scrollSavedTabs = _scrollSavedTabs;
(function() {
    var row = document.querySelector('#saved-tabs-wrap .modal-tabs');
    if (!row) return;
    row.addEventListener('scroll', _updateSavedTabsHint, { passive: true });
    window.addEventListener('resize', _updateSavedTabsHint);
    // Første visning (prescript kan ha vist Skjemaer før switchHentTab kjører).
    requestAnimationFrame(_updateSavedTabsHint);
})();

// Tilbake-pil i action-popup-header. onBack=funksjon → vis + koble; null → skjul.
function _actionPopupBack(onBack) {
    var b = document.getElementById('action-popup-back');
    if (!b) return;
    if (onBack) { b.style.display = ''; b.onclick = onBack; }
    else { b.style.display = 'none'; b.onclick = null; }
}

function closeActionPopup(e) {
    if (e && e.target !== document.getElementById('action-popup')) return;
    _rememberMenuTop();
    document.getElementById('action-popup').classList.remove('active');
    _actionPopupBack(null);
}
// ── Vindu åpnet fra en meny står der menyen sto (bruker 20-11-2026: «det er ingen grunn for at
// boksen skal endre posisjon fordi jeg trykker ny mappe … slike ting irriterer meg»).
// Velger man noe i en meny (#action-popup) som åpner et navnefelt (#input-modal) eller en
// bekreftelse (#confirm-modal), legges det nye vinduet med TOPPEN der menyen sto — ikke sentrert
// på nytt etter sin egen høyde. Gjelder hele appen (alle menyer → vinduer), ikke bare Dokumenter.
var _lastMenuTop = null;
function _rememberMenuTop() {
    var c = document.querySelector('#action-popup.active .confirm-modal-content');
    _lastMenuTop = c ? { top: c.getBoundingClientRect().top, at: Date.now() } : null;
}
function _anchorToMenu(modalId) {
    var m = document.getElementById(modalId), c = m && m.querySelector('.confirm-modal-content');
    var last = _lastMenuTop; _lastMenuTop = null;
    if (!c || !last || Date.now() - last.at > 600) return;   // ikke åpnet rett fra en meny
    m.classList.add('popup-from-menu');
    c.style.marginTop = '0px';
    var room = window.innerHeight - c.offsetHeight - 16;     // aldri utenfor skjermen nederst
    c.style.marginTop = Math.max(16, Math.min(Math.round(last.top), room)) + 'px';
}
function _unanchorMenu(modalId) {
    var m = document.getElementById(modalId), c = m && m.querySelector('.confirm-modal-content');
    if (m) m.classList.remove('popup-from-menu');
    if (c) c.style.marginTop = '';
}
['input-modal', 'confirm-modal'].forEach(function (id) {
    var show = id === 'input-modal' ? 'showInputModal' : 'showConfirmModal';
    var close = id === 'input-modal' ? 'closeInputModal' : 'closeConfirmModal';
    var s0 = window[show], c0 = window[close];
    if (typeof s0 === 'function') window[show] = function () { _unanchorMenu(id); var r = s0.apply(this, arguments); _anchorToMenu(id); return r; };
    if (typeof c0 === 'function') window[close] = function () { var r = c0.apply(this, arguments); if (!document.getElementById(id).classList.contains('active')) _unanchorMenu(id); return r; };
});

// ─── Preview overlay ────────────────────────────────────────────────────────

function updatePreviewHeaderState(hasSig) {
    var closeBtn = document.querySelector('.preview-close-btn');
    var signBtn = document.querySelector('.preview-sign-btn');
    if (hasSig) {
        closeBtn.textContent = t('btn_done');
        closeBtn.classList.add('done');
        signBtn.innerHTML = '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> ' + t('btn_signed');
        signBtn.classList.add('signed');
    } else {
        closeBtn.innerHTML = '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg> ' + t('btn_close');
        closeBtn.classList.remove('done');
        signBtn.innerHTML = '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/></svg> ' + t('btn_sign');
        signBtn.classList.remove('signed');
    }
}

// Pinch-to-zoom for preview overlay (mobile only)
function initPreviewPinchZoom(scrollEl, fcEl, baseScale) {
    var pinchStartDist = 0;
    var scaleAtPinchStart = baseScale;
    var isPinching = false;

    function getTouchDist(e) {
        var t = e.touches;
        var dx = t[0].clientX - t[1].clientX;
        var dy = t[0].clientY - t[1].clientY;
        return Math.sqrt(dx * dx + dy * dy);
    }

    function onTouchStart(e) {
        if (e.touches.length === 2) {
            isPinching = true;
            pinchStartDist = getTouchDist(e);
            scaleAtPinchStart = window._previewCurrentScale || baseScale;
            e.preventDefault();
        }
    }

    function onTouchMove(e) {
        if (!isPinching || e.touches.length !== 2) return;
        e.preventDefault();

        var dist = getTouchDist(e);
        var ratio = dist / pinchStartDist;
        var newScale = Math.min(Math.max(scaleAtPinchStart * ratio, baseScale), 2);
        var oldScale = window._previewCurrentScale || baseScale;

        // Pinch midpoint relative to scroll container viewport
        var rect = scrollEl.getBoundingClientRect();
        var midX = (e.touches[0].clientX + e.touches[1].clientX) / 2 - rect.left;
        var midY = (e.touches[0].clientY + e.touches[1].clientY) / 2 - rect.top;

        // Save scroll position BEFORE layout changes
        var oldSL = scrollEl.scrollLeft;
        var oldST = scrollEl.scrollTop;

        // Enable horizontal scroll BEFORE changing scale (so scroll range is available)
        if (newScale > baseScale) {
            scrollEl.style.overflowX = 'auto';
        } else {
            scrollEl.style.overflowX = 'hidden';
        }

        // Apply new scale and margins
        window._previewCurrentScale = newScale;
        fcEl.style.transform = 'scale(' + newScale + ')';
        fcEl.style.marginBottom = (-(fcEl.offsetHeight * (1 - newScale))) + 'px';
        fcEl.style.marginRight = (-(fcEl.offsetWidth * (1 - newScale))) + 'px';

        // Force layout reflow so new scroll dimensions are available
        void scrollEl.scrollWidth;

        // Adjust scroll so pinch midpoint stays under fingers
        scrollEl.scrollLeft = (oldSL + midX) * newScale / oldScale - midX;
        scrollEl.scrollTop = (oldST + midY) * newScale / oldScale - midY;
    }

    function onTouchEnd(e) {
        if (e.touches.length < 2) {
            isPinching = false;
        }
    }

    scrollEl.addEventListener('touchstart', onTouchStart, { passive: false });
    scrollEl.addEventListener('touchmove', onTouchMove, { passive: false });
    scrollEl.addEventListener('touchend', onTouchEnd);

    // Store references for cleanup
    window._previewPinchHandlers = {
        el: scrollEl,
        start: onTouchStart,
        move: onTouchMove,
        end: onTouchEnd
    };
}

function cleanupPreviewPinchZoom() {
    var h = window._previewPinchHandlers;
    if (h) {
        h.el.removeEventListener('touchstart', h.start);
        h.el.removeEventListener('touchmove', h.move);
        h.el.removeEventListener('touchend', h.end);
        h.el.style.overflowX = 'hidden';
        window._previewPinchHandlers = null;
    }
    window._previewBaseScale = null;
    window._previewCurrentScale = null;
}

// ── Tilbake = dit du var (hele appen) ──
// Alle tilbakeknapper (header-pilen i hver view + pilen på Innstillinger-undersider)
// går til skjermen du faktisk kom fra — ikke en fast «forelder». Eks.: Timebok →
// ☰ → Timebok-innstillinger → tilbake = Timebok (samme dag/visning), ikke Innstillinger.
// Appen holder sin egen stabel over steder (= hash: '', 'hent', 'timebok',
// 'settings', 'settings/<side>' …) fordi nettleserhistorikken ikke speiler det
// (Hjem bruker replaceState). Alle steds-bytter meldes via _navNote (showView,
// Innstillinger-sider, hashchange); bytter i samme tikk slås sammen til ett steg, så
// mellomsteg (f.eks. #settings før #settings/timebok) aldri blir egne steg.
// Retningen GJETTES IKKE: et bytte er «tilbake» bare når det faktisk er det — appens egen
// tilbakeknapp (_navBack/settingsBack setter _navDir) eller nettleserens/telefonens
// tilbake (løpenummer i history.state, se under). Tilbake = målet og alt over det fjernes
// fra stabelen; alt annet = nytt steg (pushes). (Før ble «samme sted som forrige steg»
// tolket som tilbake: Profil → Timebok → Timebok-innstillinger (= Profil) slettet Timebok
// fra stabelen, og tilbake havnet i Innstillinger.)
// Tom stabel → knappens gamle faste mål (fallback i navigateBack/settingsBack).
var _NAV_KEY = 'firesafe_nav_stack';
var _navDir = 'fwd';   // 'back' når bytte som kommer er et tilbake-steg
// Løpenummer pr. nettleser-historikksteg (history.state._navSeq): pushState → +1,
// replaceState → samme, location.hash = … (nytt steg uten state) → stemples +1.
// popstate til et LAVERE nummer = nettleserens/telefonens tilbake.
var _navSeqCur = (history.state && typeof history.state._navSeq === 'number') ? history.state._navSeq : 0;
(function () {
    var push = history.pushState.bind(history), repl = history.replaceState.bind(history);
    history.pushState = function (state, title, url) {
        _navSeqCur += 1;
        return push(Object.assign({}, state || {}, { _navSeq: _navSeqCur }), title, url);
    };
    history.replaceState = function (state, title, url) {
        return repl(Object.assign({}, state || {}, { _navSeq: _navSeqCur }), title, url);
    };
    if (!(history.state && typeof history.state._navSeq === 'number')) history.replaceState(history.state, '');
    window.addEventListener('popstate', function () {
        var s = history.state && history.state._navSeq;
        if (typeof s !== 'number') {   // location.hash = … → nytt steg fremover
            _navSeqCur += 1;
            history.replaceState(history.state, '');
            return;
        }
        if (s < _navSeqCur) _navDir = 'back';
        _navSeqCur = s;
    });
})();
var _navStack = (function () { try { var a = JSON.parse(sessionStorage.getItem(_NAV_KEY) || '[]'); return Array.isArray(a) ? a : []; } catch (e) { return []; } })();
var _navLoc = window.location.hash.slice(1);
var _navPending = false;
// Servicebil-, kappe- og kvitteringsskjema tømmes når man går fra dem. Et LAGRET skjema
// huskes derfor i stabelen som '<type>:<id>' med den lagrede versjonen (sessionStorage
// _NAV_FORMS_KEY), så tilbake åpner det samme skjemaet igjen. Et nytt skjema som aldri
// ble lagret (forkastet) finnes ikke lenger — bare da står det '<type>' uten id, og
// det steget hoppes over.
var _NAV_NOT_RESTORABLE = { service: 1, kappe: 1, kvittering: 1, 'sjekkliste/ny': 1 };
var _NAV_FORMS_KEY = 'firesafe_nav_forms';
var _navFormStash = null;   // skjemaet som nettopp ble lukket (fanges før det tømmes)
function _navBase(e) { return String(e || '').split(':')[0]; }
// Det åpne skjemaet av typen (lagret versjon) — null hvis det ikke er lagret.
function _navCaptureForm(base) {
    if (base === 'service' && _serviceCurrentId && _serviceLastSavedData) {
        return { entry: 'service:' + _serviceCurrentId, data: _serviceLastSavedData,
            sent: sessionStorage.getItem('firesafe_service_sent') === '1',
            mode: sessionStorage.getItem('firesafe_servicebil_mode') || '' };
    }
    if (base === 'kappe' && _kappeCurrentId && _kappeLastSavedData) {
        return { entry: 'kappe:' + _kappeCurrentId, data: _kappeLastSavedData,
            sent: sessionStorage.getItem('firesafe_kappe_sent') === '1' };
    }
    if (base === 'kvittering' && _kvCurrentId) return { entry: 'kvittering:' + _kvCurrentId };
    return null;
}
// Kalles først i closeServiceView/closeKappeView/closeKvitteringView (før id-en nulles).
function _navStashForm(base) { _navFormStash = _navCaptureForm(base) ? Object.assign({ base: base }, _navCaptureForm(base)) : null; }
function _navFormsMap() { try { return JSON.parse(sessionStorage.getItem(_NAV_FORMS_KEY) || '{}') || {}; } catch (e) { return {}; } }
// Stedet vi forlater → stabel-oppføring (skjema med id hvis det kan gjenopprettes).
function _navEntryFor(loc) {
    if (!_NAV_NOT_RESTORABLE[loc]) return loc;
    var f = (_navFormStash && _navFormStash.base === loc) ? _navFormStash : _navCaptureForm(loc);
    if (!f) return loc;
    var m = _navFormsMap();
    m[f.entry] = { data: f.data || null, sent: !!f.sent, mode: f.mode || '' };
    try { sessionStorage.setItem(_NAV_FORMS_KEY, JSON.stringify(m)); } catch (e) {}
    return f.entry;
}
// Åpne et lagret skjema igjen fra stabel-oppføringen '<type>:<id>'.
function _navRestoreForm(entry) {
    var base = _navBase(entry), id = entry.slice(base.length + 1);
    var p = _navFormsMap()[entry];
    if (base === 'kvittering') {
        var arch = safeParseJSON(KVITTERING_ARCHIVE_KEY, []);
        var kv = safeParseJSON(KVITTERING_STORAGE_KEY, []).concat(arch).find(function (f) { return f.id === id; });
        if (!kv) return false;
        closeAllModals();
        loadKvitteringFormDirect(Object.assign({}, kv, arch.some(function (f) { return f.id === id; }) ? { _isSent: true } : {}));
        return true;
    }
    if (!p || !p.data) return false;
    var d;
    try { d = JSON.parse(p.data); } catch (e) { return false; }
    d.id = id;
    if (p.sent) d._isSent = true;
    closeAllModals();
    if (base === 'service') {
        if (p.mode) { sessionStorage.setItem('firesafe_servicebil_mode', p.mode); _setServicebilMode(p.mode); }
        loadServiceFormDirect(d);
    } else if (base === 'kappe') loadKappeFormDirect(d);
    else return false;
    return true;
}
// Nettleser-/telefon-tilbake til #service/#kappe/#kvittering (skjemaet er lukket): åpne
// skjemaet fra stabelen i stedet for en tom visning. Kalles fra _applyHashNavigation.
function _navTryRestoreForm(hash) {
    var top = _navStack[_navStack.length - 1];
    if (!top || _navBase(top) !== hash || top === hash) return false;
    return _navRestoreForm(top);
}
var _hentLastTab = 'own';   // fanen i Lagret, så tilbake lander på samme fane
function _navNote() {
    if (_navPending) return;
    _navPending = true;
    setTimeout(_navCommit, 0);
}
function _navCommit() {
    _navPending = false;
    var k = window.location.hash.slice(1);
    var back = _navDir === 'back';
    _navDir = 'fwd';
    var stash = _navFormStash;
    _navFormStash = null;
    if (k === _navLoc) return;
    if (back) {
        // Tilbake: fjern målet og alt over det (nettleser-tilbake kan hoppe over steg).
        // Skjema-oppføringer ('service:<id>') matches på typen.
        for (var i = _navStack.length - 1; i >= 0 && _navBase(_navStack[i]) !== k; i--) {}
        if (i !== -1) _navStack.length = i;
    } else {
        _navFormStash = stash;
        _navStack.push(_navEntryFor(_navLoc));
        _navFormStash = null;
        if (_navStack.length > 30) _navStack.shift();
    }
    _navLoc = k;
    try { sessionStorage.setItem(_NAV_KEY, JSON.stringify(_navStack)); } catch (e) {}
    // Rydd lagrede skjema-versjoner som ikke lenger står i stabelen.
    var fm = _navFormsMap(), changed = false;
    Object.keys(fm).forEach(function (e) { if (_navStack.indexOf(e) === -1) { delete fm[e]; changed = true; } });
    if (changed) try { sessionStorage.setItem(_NAV_FORMS_KEY, JSON.stringify(fm)); } catch (e) {}
}
// Funksjon som åpner et sted direkte (uten ulagret-vakt — den tas i _navBack).
function _navOpenFn(k) {
    if (k === '') return _accAllowed('hjem') ? showTemplateModal : null;
    // Lagret skjema ('service:<id>' …): åpne det samme skjemaet igjen.
    if (k.indexOf(':') !== -1) {
        var fb = _navBase(k), fm = _ACC_HASH_MODULE[fb];
        if (fm && !_accAllowed(fm)) return null;
        if (fb !== 'kvittering' && !(_navFormsMap()[k] || {}).data) return null;
        return function () { if (!_navRestoreForm(k)) showTemplateModal(); };
    }
    // Innstillinger allerede åpen (underside → menyen/annen side): bare bytt side.
    var inSettings = document.body.classList.contains('settings-modal-open');
    if (k === 'settings') return inSettings ? showSettingsMenu : _showSettingsDirectly;
    if (k.indexOf('settings/') === 0) {
        var sub = k.split('/')[1];
        if (!_accSettingsPageAllowed(sub)) return null;
        return function () { if (!inSettings) _showSettingsDirectly(); showSettingsPage(sub, true); };
    }
    var m = _ACC_HASH_MODULE[k.split('/')[0]];
    if (m && !_accAllowed(m)) return null;
    if (k === 'hent') return function () { _showSavedFormsDirectly(_hentLastTab); };
    if (k === 'calc') return _showCalculatorDirectly;
    if (k === 'skjema') return function () { _applyHashNavigation('skjema'); window.location.hash = 'skjema'; };
    // Timebok (uka / dagsiden / eksport): tilbake til samme uke/dag (ikke nullstilt til i dag
    // som ved ny åpning). Inne i Timebok (dag → uke) byttes bare visningen.
    if (k === 'timebok' || k.indexOf('timebok/') === 0) return function () {
        var v = document.getElementById('timebok-view');
        var reopen = !(v && v.classList.contains('active'));
        if (reopen) {
            closeAllModals();
            showView('timebok-view');
            if (!_timebokAnchor) _timebokPrepareOpen();
        }
        document.body.classList.add('timebok-view-open');
        if (window.location.hash.slice(1) !== k) window.location.hash = k;
        _timebokApplyHash(k, reopen);
        updateToolbarState();
    };
    // Dokumenter (mappe / prosjekt / visning): inne i viewet byttes bare plasseringen.
    if (k === 'dokumenter' || k.indexOf('dokumenter/') === 0) return function () {
        if (window.location.hash.slice(1) !== k) window.location.hash = k;
        _docsApplyHash(k);
    };
    // Sjekkliste (oversikt / prosjekt / lagret sjekkliste): inne i viewet byttes bare visningen.
    if (k === 'sjekkliste' || k.indexOf('sjekkliste/') === 0) return function () {
        var v = document.getElementById('sjekkliste-view');
        var reopen = !(v && v.classList.contains('active'));
        if (reopen) { closeAllModals(); _sjShowShell(); }
        else document.body.classList.add('sjekkliste-view-open');
        if (window.location.hash.slice(1) !== k) window.location.hash = k;
        _sjApplyHash(k, reopen);
    };
    return null;
}
// Gå ett steg tilbake i stabelen. false = ingenting å gå tilbake til (bruk fallback).
function _navBack() {
    var cur = window.location.hash.slice(1), go = null;
    while (_navStack.length) {
        var k = _navStack[_navStack.length - 1];
        go = (k !== cur && !_NAV_NOT_RESTORABLE[k]) ? _navOpenFn(k) : null;
        if (go) break;
        _navStack.pop();
    }
    try { sessionStorage.setItem(_NAV_KEY, JSON.stringify(_navStack)); } catch (e) {}
    if (!go) return false;
    var curView = document.querySelector('.view.active');
    var closer = { 'service-view': closeServiceView, 'kappe-view': closeKappeView,
        'kvittering-view': closeKvitteringView, 'timebok-view': closeTimebokView,
        'sjekkliste-view': closeSjekklisteView }[curView ? curView.id : ''];
    var run = function () {
        if (_selectMode) toggleSelectMode();
        if (document.activeElement && document.activeElement.blur) document.activeElement.blur();
        if (closer) closer();
        _navDir = 'back';
        go();
        // Meld byttet NÅ (hashchange kommer først i en senere runde — da ville retningen
        // allerede vært nullstilt og tilbake-steget registrert som et nytt steg).
        _navNote();
        setTimeout(function () { _navDir = 'fwd'; }, 0);
    };
    if (isOnFormPage() && hasUnsavedChanges()) _showUnsavedGuard(run); else run();
    return true;
}

function navigateBack() {
    var current = document.querySelector('.view.active');
    var currentId = current ? current.id : '';
    var prev = _previousViewId;

    // Kalkulator-underside: tilbake = kalkulator-menyen (der du var), håndteres under.
    var calcSub = currentId === 'calculator-modal' && Array.prototype.some.call(
        document.querySelectorAll('.calc-page'), function (p) { return p.style.display !== 'none'; });
    if (!calcSub && _navBack()) return;

    // From form view: check unsaved changes, then go to previous.
    // Naviger DIREKTE (_showSavedFormsDirectly) — navigateBack har alt guardet, og
    // showSavedForms ville guardet på nytt → dobbel popup ("Fortsett" virker ikke).
    if (currentId === 'view-form') {
        var target = (prev === 'saved-modal') ? function() { _showSavedFormsDirectly(); } : showTemplateModal;
        if (isOnFormPage() && hasUnsavedChanges()) {
            _showUnsavedGuard(target);
        } else {
            target();
        }
        return;
    }
    // From service view: honor previous view, then go back
    if (currentId === 'service-view') {
        // Husk fanen vi kom fra (settes når skjemaet åpnes; ryddes ikke lenger).
        var serviceBackTab = sessionStorage.getItem('firesafe_hent_tab') || 'own';
        var target = (prev === 'saved-modal')
            ? function() { closeServiceView(); _showSavedFormsDirectly(serviceBackTab); }
            : function() { closeServiceView(); showTemplateModal(); };
        if (isOnFormPage() && hasUnsavedChanges()) {
            _showUnsavedGuard(target);
        } else {
            target();
        }
        return;
    }
    // From kappe view: honor previous view, then go back (samme mønster som service)
    if (currentId === 'kappe-view') {
        // Husk fanen vi kom fra (settes når skjemaet åpnes; ryddes ikke lenger).
        var kappeBackTab = sessionStorage.getItem('firesafe_hent_tab') || 'own';
        var target = (prev === 'saved-modal')
            ? function() { closeKappeView(); _showSavedFormsDirectly(kappeBackTab); }
            : function() { closeKappeView(); showTemplateModal(); };
        if (isOnFormPage() && hasUnsavedChanges()) {
            _showUnsavedGuard(target);
        } else {
            target();
        }
        return;
    }
    // From kvittering view: tilbake dit vi kom fra (Lagret-fanen, Verktøy eller hjem).
    if (currentId === 'kvittering-view') {
        var kvBackTab = sessionStorage.getItem('firesafe_hent_tab') || 'kvittering';
        var target = (prev === 'saved-modal')
            ? function() { closeKvitteringView(); _showSavedFormsDirectly(kvBackTab); }
            : (prev === 'calculator-modal')
                ? function() { closeKvitteringView(); _showCalculatorDirectly(); }
                : function() { closeKvitteringView(); showTemplateModal(); };
        if (isOnFormPage() && hasUnsavedChanges()) {
            _showUnsavedGuard(target);
        } else {
            target();
        }
        return;
    }
    // Timebok uten historikk (f.eks. åpnet rett på en dag): dagsiden/eksport → uka.
    if (currentId === 'timebok-view' && _timebokViewMode !== 'week') {
        var toWeek = function () {
            _navDir = 'back';
            history.replaceState(null, '', '#timebok');
            _timebokApplyHash('timebok');
            _navNote();
            setTimeout(function () { _navDir = 'fwd'; }, 0);
        };
        if (hasUnsavedChanges()) _showUnsavedGuard(toWeek); else toWeek();
        return;
    }
    // From Timebok: ingen autolagring → ulagret-varsel (Avbryt / Forkast / Lagre), så hjem.
    if (currentId === 'timebok-view') {
        var tbTarget = function() { closeTimebokView(); showTemplateModal(); };
        if (hasUnsavedChanges()) _showUnsavedGuard(tbTarget); else tbTarget();
        return;
    }
    // Sjekkliste uten historikk: skjema → prosjektet → oversikten → hjem.
    if (currentId === 'sjekkliste-view') {
        _sjBackFallback();
        return;
    }
    // From Skjemaer: go back to home. closeModal() is reserved for loading a
    // saved form into the order form.
    if (currentId === 'saved-modal') {
        if (_selectMode) toggleSelectMode();
        if (document.activeElement && document.activeElement.blur) document.activeElement.blur();
        showTemplateModal();
        return;
    }
    // From Innstillinger (ingen historikk, f.eks. åpnet direkte på #settings): hjem.
    if (currentId === 'settings-modal') {
        showTemplateModal();
        return;
    }
    // From Calculator: if on a calc page, go back to menu; otherwise go home
    if (currentId === 'calculator-modal') {
        var activePage = document.querySelector('.calc-page[style=""]') || document.querySelector('.calc-page:not([style*="none"])');
        if (activePage && activePage.style.display !== 'none') {
            // Go back to calculator menu
            document.querySelectorAll('.calc-page').forEach(function(p) { p.style.display = 'none'; });
            document.querySelector('.calc-section').style.display = '';
            document.querySelector('#calculator-modal .modal-header span').textContent = t('calc_title');
        } else {
            document.body.classList.remove('calculator-modal-open');
            showTemplateModal();
        }
        return;
    }
    // Fallback: go home
    showTemplateModal();
}

function updatePreviewScale() {
    var overlay = document.getElementById('preview-overlay');
    if (!overlay || !overlay.classList.contains('active')) return;

    var fc = document.getElementById('form-container');
    var scroll = document.getElementById('preview-scroll');
    if (!fc || !scroll) return;

    // Wipe any lingering inline styles from previous sessions
    fc.style.marginLeft = '';
    fc.style.marginRight = '';
    fc.style.marginTop = '';
    fc.style.marginBottom = '';
    fc.style.transform = '';
    fc.style.transformOrigin = '';
    scroll.classList.remove('centered');

    var cs = getComputedStyle(scroll);
    var padLR = parseFloat(cs.paddingLeft) + parseFloat(cs.paddingRight);
    var availWidth = scroll.clientWidth - padLR;
    var formHeight = fc.offsetHeight;
    // PC (≥1400px med mus): cap til 800px for å matche resten av appens bredde.
    // Mobil/nettbrett: full bredde for konsistens med andre views.
    var isDesktop = window.matchMedia('(min-width: 1400px) and (hover: hover) and (pointer: fine)').matches;
    var maxRenderedWidth = isDesktop ? 800 : availWidth;
    var scale = maxRenderedWidth / 800;

    var header = document.querySelector('.preview-overlay-header');
    var renderedWidth = 800 * scale;
    var translateX = Math.max(0, (availWidth - renderedWidth) / 2);
    fc.style.transformOrigin = 'top left';
    fc.style.transform = 'translate(' + translateX + 'px, 0) scale(' + scale + ')';
    fc.style.marginBottom = (-(formHeight * (1 - scale))) + 'px';
    fc.style.marginRight = -(800 - renderedWidth - translateX) + 'px';
    fc.style.marginLeft = '0';
    if (header) {
        header.style.maxWidth = renderedWidth + 'px';
    }

    window._previewBaseScale = scale;
    window._previewCurrentScale = scale;
}

// «Vis» = render den EKTE tekst-PDF-en (via PDF.js) i preview-overlayet, så
// forhåndsvisningen er identisk med eksportfilen. Sidene tegnes til canvas i høy
// oppløsning. Fallback (PDF.js mangler): åpne PDF-blob i ny fane.
async function _showPdfInPreview(doc) {
    var overlay = document.getElementById('preview-overlay');
    var scroll = document.getElementById('preview-scroll');
    if (!overlay || !scroll) return;
    scroll.innerHTML = '';
    var wrap = document.createElement('div');
    wrap.className = 'pdf-preview-pages';
    scroll.appendChild(wrap);
    overlay.classList.add('active');
    document.body.style.overflow = 'hidden';
    document.body.classList.add('preview-active');

    var blob = doc.output('blob');
    var lib = window.pdfjsLib;
    if (!lib) {
        try { window.open(URL.createObjectURL(blob), '_blank'); } catch (e) {}
        return;
    }
    try { lib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js'; } catch (e) {}
    try {
        var buf = await blob.arrayBuffer();
        var pdf = await lib.getDocument({ data: buf }).promise;
        var renderScale = 2 * Math.min(window.devicePixelRatio || 1, 2);
        for (var p = 1; p <= pdf.numPages; p++) {
            var page = await pdf.getPage(p);
            var vp = page.getViewport({ scale: renderScale });
            var c = document.createElement('canvas');
            c.className = 'pdf-preview-page';
            c.width = vp.width; c.height = vp.height;
            wrap.appendChild(c);
            await page.render({ canvasContext: c.getContext('2d'), viewport: vp }).promise;
        }
    } catch (e) {
        try { window.open(URL.createObjectURL(blob), '_blank'); } catch (e2) {}
    }
}

function openPreview() {
    window._servicePreviewActive = false;
    window._kappePreviewActive = false;
    syncMobileToOriginal();
    var hasSig = !!document.getElementById('mobile-kundens-underskrift').value;
    updatePreviewHeaderState(hasSig);
    var signBtn = document.querySelector('.preview-sign-btn');
    if (signBtn) signBtn.style.display = '';   // ordreseddel kan signeres
    window._previewSavedScroll = _saveScrollPositions();
    buildOrdreseddelPdfDoc(getFormData()).then(_showPdfInPreview);
}

function _openPreviewLegacyDISABLED() {
    // Sync mobile form data to desktop layout
    syncMobileToOriginal();
    buildDesktopWorkLines();

    // Convert inputs to spans for clean rendering
    window._previewConverted = convertTextareasToDiv();

    var fc = document.getElementById('form-container');

    // Midlertidig fjern disabled for ren visning (identisk med eksport)
    var disabledFields = fc.querySelectorAll('input:disabled, textarea:disabled, select:disabled');
    disabledFields.forEach(function(el) { el.disabled = false; });
    window._previewDisabledFields = disabledFields;
    var scroll = document.getElementById('preview-scroll');

    // Move form-container into preview scroll area
    scroll.appendChild(fc);

    // Show and scale to fit screen
    fc.style.display = 'block';
    fc.style.width = '800px';

    // Activate overlay first so scroll has dimensions
    window._previewSavedScroll = _saveScrollPositions();
    document.getElementById('preview-overlay').classList.add('active');

    // Hide body scroll so form page scrollbar doesn't show behind overlay
    document.body.style.overflow = 'hidden';
    document.body.classList.add('preview-active');

    // Set header state based on whether signature exists
    var hasSig = !!document.getElementById('mobile-kundens-underskrift').value;
    updatePreviewHeaderState(hasSig);

    // Calculate scale after overlay is visible (never scale up beyond 1)
    requestAnimationFrame(function() {
        updatePreviewScale();
        var s = window._previewBaseScale;
        if (s < 1) {
            initPreviewPinchZoom(scroll, fc, s);
        }
    });

    // Recalculate on browser zoom / window resize / device rotation.
    // Wrap i 200ms timeout for orientationchange (lar viewport settle), og rens
    // + re-init pinch-zoom (samme mønster som service/kappe-preview for konsistens).
    window._previewResizeHandler = function() {
        clearTimeout(window._previewOrdreOrientTimer);
        window._previewOrdreOrientTimer = setTimeout(function() {
            updatePreviewScale();
            cleanupPreviewPinchZoom();
            var scrollEl = document.getElementById('preview-scroll');
            var fcEl = document.getElementById('form-container');
            if (!scrollEl || !fcEl) return;
            var baseScale = Math.min(scrollEl.clientWidth / 800, 1);
            if (baseScale < 1) initPreviewPinchZoom(scrollEl, fcEl, baseScale);
        }, 200);
    };
    window.addEventListener('resize', window._previewResizeHandler);
    window.addEventListener('orientationchange', window._previewResizeHandler);
}

function closePreview() {
    // Remove resize/orientation listener (samme handler bundet til begge events)
    if (window._previewResizeHandler) {
        window.removeEventListener('resize', window._previewResizeHandler);
        window.removeEventListener('orientationchange', window._previewResizeHandler);
        window._previewResizeHandler = null;
    }
    if (window._previewOrdreOrientTimer) {
        clearTimeout(window._previewOrdreOrientTimer);
        window._previewOrdreOrientTimer = null;
    }
    if (window._svcPreviewOrientTimer) {
        clearTimeout(window._svcPreviewOrientTimer);
        window._svcPreviewOrientTimer = null;
    }
    if (window._kappePreviewOrientTimer) {
        clearTimeout(window._kappePreviewOrientTimer);
        window._kappePreviewOrientTimer = null;
    }

    cleanupPreviewPinchZoom();
    document.getElementById('preview-overlay').classList.remove('active');

    // Restore body scroll
    document.body.style.overflow = '';
    document.body.classList.remove('preview-active');
    _restoreScrollPositions(window._previewSavedScroll);
    window._previewSavedScroll = null;

    if (window._servicePreviewActive) {
        // Service preview cleanup
        var sc = document.getElementById('service-export-container');
        document.getElementById('service-view').appendChild(sc);
        sc.style.display = 'none';
        sc.style.width = '';
        sc.style.overflow = '';
        sc.style.transform = '';
        sc.style.transformOrigin = '';
        sc.style.margin = '';
        sc.style.marginBottom = '';
        sc.style.marginLeft = '';
        sc.style.marginRight = '';
        window._servicePreviewActive = false;
    } else if (window._kappePreviewActive) {
        var kc = document.getElementById('kappe-export-container');
        document.getElementById('kappe-view').appendChild(kc);
        kc.style.display = 'none';
        kc.style.width = '';
        kc.style.overflow = '';
        kc.style.transform = '';
        kc.style.transformOrigin = '';
        kc.style.margin = '';
        kc.style.marginBottom = '';
        kc.style.marginLeft = '';
        kc.style.marginRight = '';
        window._kappePreviewActive = false;
        // Restore sign button visibility
        var signBtn = document.querySelector('.preview-sign-btn');
        if (signBtn) signBtn.style.display = '';
    } else {
        var fc = document.getElementById('form-container');
        // Move back to original location inside #view-form
        document.getElementById('view-form').appendChild(fc);

        // Restore original styling
        fc.style.display = '';
        fc.style.width = '';
        fc.style.transform = '';
        fc.style.transformOrigin = '';
        fc.style.margin = '';
        fc.style.marginBottom = '';
        fc.style.marginLeft = '';
        fc.style.marginRight = '';
    }

    // Reset header styles
    var header = document.querySelector('.preview-overlay-header');
    if (header) {
        header.style.maxWidth = '';
        header.style.margin = '';
        header.style.height = '';
        header.style.maxWidth = '';
        header.style.margin = '';
    }

    // Gjenopprett disabled-tilstand
    if (window._previewDisabledFields) {
        window._previewDisabledFields.forEach(function(el) { el.disabled = true; });
        window._previewDisabledFields = null;
    }

    // Restore converted elements
    if (window._previewConverted) {
        restoreTextareas(window._previewConverted);
        window._previewConverted = null;
    }

    // Fjern PDF-canvas-sidene (tekst-PDF-preview).
    var _ps = document.getElementById('preview-scroll');
    if (_ps) { var pages = _ps.querySelector('.pdf-preview-pages'); if (pages) pages.remove(); }
}

function previewSign() {
    if (window._servicePreviewActive) {
        // Service preview: open signature for service
        signatureTarget = 'service';
        openSignatureOverlay();
        window._signedFromServicePreview = true;
    } else {
        // Regular form preview
        openSignatureOverlay();
        window._signedFromPreview = true;
    }
}

function showExportMenu() {
    if (isModalOpen()) return;
    const popup = document.getElementById('action-popup');
    document.getElementById('action-popup-title').textContent = t('export_title');
    const buttonsEl = document.getElementById('action-popup-buttons');
    var shareIcon = '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><line x1="8.59" y1="13.51" x2="15.42" y2="17.49"/><line x1="15.41" y1="6.51" x2="8.59" y2="10.49"/></svg>';
    var canShare = !!(navigator.share && navigator.canShare);
    var mf = "document.getElementById('export-mark-ferdig')?.checked";
    var shareBtnPDF = canShare
        ? '<button class="confirm-btn-ok" style="background:#E8501A" onclick="doSharePDF(' + mf + '); closeActionPopup()">' + shareIcon + ' PDF</button>'
        : '<button class="confirm-btn-ok" style="background:#E8501A;opacity:0.5;cursor:not-allowed" onclick="showNotificationModal(t(\'share_not_supported\'))">' + shareIcon + ' PDF</button>';
    var shareBtnPNG = canShare
        ? '<button class="confirm-btn-ok" style="background:#E8501A" onclick="doSharePNG(' + mf + '); closeActionPopup()">' + shareIcon + ' PNG</button>'
        : '<button class="confirm-btn-ok" style="background:#E8501A;opacity:0.5;cursor:not-allowed" onclick="showNotificationModal(t(\'share_not_supported\'))">' + shareIcon + ' PNG</button>';
    // «Merk som ferdig»: av → deling gir sendt (som før), på → ferdig. Vises ikke
    // når skjemaet ALLEREDE er lukket — da er det ingenting å velge.
    // Nedlasting endrer aldri status, uansett avkrysning.
    var _fIsSent = sessionStorage.getItem('firesafe_current_sent') === '1';
    var _fStatus = sessionStorage.getItem('firesafe_current_status') || '';
    var alreadyClosed = _fIsSent && _fStatus !== 'sendt';
    var ferdigCheckboxHtml = alreadyClosed ? '' :
        '<label style="display:flex;align-items:center;gap:10px;margin-bottom:12px;cursor:pointer;font-size:14px;padding:4px 0">' +
            '<input type="checkbox" id="export-mark-ferdig" style="width:22px;height:22px;accent-color:#E8501A;flex-shrink:0">' +
            escapeHtml(t('export_mark_ferdig_label')) +
        '</label>';
    let html = ferdigCheckboxHtml +
        '<div style="font-size:13px;font-weight:600;color:#555;margin-bottom:4px">' + t('export_download') + '</div>' +
        '<div class="confirm-modal-buttons" style="margin-bottom:12px">' +
            '<button class="confirm-btn-ok" style="background:#333" onclick="doExportPDF(); closeActionPopup()"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M7 10l5 5 5-5M12 15V3"/></svg> PDF</button>' +
            '<button class="confirm-btn-ok" style="background:#333" onclick="doExportPNG(); closeActionPopup()"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M7 10l5 5 5-5M12 15V3"/></svg> PNG</button>' +
        '</div>' +
        '<div style="font-size:13px;font-weight:600;color:#555;margin-bottom:4px">' + t('btn_share') + '</div>' +
        '<div class="confirm-modal-buttons">' +
            shareBtnPDF + shareBtnPNG +
        '</div>';
    buttonsEl.innerHTML = html;
    popup.classList.add('active');
}

var _filterTimeout = null;
var _searchVersion = 0;
var _savedFormsAll = null;
var _templatesAll = null;
var _serviceFormsAll = null;

// Firestore prefix-søk for skjemaer som ikke er lastet inn ennå
async function firestoreSearchForms(rawTerm, collections, field) {
    if (!currentUser || !db || !rawTerm) return [];
    var searchField = field || 'ordreseddelNr';
    var results = await Promise.all(collections.map(function(col) {
        return db.collection('users').doc(currentUser.uid).collection(col.name)
            .where(searchField, '>=', rawTerm)
            .where(searchField, '<=', rawTerm + '\uf8ff')
            .orderBy(searchField)
            .limit(50)
            .get()
            .catch(function() { return { docs: [] }; });
    }));
    var forms = [];
    results.forEach(function(snap, i) {
        snap.docs.forEach(function(d) {
            forms.push(Object.assign({ id: d.id, _isSent: !!collections[i].isSent }, d.data()));
        });
    });
    return forms;
}

function mergeSearchResults(memoryResults, firestoreResults) {
    var ids = {};
    memoryResults.forEach(function(f) { if (f.id) ids[f.id] = true; });
    var merged = memoryResults.slice();
    firestoreResults.forEach(function(f) {
        if (f.id && !ids[f.id]) merged.push(f);
    });
    return merged;
}

function filterList(listId, searchId) {
    clearTimeout(_filterTimeout);
    _filterTimeout = setTimeout(function() {
        var rawTerm = document.getElementById(searchId).value.trim();
        var term = rawTerm.toLowerCase();

        // Invalider eventuelle in-flight Firestore-søk
        ++_searchVersion;

        if (listId === 'saved-list') {
            if (!_savedFormsAll) _savedFormsAll = window.loadedForms ? window.loadedForms.slice() : [];
            if (!term) { var all = _savedFormsAll; _savedFormsAll = null; renderSavedFormsList(all, false, _savedHasMore || _sentHasMore); return; }
            var filtered = _savedFormsAll.filter(function(f) {
                return (f.ordreseddelNr || '').toLowerCase().startsWith(term) ||
                       (f.prosjektnr || '').toLowerCase().startsWith(term) ||
                       (f.prosjektnavn || '').toLowerCase().startsWith(term);
            });
            renderSavedFormsList(filtered);
            // Søk i Firestore etter ulastede skjemaer (på alle tre felter)
            if ((_savedHasMore || _sentHasMore) && currentUser && db) {
                var ver = ++_searchVersion;
                var cols = [
                    { name: 'forms', isSent: false },
                    { name: 'archive', isSent: true }
                ];
                Promise.all([
                    firestoreSearchForms(rawTerm, cols, 'ordreseddelNr'),
                    firestoreSearchForms(rawTerm, cols, 'prosjektnr'),
                    firestoreSearchForms(rawTerm, cols, 'prosjektnavn')
                ]).then(function(all) {
                    if (ver !== _searchVersion) return;
                    var combined = all[0].concat(all[1], all[2]);
                    var merged = mergeSearchResults(filtered, combined);
                    if (merged.length > filtered.length) {
                        renderSavedFormsList(merged);
                    }
                });
            }
        } else if (listId === 'template-picker-list') {
            var cachedAll = safeParseJSON(TEMPLATE_KEY, []).filter(function(t) { return t.active !== false; });
            var pickerListEl = document.getElementById('template-picker-list');
            if (!term) { _renderTemplatePickerList(cachedAll, pickerListEl); return; }
            var filteredPicker = cachedAll.filter(function(f) {
                return (f.prosjektnavn || '').toLowerCase().indexOf(term) !== -1 ||
                       (f.oppdragsgiver || '').toLowerCase().indexOf(term) !== -1 ||
                       (f.prosjektnr || '').toLowerCase().indexOf(term) !== -1;
            });
            _renderTemplatePickerList(filteredPicker, pickerListEl);
        } else if (listId === 'kvittering-list') {
            _kvFilterList(term);
        } else if (listId === 'service-list') {
            if (!_serviceFormsAll) _serviceFormsAll = window.loadedServiceForms ? window.loadedServiceForms.slice() : [];
            if (!term) { var all4 = _serviceFormsAll; _serviceFormsAll = null; renderServiceFormsList(all4); return; }
            var filtered4 = _serviceFormsAll.filter(function(f) {
                return (f.montor || '').toLowerCase().indexOf(term) !== -1;
            });
            renderServiceFormsList(filtered4);
        }
    }, 150);
}

function updateSearchClearBtn(inputId) {
    var input = document.getElementById(inputId);
    var btn = document.getElementById(inputId + '-clear');
    if (!input || !btn) return;
    btn.classList.toggle('visible', !!input.value);
}

function clearSearchInput(inputId, listId) {
    var input = document.getElementById(inputId);
    if (!input) return;
    input.value = '';
    updateSearchClearBtn(inputId);
    filterList(listId, inputId);
    input.focus();
}

function markCurrentFormAsSent() {
    try {
        var data = getFormData();
        data.status = 'sendt';   // sendt, venter på signatur → blå prikk
        var formsCollection = 'forms';
        var archiveCollection = 'archive';

        // localStorage: legg til i archived, IKKE fjern fra saved (sikkerhetskopi)
        var saved = safeParseJSON(STORAGE_KEY, []);
        var existingIndex = saved.findIndex(function(item) { return item.ordreseddelNr === data.ordreseddelNr; });
        if (existingIndex !== -1) {
            data.id = saved[existingIndex].id;
        } else {
            data.id = _newFormId();
        }
        var archived = safeParseJSON(ARCHIVE_KEY, []);
        var archivedExisting = archived.findIndex(function(item) { return item.ordreseddelNr === data.ordreseddelNr; });
        if (archivedExisting !== -1) {
            archived[archivedExisting] = data;
        } else {
            archived.unshift(data);
        }
        safeSetItem(ARCHIVE_KEY, JSON.stringify(archived));
        addToOrderNumberIndex(data.ordreseddelNr);

        // Update UI state
        sessionStorage.setItem('firesafe_current_sent', '1');
        lastSavedData = getFormDataSnapshot();
        sessionStorage.setItem('firesafe_current_status', 'sendt');
        document.getElementById('sent-banner').style.display = 'block';
        _updateFormStatusButtons();
        showNotificationModal(t('marked_as_sent'), true);
        _lastLocalSaveTs = Date.now();
        loadedForms = [];
        _showSavedFormsDirectly();

        enqueueUserDocMove(archiveCollection, formsCollection, data.id, data, 'Mark as sent Firebase');
    } catch (e) {
        console.error('Mark as sent error:', e);
    }
}

// Sentralt: oppdater status-knappene (Merk sendt / Merk ferdig) ut fra det åpne
// skjemaets tilstand (sessionStorage `firesafe_current_sent`/`firesafe_current_status`):
//   Utkast  → begge knapper (kan sendes ELLER ferdigstilles direkte ved signering på stedet)
//   Sendt   → kun «Merk ferdig»
//   Ferdig  → ingen (hele status-raden skjules)
function _updateFormStatusButtons() {
    // Én «Merk som ▾»-knapp er alltid synlig; popupen tilpasser valgene til
    // gjeldende status (se showFormStatusMenu). Tidligere skjulte vi knapper
    // per status — nå eier menyen den logikken.
    var row = document.getElementById('form-status-actions');
    if (row) row.style.display = '';
}

// Status-farger på ETT sted. De var duplisert som literaler i tre popup-byggere
// og drev fra hverandre: «Merk lukket»-knappen i lista sto igjen som grønn
// gjennom to palett-endringer fordi den ble glemt. Må holdes i synk med
// .status-dot-reglene i styles.css (CSS kan ikke lese herfra).
var _STATUS_COLORS = { lagret: '#F5A623', sendt: '#2D7FF9', ferdig: '#3a3a3c' };

// In-form status-meny: gjenbruker bulk-popup-mønsteret (#action-popup +
// .bulk-status-option). Valgene avhenger av gjeldende status: forover i flyten,
// og fra Lukket tilbake til Sendt (send på nytt hvis den ble avvist).
var _FORM_STATUS_META = {
    sendt:  { color: _STATUS_COLORS.sendt,  key: 'btn_mark_sent' },
    ferdig: { color: _STATUS_COLORS.ferdig, key: 'btn_mark_ferdig' }   // = Lukket
};
function showFormStatusMenu() {
    var isSent = sessionStorage.getItem('firesafe_current_sent') === '1';
    var status = sessionStorage.getItem('firesafe_current_status') || '';
    // Alt i archive som ikke er 'sendt' er Lukket — inkludert den utgåtte
    // 'ikke_godkjent' på gamle dokumenter og arkiverte uten status-felt.
    var cur = !isSent ? 'utkast' : (status === 'sendt' ? 'sendt' : 'lukket');
    var opts;
    if (cur === 'utkast') opts = ['sendt', 'ferdig'];
    else if (cur === 'sendt') opts = ['ferdig'];
    else opts = ['sendt'];   // Lukket → send på nytt (f.eks. etter avvisning)
    var titleEl = document.getElementById('action-popup-title');
    if (titleEl) titleEl.textContent = t('form_mark_btn');
    document.getElementById('action-popup-buttons').innerHTML =
        '<div class="bulk-status-menu">' +
        opts.map(function(o) {
            var m = _FORM_STATUS_META[o];
            return '<button class="bulk-status-option" onclick="closeActionPopup(); _formMarkStatus(\'' + o + '\')">' +
                '<span class="bulk-status-option-dot" style="background:' + m.color + '"></span>' + t(m.key) + '</button>';
        }).join('') +
        '</div>';
    document.getElementById('action-popup').classList.add('active');
}
window.showFormStatusMenu = showFormStatusMenu;

function _formMarkStatus(target) {
    if (!validateRequiredFields()) return;
    if (target === 'sendt') markCurrentFormAsSent();
    else if (target === 'ferdig') markCurrentFormAsFerdig();
}
window._formMarkStatus = _formMarkStatus;
window._updateFormStatusButtons = _updateFormStatusButtons;

// Marker det ÅPNE skjemaet som LUKKET: sett status='ferdig' i archive. Er
// skjemaet allerede sendt ligger det i archive (ingen flytting); kommer det
// direkte fra utkast, flyttes det forms→archive. Verdien 'ferdig' beholdes som
// intern representasjon av Lukket — kun etiketten er endret, så gamle dokumenter
// (også de med utgått 'ikke_godkjent') trenger ingen migrering.
function _markCurrentFormTerminal(statusVal, toastKey) {
    try {
        var data = getFormData();
        data.status = statusVal;
        var wasSent = sessionStorage.getItem('firesafe_current_sent') === '1';
        var saved = safeParseJSON(STORAGE_KEY, []);
        var archived = safeParseJSON(ARCHIVE_KEY, []);
        var aIdx = archived.findIndex(function(f) { return f.ordreseddelNr === data.ordreseddelNr; });
        var sIdx = saved.findIndex(function(f) { return f.ordreseddelNr === data.ordreseddelNr; });
        data.id = (aIdx !== -1) ? archived[aIdx].id : ((sIdx !== -1) ? saved[sIdx].id : Date.now().toString());
        if (aIdx !== -1) archived[aIdx] = data; else archived.unshift(data);
        safeSetItem(ARCHIVE_KEY, JSON.stringify(archived));
        if (sIdx !== -1) { saved.splice(sIdx, 1); safeSetItem(STORAGE_KEY, JSON.stringify(saved)); }
        addToOrderNumberIndex(data.ordreseddelNr);
        if (wasSent || aIdx !== -1) {
            enqueueUserDocSet('archive', data.id, data, 'Mark ' + statusVal + ' (var i archive)');
        } else {
            enqueueUserDocMove('archive', 'forms', data.id, data, 'Mark ' + statusVal + ' (fra utkast)');
        }
        sessionStorage.setItem('firesafe_current_sent', '1');
        sessionStorage.setItem('firesafe_current_status', statusVal);
        _updateFormStatusButtons();
        showNotificationModal(t(toastKey), true);
        _lastLocalSaveTs = Date.now();
        loadedForms = [];
        _showSavedFormsDirectly();
    } catch (e) { console.error('Mark terminal (' + statusVal + ') error:', e); }
}
function markCurrentFormAsFerdig() { _markCurrentFormTerminal('ferdig', 'marked_as_ferdig'); }
window.markCurrentFormAsFerdig = markCurrentFormAsFerdig;

// Kalt når en DELING er fullført: løft LAGRET (utkast) til sendt. Sendt forblir
// sendt, ferdig forblir ferdig — aldri nedgrader (en ferdig/signert liste som
// deles er fortsatt ferdig). Nedlasting kaller IKKE denne (last ned ≠ sendt).
// ── «Deling = sendt» — ÉN regel for hele appen ───────────────────────────────
// En FULLFØRT deling markerer skjemaet som sendt. En nedlasting gjør det ikke —
// en fil på egen disk er ikke levert til noen. Regelen gjelder alle tre
// skjematypene (ordreseddel, servicebil, kappeskjema) og alle tre delings-veiene
// (åpent skjema, enkeltskjema fra Lagret-lista, fler-valg-eksport).
// Ingen av veiene nedgraderer et skjema som allerede er sendt eller lukket.
// Manuell merking finnes fortsatt: «Merk som» i ordreseddelen og
// «Merk som sendt»-knappen i servicebil/kappeskjema.
// markFerdig = avkrysningen «Merk som ferdig» i eksport-menyen.
//   av  → utkast blir sendt; sendt/ferdig røres ikke (som før)
//   på  → utkast OG sendt blir ferdig (kunden har signert, saken er lukket)
// Ferdig nedgraderes aldri. Kun ordreseddel: servicebil og kappeskjema har bare
// to tilstander og ingen «ferdig».
function _promoteFormToSent(markFerdig) {
    var isSent = sessionStorage.getItem('firesafe_current_sent') === '1';
    var status = sessionStorage.getItem('firesafe_current_status') || '';
    if (markFerdig) {
        // Alt i archive som ikke er 'sendt' er allerede lukket — samme regel som
        // showFormStatusMenu bruker, så de to kan ikke bli uenige om tilstanden.
        var alreadyClosed = isSent && status !== 'sendt';
        if (alreadyClosed) return;
        markCurrentFormAsFerdig();
        return;
    }
    if (isSent) return;                        // sendt el. ferdig → ikke rør
    markCurrentFormAsSent();
}
window._promoteFormToSent = _promoteFormToSent;

function _promoteServiceToSent() {
    if (sessionStorage.getItem('firesafe_service_sent') === '1') return;
    markServiceAsSent();
}
window._promoteServiceToSent = _promoteServiceToSent;

function _promoteKappeToSent() {
    if (sessionStorage.getItem('firesafe_kappe_sent') === '1') return;
    markKappeAsSent();
}
window._promoteKappeToSent = _promoteKappeToSent;

// Enkeltskjema delt fra Lagret-lista. Skjemaet er IKKE åpent, så vi bruker de
// samme data-baserte hjelperne som fler-valg-eksporten (_bulkMarkSelectedAsSent)
// i stedet for de skjema-baserte markXAsSent-funksjonene.
// tab: 'own' | 'service' | 'kappe' (fra _savedItemTab).
function _promoteListFormToSent(form, tab, markFerdig) {
    if (!form) return false;
    // «Merk som ferdig» gjelder kun ordreseddel, og gjør at et allerede SENDT
    // skjema kan lukkes ved deling. _applyFormStatus håndterer alle overganger
    // (også forms→archive for et utkast), så vi slipper egen flytte-logikk her.
    if (markFerdig && tab === 'own') {
        if (_isFormClosed(form)) return false;  // allerede lukket → ingenting å gjøre
        var savedArr = safeParseJSON(STORAGE_KEY, []);
        var archArr = safeParseJSON(ARCHIVE_KEY, []);
        try { _applyFormStatus(form, 'ferdig', savedArr, archArr); }
        catch (e) { console.error('Del → ferdig:', e); return false; }
        safeSetItem(STORAGE_KEY, JSON.stringify(savedArr));
        safeSetItem(ARCHIVE_KEY, JSON.stringify(archArr));
        form._isSent = true;
        form.status = 'ferdig';
        _lastLocalSaveTs = Date.now();
        loadedForms = [];
        _showSavedFormsDirectly(tab);
        showNotificationModal(t('marked_as_ferdig'), true);
        return true;
    }
    if (form._isSent) return false;            // allerede sendt/lukket → aldri nedgrader
    if (tab === 'kvittering') _applyTwoStateStatus(form, tab, 'sendt');
    else if (tab === 'service') _markServiceFormDataAsSent(form);
    else if (tab === 'kappe') _markKappeFormDataAsSent(form);
    else _markOwnFormDataAsSent(form);
    form._isSent = true;                       // lista holder samme objekt
    _lastLocalSaveTs = Date.now();
    loadedForms = [];
    _showSavedFormsDirectly(tab);
    showNotificationModal(t('marked_as_sent'), true);
    return true;
}
window._promoteListFormToSent = _promoteListFormToSent;

// ── Status fra lista: utkast → sendt → ferdig ────────────────────────────────
// Marker et lagret skjema (fra #hent-lista) som SENDT (blå): flytt forms→archive
// og sett status='sendt'. Speiler markCurrentFormAsSent, men på data fra lista
// (skjemaet trenger ikke være åpent).
function _markFormSent(form) {
    try {
        var data = Object.assign({}, form);
        delete data._isSent;
        data.status = 'sendt';
        if (!data.id) data.id = _newFormId();
        // localStorage: flytt fra saved til archive.
        var saved = safeParseJSON(STORAGE_KEY, []);
        var sIdx = saved.findIndex(function(f) { return f.id === data.id; });
        if (sIdx !== -1) { saved.splice(sIdx, 1); safeSetItem(STORAGE_KEY, JSON.stringify(saved)); }
        var archived = safeParseJSON(ARCHIVE_KEY, []);
        var aIdx = archived.findIndex(function(f) { return f.id === data.id; });
        if (aIdx !== -1) archived[aIdx] = data; else archived.unshift(data);
        safeSetItem(ARCHIVE_KEY, JSON.stringify(archived));
        addToOrderNumberIndex(data.ordreseddelNr);
        enqueueUserDocMove('archive', 'forms', data.id, data, 'Mark sent (list)');
        _lastLocalSaveTs = Date.now();
        loadedForms = [];
        _showSavedFormsDirectly();
        showNotificationModal(t('marked_as_sent'), true);
    } catch (e) { console.error('Mark sent (list) error:', e); }
}

// Marker et SENDT skjema som FERDIG (grønn): sett status='ferdig' i archive
// (ingen samlings-flytting — den ligger allerede i archive).
function _markFormFerdig(form) {
    try {
        var data = Object.assign({}, form);
        delete data._isSent;
        data.status = 'ferdig';
        if (!data.id) data.id = _newFormId();
        var archived = safeParseJSON(ARCHIVE_KEY, []);
        var aIdx = archived.findIndex(function(f) { return f.id === data.id; });
        if (aIdx !== -1) archived[aIdx] = data; else archived.unshift(data);
        safeSetItem(ARCHIVE_KEY, JSON.stringify(archived));
        enqueueUserDocSet('archive', data.id, data, 'Mark ferdig (list)');
        _lastLocalSaveTs = Date.now();
        loadedForms = [];
        _showSavedFormsDirectly();
        showNotificationModal(t('marked_as_ferdig'), true);
    } catch (e) { console.error('Mark ferdig error:', e); }
}

// Ett trykk på status-knappen i lista flytter til NESTE tilstand (med bekreftelse).
function advanceSavedFormStatus(form) {
    if (!form) return;
    if (!form._isSent) {
        showConfirmModal(t('mark_sent_confirm'), function() { _markFormSent(form); }, t('btn_mark_sent'), '#2D7FF9');
    } else if (form.status === 'sendt') {
        showConfirmModal(t('mark_ferdig_confirm'), function() { _markFormFerdig(form); }, t('btn_mark_ferdig'), '#4CAF50');
    }
}
window.advanceSavedFormStatus = advanceSavedFormStatus;

// ============================================
// PROSJEKTMALER
// ============================================

if (!window.loadedTemplates) window.loadedTemplates = [];

// Prosjektlista = felles (firmaets) + egne (se FELLES PROSJEKTER under). Hele lista hentes i
// ett (ingen sider — `lastDoc` brukes ikke lenger, men beholdes for kallene).
async function getTemplates(lastDoc) {
    if (lastDoc) return { forms: [], lastDoc: null, hasMore: false };
    if (currentUser && db) {
        try {
            var list = await _projFetchAll();
            // Kallene under skriver selv TEMPLATE_KEY (noen med en gammel 50-grense) — hele
            // lista legges i cachen like etter, så ingen prosjekter faller ut.
            setTimeout(function () { _projCache(list); _projUpdateBadges(); }, 0);
            return { forms: list, lastDoc: null, hasMore: false };
        } catch (e) {
            console.error('Templates error:', e);
            return { forms: safeParseJSON(TEMPLATE_KEY, []), lastDoc: null, hasMore: false };
        }
    }
    if (auth && !authReady) return { forms: [], lastDoc: null, hasMore: false };
    return { forms: safeParseJSON(TEMPLATE_KEY, []), lastDoc: null, hasMore: false };
}

function _buildTemplateItemHtml(item, index) {
    var row1 = (escapeHtml(item.prosjektnavn) || t('no_name')) + (item._pending ? ' <span class="proj-pending-chip">' + escapeHtml(t('proj_pending_chip')) + '</span>' : '');
    var row2 = [item.oppdragsgiver, item.prosjektnr].filter(function(x) { return x; }).map(escapeHtml).join(' \u2022 ');
    var row3 = item.fakturaadresse ? escapeHtml(item.fakturaadresse) : '';
    return '<div class="saved-item" data-index="' + index + '">' +
        '<div class="saved-item-info">' +
            '<div class="saved-item-row1">' + row1 + '</div>' +
            (row2 ? '<div class="saved-item-row2">' + row2 + '</div>' : '') +
            (row3 ? '<div class="saved-item-row2">' + row3 + '</div>' : '') +
        '</div>' +
    '</div>';
}

// ═══ FELLES PROSJEKTER + MONTØRENS FORSLAG (15-11-2026) ═════════════════════
// Bruker: admin styrer prosjektlista (felles for firmaet), men montører må kunne lage et
// prosjekt selv med en gang (admin er treg med å legge inn) — uten at skrivefeil spres til alle:
//   • Felles liste: firms/{firma}/projects/{id} — bare admin skriver, alle i firmaet leser.
//   • Montør lager prosjekt → PERSONLIG (users/{uid}/templates, forslag:'pending'), brukes med en
//     gang i egne skjemaer/Timebok, og sendes som forslag: firms/{firma}/projectSuggestions/
//     {uid}_{id}. Andre montører ser det ikke.
//   • Admin (Admin › Prosjekter › Til godkjenning): Godkjenn (kan rette navn/nr/adresser først)
//     → felles prosjekt med SAMME id (Timebok-dagene peker fortsatt riktig) · Slå sammen med et
//     eksisterende · Avvis (blir værende personlig for montøren).
//   • Montørens app plukker opp avgjørelsen ved neste henting: rettelsene skrives ut i egne
//     skjemaer (_propagateProjectCorrection), og den personlige kopien skjules. Admin-rettelser
//     av et felles prosjekt slår igjennom likt hos alle (sammenligning mot forrige kopi).
//   • Admins egne prosjekter fra før blir IKKE felles automatisk (hovedadmin bytter firma, og
//     lista kunne havnet i feil firma) — de står under «Til godkjenning» med «Gjør alle felles».
//   • Reiseavstand er pr. person (avstanden fra der man bor): egen verdi i PROJECT_OVERRIDES_KEY
//     (users/{uid}/settings/project_overrides), aldri på det felles prosjektet.
//   • Mangler Firestore-reglene (felles liste kan ikke leses) → gammel modus: bare egne
//     prosjekter, som før. Ingenting forsvinner.
// Lokal test (DEV, uid 'dev-local'): _projStore etterligner Firestore i localStorage, med egne
// personlige lister for testrollene Admin og Montør (Meny › Testmodus).
var PROJECT_OVERRIDES_KEY = 'firesafe_project_overrides';
var _PROJ_DEV_KEY = 'firesafe_dev_projects';
var _projSharedOk = null;          // null = ukjent, true = felles liste virker, false = gammel modus
var _projSyncAt = 0;
var _projPending = [];             // admin: montørenes forslag (status pending)
var _projReview = null;            // admin: { sugg } eller { own } mens et forslag vurderes

function _projDevData() {
    var d = safeParseJSON(_PROJ_DEV_KEY, null);
    if (!d) {
        // Første gang: dagens lokale prosjekter blir admins personlige (som i ekte modus).
        d = { shared: {}, sugg: {}, own: { admin: {}, montor: {} } };
        safeParseJSON(TEMPLATE_KEY, []).forEach(function (p) { if (p && p.id && !p._shared) d.own.admin[p.id] = _projClean(p); });
        _projDevSave(d);
    }
    // Felles liste og forslag er pr. firma (som firms/{firma}/…); egne er pr. bruker.
    d.own = d.own || {}; d.firms = d.firms || {};
    if (d.shared && !d.firms.firesafe) { d.firms.firesafe = { shared: d.shared, sugg: d.sugg || {} }; }
    var f = _firma();
    d.firms[f] = d.firms[f] || { shared: {}, sugg: {} };
    d.shared = d.firms[f].shared; d.sugg = d.firms[f].sugg;
    return d;
}
function _projDevSave(d) { var o = Object.assign({}, d); delete o.shared; delete o.sugg; safeSetItem(_PROJ_DEV_KEY, JSON.stringify(o)); }
function _projDevRoleKey() { return (typeof _devRole === 'function' && _devRole() === 'montor') ? 'montor' : 'admin'; }
// Fjern visningsflagg (_shared, _own, _pending …) og id før lagring.
function _projClean(p) {
    var o = {};
    Object.keys(p || {}).forEach(function (k) { if (k.charAt(0) !== '_' && k !== 'id') o[k] = p[k]; });
    return o;
}
function _projDocs(s) { return s.docs.map(function (x) { return Object.assign({ id: x.id }, x.data()); }); }
function _projDevList(o) { return Object.keys(o || {}).map(function (k) { return Object.assign({ id: k }, o[k]); }); }
function _projDevPut(bucket, id, data, merge) { bucket[id] = merge ? Object.assign({}, bucket[id] || {}, data) : data; }
var _projStore = {
    listShared: function () {
        if (_admDev()) return Promise.resolve(_projDevList(_projDevData().shared));
        return _firmaRef().collection('projects').get().then(_projDocs);
    },
    setShared: function (id, data, merge) {
        data = _projClean(data);
        delete data.timebokBracketId; delete data.forslag; delete data.mergedInto;   // personlig, ikke felles
        if (_admDev()) { var d = _projDevData(); _projDevPut(d.shared, id, data, merge); _projDevSave(d); return Promise.resolve(); }
        var ref = _firmaRef().collection('projects').doc(id);
        return merge ? ref.set(data, { merge: true }) : ref.set(data);
    },
    delShared: function (id) {
        if (_admDev()) { var d = _projDevData(); delete d.shared[id]; _projDevSave(d); return Promise.resolve(); }
        return _firmaRef().collection('projects').doc(id).delete();
    },
    listOwn: function () {
        if (_admDev()) return Promise.resolve(_projDevList(_projDevData().own[_projDevRoleKey()]));
        return db.collection('users').doc(currentUser.uid).collection('templates').orderBy('prosjektnavn').get().then(_projDocs);
    },
    setOwn: function (id, data, merge) {
        data = _projClean(data);
        if (_admDev()) { var d = _projDevData(), r = _projDevRoleKey(); d.own[r] = d.own[r] || {}; _projDevPut(d.own[r], id, data, merge); _projDevSave(d); return; }
        enqueueUserDocSet('templates', id, data, 'Save project', merge ? { merge: true } : undefined);
    },
    delOwn: function (id) {
        if (_admDev()) { var d = _projDevData(), r = _projDevRoleKey(); if (d.own[r]) delete d.own[r][id]; _projDevSave(d); return; }
        enqueueUserDocDelete('templates', id, 'Delete project');
    },
    listSuggPending: function () {
        if (_admDev()) return Promise.resolve(_projDevList(_projDevData().sugg).filter(function (s) { return s.status === 'pending'; }));
        return _firmaRef().collection('projectSuggestions').where('status', '==', 'pending').get().then(_projDocs);
    },
    listSuggMine: function () {
        var me = _projMe();
        if (_admDev()) return Promise.resolve(_projDevList(_projDevData().sugg).filter(function (s) { return s.createdBy === me; }));
        return _firmaRef().collection('projectSuggestions').where('createdBy', '==', me).get().then(_projDocs);
    },
    setSugg: function (id, data, merge) {
        data = _projClean(data);
        if (_admDev()) { var d = _projDevData(); _projDevPut(d.sugg, id, data, merge); _projDevSave(d); return Promise.resolve(); }
        var ref = _firmaRef().collection('projectSuggestions').doc(id);
        return merge ? ref.set(data, { merge: true }) : ref.set(data);
    },
    delSugg: function (id) {
        if (_admDev()) { var d = _projDevData(); delete d.sugg[id]; _projDevSave(d); return Promise.resolve(); }
        return _firmaRef().collection('projectSuggestions').doc(id).delete();
    }
};
// Hvem er «jeg»? I lokal test er admin og montør to ulike personer (testrollen).
function _projMe() { return _admDev() ? 'dev-' + _projDevRoleKey() : (currentUser ? currentUser.uid : ''); }
function _projMyName() {
    if (_admDev()) return _projDevRoleKey() === 'montor' ? 'Test Montør' : 'Test Admin';
    var mi = (typeof getMinInfo === 'function') ? (getMinInfo() || {}) : {};
    var n = [mi.fornavn, mi.etternavn].filter(Boolean).join(' ').trim();
    return n || (currentUser && (currentUser.displayName || currentUser.email)) || '';
}
function _projDateStr(iso) {
    var d = iso ? new Date(iso) : null;
    if (!d || isNaN(d.getTime())) return '';
    return ('0' + d.getDate()).slice(-2) + '-' + ('0' + (d.getMonth() + 1)).slice(-2) + '-' + d.getFullYear();
}
// ── Reiseavstand pr. person ──
function _projOverrides() { return safeParseJSON(PROJECT_OVERRIDES_KEY, {}) || {}; }
function _projSaveOverride(id, bracketId) {
    var o = _projOverrides();
    if (bracketId) o[id] = { timebokBracketId: bracketId }; else delete o[id];
    safeSetItem(PROJECT_OVERRIDES_KEY, JSON.stringify(o));
    enqueueUserDocSet('settings', 'project_overrides', { map: o }, 'Project overrides');
}
function _projFetchOverrides() {
    if (!currentUser || !db || _admDev()) return Promise.resolve();
    return db.collection('users').doc(currentUser.uid).collection('settings').doc('project_overrides').get()
        .then(function (d) { if (d.exists) safeSetItem(PROJECT_OVERRIDES_KEY, JSON.stringify((d.data() || {}).map || {})); })
        .catch(function (e) { console.warn('Project overrides:', e && (e.code || e.message)); });
}
function _projNorm(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9æøå]/g, ''); }
function _projSort(list) {
    return list.sort(function (a, b) { return _cmpText(String(a.prosjektnavn || ''), String(b.prosjektnavn || '')); });
}
// Felles (godkjente) + egne som ikke er godkjent/slått sammen. Egne med samme id som et
// felles skjules (godkjent med samme id).
function _projMerge(shared, own) {
    var ids = {}, ov = _projOverrides(), out = [];
    shared.forEach(function (p) {
        ids[p.id] = 1;
        out.push(Object.assign({}, p, { _shared: true, timebokBracketId: (ov[p.id] && ov[p.id].timebokBracketId) || null }));
    });
    own.forEach(function (p) {
        if (ids[p.id] || p.forslag === 'approved' || p.forslag === 'merged') return;
        out.push(Object.assign({}, p, { _own: true, _pending: p.forslag === 'pending' }));
    });
    return _projSort(out);
}
function _projIdentityChanged(a, b) {
    return ['prosjektnavn', 'prosjektnr', 'oppdragsgiver', 'kundensRef', 'fakturaadresse', 'leveringsadresse']
        .some(function (k) { return String(a[k] || '') !== String(b[k] || ''); });
}
function _projStrip(p) { var o = Object.assign({}, p); Object.keys(o).forEach(function (k) { if (k.charAt(0) === '_') delete o[k]; }); return o; }
// Hent alt (felles + egne). Lesefeil på felles liste = gammel modus (bare egne).
function _projFetchAll() {
    var prevShared = {};
    safeParseJSON(TEMPLATE_KEY, []).forEach(function (p) { if (p && p._shared) prevShared[p.id] = p; });
    return Promise.all([
        _projStore.listShared().then(function (x) { _projSharedOk = true; return x; }, function (e) {
            _projSharedOk = false;
            console.warn('Felles prosjekter utilgjengelig (Firestore-regler?) — bruker egne:', e && (e.code || e.message));
            return null;
        }),
        _projStore.listOwn().catch(function (e) { console.error('Egne prosjekter:', e); return null; }),
        _projFetchOverrides()
    ]).then(function (r) {
        var shared = r[0], own = r[1];
        if (own === null) own = safeParseJSON(TEMPLATE_KEY, []).filter(function (p) { return p && !p._shared; }).map(_projStrip);
        if (shared === null) return _projSort(own.slice());
        // Admin har rettet et felles prosjekt siden sist → rett egne skjemaer (alle brukere).
        shared.forEach(function (p) {
            var old = prevShared[p.id];
            if (old && _projIdentityChanged(old, p)) {
                try { _propagateProjectCorrection(_projStrip(old), p); } catch (e) { console.error('Propagate shared project:', e); }
            }
        });
        if (Date.now() - _projSyncAt > 30000) { _projSyncAt = Date.now(); setTimeout(function () { _projSync(shared, own); }, 0); }
        return _projMerge(shared, own);
    });
}
function _projCache(list) {
    safeSetItem(TEMPLATE_KEY, JSON.stringify(list));
    window.loadedTemplates = list.slice();
}
// Optimistisk oppdatering av cachen (én rad) — før Firestore har svart.
function _projCacheUpsert(item) {
    var list = safeParseJSON(TEMPLATE_KEY, []), found = false;
    list = list.map(function (p) { if (p.id === item.id) { found = true; return item; } return p; });
    if (!found) list.push(item);
    _projCache(_projSort(list));
}
function _projCacheRemove(id) { _projCache(safeParseJSON(TEMPLATE_KEY, []).filter(function (p) { return p.id !== id; })); }
function _projSettingsOpen() {
    var pg = document.getElementById('settings-page-templates');
    return !!(pg && pg.style.display !== 'none' && document.body.classList.contains('settings-modal-open'));
}
function _projRefreshCaches() {
    return _projFetchAll().then(function (list) {
        _projCache(list);
        if (_projSettingsOpen()) { _renderSettingsTemplateListFromData(list); _projRenderPending(); }
        return list;
    });
}
// Avgjørelser og innsending (bakgrunn etter henting, maks hvert 30. sekund).
function _projSync(shared, own) {
    if (!_projSharedOk) return;
    if (isAdmin) { _sugLoadPending(); return; }
    var byId = {}, byKey = {};
    shared.forEach(function (p) { byId[p.id] = p; byKey[_projNorm(p.prosjektnavn) + '|' + _projNorm(p.prosjektnr)] = p; });
    var changed = false;
    _projStore.listSuggMine().then(function (sugs) {
        sugs = sugs.filter(function (s) { return (s.kind || 'project') === 'project'; });   // materialer/personer: egne synker
        var bySugg = {};
        sugs.forEach(function (s) { bySugg[s.templateId] = s; });
        // 1) Admins avgjørelser
        sugs.forEach(function (s) {
            if (s.status === 'pending') return;
            var mine = own.filter(function (p) { return p.id === s.templateId; })[0];
            if (s.status === 'approved' || s.status === 'merged') {
                var target = byId[s.approvedId];
                if (mine && target) {
                    try { _propagateProjectCorrection(_projStrip(mine), target); } catch (e) {}
                    // Min reiseavstand følger med til det felles prosjektet (har jeg ikke en fra før).
                    if (mine.timebokBracketId && !(_projOverrides()[target.id])) _projSaveOverride(target.id, mine.timebokBracketId);
                }
                if (mine) _projStore.setOwn(mine.id, { forslag: s.status, mergedInto: s.approvedId || null }, true);
            } else if (s.status === 'rejected' && mine) {
                _projStore.setOwn(mine.id, { forslag: 'rejected' }, true);
            }
            _projStore.delSugg(s.id).catch(function () {});
            changed = true;
        });
        // 2) Egne prosjekter fra før denne versjonen → sendes inn. Helt likt et felles
        //    prosjekt (navn + nr) → kobles til det uten å plage admin.
        own.forEach(function (p) {
            if (byId[p.id] || p.forslag || bySugg[p.id]) return;
            var twin = byKey[_projNorm(p.prosjektnavn) + '|' + _projNorm(p.prosjektnr)];
            if (twin) {
                try { _propagateProjectCorrection(_projStrip(p), twin); } catch (e) {}
                if (p.timebokBracketId && !(_projOverrides()[twin.id])) _projSaveOverride(twin.id, p.timebokBracketId);
                _projStore.setOwn(p.id, { forslag: 'merged', mergedInto: twin.id }, true);
            } else {
                _projSubmit(p);
                _projStore.setOwn(p.id, { forslag: 'pending' }, true);
            }
            changed = true;
        });
        if (changed) setTimeout(_projRefreshCaches, 300);
    }).catch(function (e) { console.warn('Prosjektforslag:', e && (e.code || e.message)); });
}
function _projSubmit(p) {
    var me = _projMe();
    var data = Object.assign(_projStrip(p), {
        kind: 'project', templateId: p.id, createdBy: me, createdByName: _projMyName(),
        suggestedAt: new Date().toISOString(), status: 'pending'
    });
    delete data.timebokBracketId; delete data.forslag;
    return _projStore.setSugg(me + '_' + p.id, data).catch(function (e) { console.error('Send prosjektforslag:', e); });
}

// ── Admin: til godkjenning ──
// Egne (ikke felles ennå) — admins gamle personlige prosjekter.
function _projOwnUnshared() {
    return safeParseJSON(TEMPLATE_KEY, []).filter(function (p) { return p._own; });
}
function _projLoadPending() { return _sugLoadPending(); }
function _projPendingCount() { return (_sugIsAdmin() && (_projSharedOk !== false || _admDev())) ? _sugPending.length : 0; }
// Varsel til admin (se TIL GODKJENNING): tall på Meny-knappen, på Admin › Til godkjenning og
// et banner på Hjem. Bare montørenes forslag teller — admins egne gamle prosjekter er ikke noe
// som «venter på» noen (de står på Prosjekter-siden).
function _projUpdateBadges() {
    var n = _projPendingCount();
    ['inbox-badge', 'menu-pending-dot'].forEach(function (id) {
        var b = document.getElementById(id);
        if (b) { b.textContent = n; b.hidden = !n; }
    });
    var hb = document.getElementById('home-inbox');
    var txt = _sugBannerTexts(n);
    if (hb) {
        hb.hidden = !n;
        if (n) {
            document.getElementById('home-inbox-title').textContent = txt.title;
            document.getElementById('home-inbox-desc').textContent = txt.desc;
        }
    }
}
function _sugBannerTexts(n) {
    var cnt = function (k) { return _sugPending.filter(function (s) { return (s.kind || 'project') === k; }).length; };
    var np = cnt('project'), nm = cnt('material'), nq = cnt('person');
    return {
        title: t(n === 1 ? 'inbox_banner_one' : 'inbox_banner', n),
        desc: [np ? t(np === 1 ? 'inbox_n_project' : 'inbox_n_projects', np) : '', nm ? t(nm === 1 ? 'inbox_n_material' : 'inbox_n_materials', nm) : '', nq ? t(nq === 1 ? 'inbox_n_person' : 'inbox_n_persons', nq) : ''].filter(Boolean).join(' \u00b7 ')
    };
}
// Prosjekter-siden: bare admins egne gamle prosjekter (ikke felles ennå) — montørenes forslag
// ligger i innboksen (Admin › Til godkjenning).
function _projRenderPending() {
    var wrap = document.getElementById('proj-pending-wrap');
    if (!wrap) return;
    var own = (isAdmin && _projSharedOk) ? _projOwnUnshared() : [];
    wrap.hidden = !own.length;
    if (!own.length) return;
    var h = '<div class="proj-own-head"><span class="adm-sub">' + escapeHtml(t('proj_own_unshared_hint')) + '</span>' +
        '<button type="button" class="proj-share-all" onclick="projShareAllOwn()">' + escapeHtml(t('proj_share_all')) + '</button></div>';
    own.forEach(function (p) {
        var sub = [p.prosjektnr, p.oppdragsgiver].filter(Boolean).map(escapeHtml).join(' \u2022 ');
        h += '<div class="adm-user proj-pending-row" onclick="openProjectReview(null, \'' + escapeJsStringAttr(p.id) + '\')">' +
            '<span class="adm-main"><span class="adm-name">' + (escapeHtml(p.prosjektnavn) || t('no_name')) + '</span>' +
            (sub ? '<span class="adm-sub">' + sub + '</span>' : '') + '</span><span class="set-chev">&rsaquo;</span></div>';
    });
    document.getElementById('proj-pending-list').innerHTML = h;
    document.getElementById('proj-pending-count').textContent = own.length;
}
// Åpne et forslag (eller et eget, ikke felles prosjekt) i prosjektskjemaet til vurdering.
function openProjectReview(suggId, ownId) {
    var s = suggId ? _projPending.filter(function (x) { return x.id === suggId; })[0] : null;
    var own = ownId ? _projOwnUnshared().filter(function (x) { return x.id === ownId; })[0] : null;
    if (!s && !own) return;
    showTemplateEditor(null, s ? { sugg: s } : { own: own });
}
function _projReviewData() { return (_projReview && (_projReview.sugg || _projReview.own)) || null; }
function _projReviewId() { return _projReview ? (_projReview.sugg ? _projReview.sugg.templateId : _projReview.own.id) : null; }
function _projAfterReview(msgKey) {
    closeTemplateEditor();
    showNotificationModal(t(msgKey), true);
    _projRefreshCaches().then(function () { return _sugLoadPending(); }).then(_projRenderPending);
}
// Godkjenn: felles prosjekt med samme id som montørens (Timebok-dagene peker riktig).
function _projApprove(data) {
    var r = _projReview, src = _projReviewData();
    if (!src) return;
    var id = _projReviewId();
    var shared = Object.assign({}, data, {
        active: true, createdAt: src.createdAt || src.suggestedAt || new Date().toISOString(),
        createdBy: r.sugg ? r.sugg.createdBy : (src.createdBy || _projMe()),
        approvedAt: new Date().toISOString(), approvedBy: _projMe()
    });
    _projStore.setShared(id, shared).then(function () {
        if (r.sugg) return _projStore.setSugg(r.sugg.id, { status: 'approved', approvedId: id, decidedAt: new Date().toISOString() }, true);
        // Eget prosjekt: min reiseavstand blir min personlige verdi, rettelser skrives ut i mine skjemaer.
        if (data.timebokBracketId) _projSaveOverride(id, data.timebokBracketId);
        _projStore.setOwn(id, { forslag: 'approved' }, true);
        if (_projIdentityChanged(src, data)) _propagateProjectCorrection(_projStrip(src), Object.assign({ id: id }, data));
    }).then(function () { _projAfterReview('proj_approved'); }, function (e) {
        console.error('Godkjenn prosjekt:', e);
        showNotificationModal(t('proj_action_failed'));
    });
}
function projMergeInto(targetId) {
    var r = _projReview, src = _projReviewData();
    var target = safeParseJSON(TEMPLATE_KEY, []).filter(function (p) { return p.id === targetId && p._shared; })[0];
    if (!src || !target) return;
    showConfirmModal(t('proj_merge_confirm', target.prosjektnavn || ''), function () {
        var p;
        if (r.sugg) p = _projStore.setSugg(r.sugg.id, { status: 'merged', approvedId: targetId, decidedAt: new Date().toISOString() }, true);
        else {
            if (src.timebokBracketId && !_projOverrides()[targetId]) _projSaveOverride(targetId, src.timebokBracketId);
            _projStore.setOwn(src.id, { forslag: 'merged', mergedInto: targetId }, true);
            _propagateProjectCorrection(_projStrip(src), target);
            p = Promise.resolve();
        }
        p.then(function () { _projAfterReview('proj_merged'); }, function (e) {
            console.error('Slå sammen prosjekt:', e);
            showNotificationModal(t('proj_action_failed'));
        });
    }, t('proj_merge_btn'), '#E8501A');
}
function projRejectSuggestion() {
    var r = _projReview;
    if (!r || !r.sugg) return;
    showConfirmModal(t('proj_reject_confirm'), function () {
        _projStore.setSugg(r.sugg.id, { status: 'rejected', decidedAt: new Date().toISOString() }, true)
            .then(function () { _projAfterReview('proj_rejected'); }, function (e) {
                console.error('Avvis prosjekt:', e);
                showNotificationModal(t('proj_action_failed'));
            });
    }, t('proj_reject_btn'));
}
// Admins gamle personlige prosjekter → felles for firmaet som er valgt nå.
function projShareAllOwn() {
    var own = _projOwnUnshared();
    if (!own.length) return;
    showConfirmModal(t('proj_share_all_confirm', own.length, _firmaName(_firma())), function () {
        Promise.all(own.map(function (p) {
            return _projStore.setShared(p.id, Object.assign(_projStrip(p), { active: p.active !== false })).then(function () {
                if (p.timebokBracketId) _projSaveOverride(p.id, p.timebokBracketId);
                _projStore.setOwn(p.id, { forslag: 'approved' }, true);
            });
        })).then(function () {
            showNotificationModal(t('proj_shared_all', own.length), true);
            _projRefreshCaches().then(_projRenderPending);
        }, function (e) {
            console.error('Gjør felles:', e);
            showNotificationModal(t('proj_action_failed'));
        });
    }, t('proj_share_all'), '#E8501A');
}

// ── «Finnes allerede?»: felles prosjekter som ligner (samme nr, eller navnet nesten likt) ──
function _projLev(a, b) {
    if (Math.abs(a.length - b.length) > 2) return 3;
    var prev = [], cur, i, j;
    for (j = 0; j <= b.length; j++) prev[j] = j;
    for (i = 1; i <= a.length; i++) {
        cur = [i];
        for (j = 1; j <= b.length; j++) cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
        prev = cur;
    }
    return prev[b.length];
}
function _projSimilar(name, nr, exceptId) {
    var n = _projNorm(name), r = _projNorm(nr);
    if (n.length < 3 && r.length < 2) return [];
    return safeParseJSON(TEMPLATE_KEY, []).filter(function (p) {
        if (!p._shared || p.id === exceptId || p.active === false) return false;
        var pn = _projNorm(p.prosjektnavn), pr = _projNorm(p.prosjektnr);
        if (r.length >= 2 && pr && r === pr) return true;
        if (n.length >= 4 && pn && (pn.indexOf(n) !== -1 || n.indexOf(pn) !== -1)) return true;
        return n.length >= 5 && _projLev(n, pn) <= 2;
    }).slice(0, 3);
}
// Tegnes under feltene i prosjektskjemaet: ved nytt prosjekt («Bruk dette») og ved
// vurdering av et forslag («Slå sammen»). Ikke ved redigering av et eksisterende.
function _projRenderSimilar() {
    var box = document.getElementById('tpl-similar');
    if (!box) return;
    var reviewing = !!_projReview;
    if (_editingTemplateId || !_projSharedOk) { box.hidden = true; return; }
    var list = _projSimilar(document.getElementById('tpl-edit-prosjektnavn').value, document.getElementById('tpl-edit-prosjektnr').value, _projReviewId());
    box.hidden = !list.length;
    if (!list.length) { box.innerHTML = ''; return; }
    box.innerHTML = '<div class="tpl-similar-title">' + escapeHtml(t(reviewing ? 'proj_similar_review' : 'proj_similar_new')) + '</div>' +
        list.map(function (p) {
            var sub = [p.prosjektnr, p.oppdragsgiver].filter(Boolean).map(escapeHtml).join(' • ');
            return '<div class="tpl-similar-row"><span class="tpl-similar-text"><span class="tpl-similar-name">' + escapeHtml(p.prosjektnavn || '') + '</span>' +
                (sub ? '<span class="tpl-similar-sub">' + sub + '</span>' : '') + '</span>' +
                '<button type="button" class="tpl-similar-btn" onclick="' + (reviewing ? 'projMergeInto' : 'projUseExisting') + '(\'' + escapeJsStringAttr(p.id) + '\')">' +
                escapeHtml(t(reviewing ? 'proj_merge_btn' : 'proj_use_btn')) + '</button></div>';
        }).join('');
}
// «Bruk dette» ved nytt prosjekt: ta i bruk det felles prosjektet i stedet for å lage et nytt.
function projUseExisting(id) {
    var p = safeParseJSON(TEMPLATE_KEY, []).filter(function (x) { return x.id === id; })[0];
    if (!p) return;
    var fromPicker = _templateEditorFromPicker, fromTimebok = _templateEditorFromTimebok;
    _templateEditorFromPicker = false; _templateEditorFromTimebok = false;
    closeTemplateEditor();
    if (fromPicker) { _setTemplatePickerHidden(false); _applyTemplateToForm(p); }
    else if (fromTimebok) { if (_timebokPickerTarget) _selectTimebokProject(id); }
    else showTemplateEditor(id);
}

// ═══ MONTØRENS MATERIALER + FORSLAG (15-11-2026) ═══════════════════════════
// Samme ordning som prosjekter (se FELLES PROSJEKTER over): materiallista (firms/{f}/settings/
// materials + kappe-katalogen) eies av admin. Montøren kan legge til et materiale (eller en ny
// enhet/variant på et eksisterende, eller et isolasjons-/festemiddelprodukt) rett i velgeren:
//   • PERSONLIG med en gang: users/{uid}/settings/my_materials ({ list }) + MY_MATERIALS_KEY,
//     flettes inn i velgeren (cachedMaterialOptions) og kappe-katalogen (getKappeCatalog).
//   • Forslag til admin i SAMME samling som prosjektforslagene (firms/{f}/projectSuggestions,
//     kind:'material') — samme Firestore-regler, ingen nye.
//   • Admin (Admin › Til godkjenning): Godkjenn (kan rette navn/enheter) → felles materialliste,
//     Slå sammen med et eksisterende, Avvis (blir værende personlig).
//   • Montørens app plukker opp avgjørelsen og skjuler den personlige kopien (det felles har tatt
//     over). Lagrede skjemaer endres ikke — materialnavn i skjemaene er fri tekst (samme som når
//     admin endrer et materialnavn i Admin › Materialer).
var MY_MATERIALS_KEY = 'firesafe_my_materials';
var _matSyncAt = 0;
// Lokal test: hver testrolle har egen personlig liste (to ulike personer).
function _matKey() { return (typeof _admDev === 'function' && _admDev()) ? MY_MATERIALS_KEY + '_' + _projDevRoleKey() : MY_MATERIALS_KEY; }
function _matMine() { var d = safeParseJSON(_matKey(), null); return (d && Array.isArray(d.list)) ? d.list : []; }
function _matSaveMine(list) {
    safeSetItem(_matKey(), JSON.stringify({ list: list }));
    if (!_admDev()) enqueueUserDocSet('settings', 'my_materials', { list: JSON.parse(JSON.stringify(list)) }, 'My materials');
}
function _matFetchMine() {
    if (!currentUser || !db || _admDev()) return Promise.resolve();
    return db.collection('users').doc(currentUser.uid).collection('settings').doc('my_materials').get()
        .then(function (d) { if (d.exists) safeSetItem(MY_MATERIALS_KEY, JSON.stringify({ list: (d.data() || {}).list || [] })); })
        .catch(function (e) { console.warn('Egne materialer:', e && (e.code || e.message)); });
}
// Synlige personlige: ikke godkjent / slått sammen (avviste blir værende, uten «venter»).
function _matVisible() { return _matMine().filter(function (m) { return m.forslag !== 'approved' && m.forslag !== 'merged'; }); }
function _matIsKappeType(type) { return type === 'isolasjon' || type === 'festemiddel'; }
function _matLc(s) { return String(s || '').trim().toLowerCase(); }
function _matUnitStr(u) { return typeof u === 'string' ? u : (u && (u.plural || u.singular)) || ''; }
// Felles materialer (bare admins liste) — fra cachen, uten de personlige.
function _matShared() {
    var stored = localStorage.getItem(MATERIALS_KEY);
    return normalizeMaterialData(stored ? JSON.parse(stored) : null).materials;
}
// Felles + mine (velgeren). Ny enhet på et felles materiale → enhetene slås sammen.
function _matMergeMine(shared) {
    var out = shared.map(function (m) { return Object.assign({}, m); }), idx = {};
    out.forEach(function (m, i) { idx[_matLc(m.name)] = i; });
    _matVisible().forEach(function (m) {
        if (_matIsKappeType(m.type)) return;
        var i = idx[_matLc(m.name)];
        if (i != null) {
            var base = out[i], have = (base.allowedUnits || []).map(function (u) { return _matLc(_matUnitStr(u)); });
            var add = (m.allowedUnits || []).filter(function (u) { return have.indexOf(_matLc(u)) === -1; });
            if (add.length) out[i] = Object.assign({}, base, { allowedUnits: (base.allowedUnits || []).concat(add) });
            return;
        }
        out.push({ name: m.name, type: m.type || 'standard', defaultUnit: m.defaultUnit || 'stk', allowedUnits: (m.allowedUnits || []).slice(), fixedSize: !!m.fixedSize, _mine: true });
        idx[_matLc(m.name)] = out.length - 1;
    });
    return out.sort(function (a, b) { return _cmpText(a.name, b.name); });
}
// Personlige kappe-produkter (isolasjon/festemiddel) — flettes inn i getKappeCatalog (script.js).
function _matMineKappe() {
    return _matVisible().filter(function (m) { return _matIsKappeType(m.type); }).map(function (m) {
        var units = m.type === 'festemiddel' ? ['stk', 'eske'] : ['meter', 'stk'];
        return { name: m.name, type: m.type, units: units, defaultUnit: units[0], usesDimensions: true };
    });
}
// «Venter»-merket i velgeren: materialer jeg har lagt til selv. En ny enhet på et felles
// materiale merkes ikke — materialet i seg selv er jo godkjent.
function _matIsPending(name) {
    var n = _matLc(name);
    if (!n) return false;
    var shared = _matShared().map(function (m) { return _matLc(m.name); });
    return _matMine().some(function (m) {
        if (m.forslag !== 'pending' || shared.indexOf(_matLc(m.name)) !== -1) return false;
        var mn = _matLc(m.name);
        return n === mn || n.indexOf(mn + ' ') === 0;
    });
}
function _matRefreshOptions() {
    if (typeof cachedMaterialOptions === 'undefined') return;
    cachedMaterialOptions = _matMergeMine(_matShared());
}
// Montør legger til (fra velgeren). Returnerer { ok } / { ok:false, dup:true }.
function _matAddMine(name, type, variant, fixedSize) {
    var kappe = _matIsKappeType(type);
    var list = _matMine();
    if (kappe) {
        if (typeof getKappeCatalogProduct === 'function' && getKappeCatalogProduct(name)) return { ok: false, dup: true };
    } else {
        var sh = _matShared().filter(function (m) { return _matLc(m.name) === _matLc(name); })[0];
        if (sh) {
            // Finnes felles: bare en NY enhet gir mening (som admins snarvei).
            var has = (sh.allowedUnits || []).some(function (u) { return _matLc(_matUnitStr(u)) === _matLc(variant); });
            if (type !== 'standard' || !variant || has) return { ok: false, dup: true };
            name = sh.name;
        }
    }
    var mine = list.filter(function (m) { return _matLc(m.name) === _matLc(name) && m.forslag !== 'approved' && m.forslag !== 'merged'; })[0];
    if (mine) {
        if (kappe || !variant || (mine.allowedUnits || []).some(function (u) { return _matLc(u) === _matLc(variant); })) return { ok: false, dup: true };
        mine.allowedUnits = (mine.allowedUnits || []).concat([variant]);
        mine.forslag = 'pending'; mine.submitted = false;
    } else {
        mine = {
            id: Date.now().toString(), name: name, type: type || 'standard', defaultUnit: 'stk',
            allowedUnits: (!kappe && type === 'standard' && variant) ? [variant] : [],
            fixedSize: !!fixedSize && type === 'mansjett', forslag: 'pending', submitted: false,
            createdAt: new Date().toISOString()
        };
        list.push(mine);
    }
    _matSaveMine(list);
    _matRefreshOptions();
    _matSubmit(mine);
    return { ok: true };
}
function _matSubmit(m) {
    if (!_projSharedOk && !_admDev()) return Promise.resolve();   // reglene mangler → sendes ved neste synk
    var me = _projMe();
    var variantOf = !_matIsKappeType(m.type) && _matShared().some(function (s) { return _matLc(s.name) === _matLc(m.name); });
    return _projStore.setSugg(me + '_m_' + m.id, {
        kind: 'material', templateId: m.id, name: m.name, type: m.type, allowedUnits: m.allowedUnits || [],
        fixedSize: !!m.fixedSize, variantOf: variantOf, createdBy: me, createdByName: _projMyName(),
        suggestedAt: new Date().toISOString(), status: 'pending'
    }).then(function () {
        var list = _matMine();
        list.forEach(function (x) { if (x.id === m.id) x.submitted = true; });
        _matSaveMine(list);
    }).catch(function (e) { console.warn('Send materialforslag:', e && (e.code || e.message)); });
}
// Montør: hent admins avgjørelser + send det som ikke kom fram (maks hvert 30. sekund).
function _matSync(force) {
    if (isAdmin || !currentUser) return Promise.resolve();
    if (!force && Date.now() - _matSyncAt < 30000) return Promise.resolve();
    _matSyncAt = Date.now();
    return _projStore.listSuggMine().then(function (sugs) {
        var list = _matMine(), changed = false, byId = {};
        sugs.filter(function (s) { return s.kind === 'material'; }).forEach(function (s) {
            byId[s.templateId] = s;
            if (s.status === 'pending') return;
            list.forEach(function (m) { if (m.id === s.templateId) { m.forslag = s.status; m.decidedName = s.approvedName || null; } });
            _projStore.delSugg(s.id).catch(function () {});
            changed = true;
        });
        list.forEach(function (m) { if (m.forslag === 'pending' && !m.submitted && !byId[m.id]) _matSubmit(m); });
        if (changed) { _matSaveMine(list); _matRefreshOptions(); }
    }).catch(function (e) { console.warn('Materialforslag:', e && (e.code || e.message)); });
}

// ── Admin: vurdere et materialforslag (popup #mat-review-popup) ──
var _matReview = null;
function _matSimilar(name, type) {
    var n = _projNorm(name);
    if (n.length < 3) return [];
    var pool = _matIsKappeType(type)
        ? ((typeof getKappeCatalogProducts === 'function') ? getKappeCatalogProducts(type) : []).map(function (p) { return { name: p.name, type: p.type }; })
        : _matShared();
    return pool.filter(function (m) {
        var mn = _projNorm(m.name);
        if (!mn || mn === n) return mn === n;
        if (n.length >= 4 && (mn.indexOf(n) !== -1 || n.indexOf(mn) !== -1)) return true;
        return n.length >= 5 && _projLev(n, mn) <= 2;
    }).slice(0, 3);
}
function _matTypeLabel(type, fixed) {
    var key = _matIsKappeType(type) ? 'kappe_product_type_' + type : 'material_type_' + (type || 'standard');
    return t(key) + (_matIsKappeType(type) ? '' : _matTypeSubLabel(type || 'standard', fixed));
}
var _matReviewType = 'standard', _matReviewFixed = false;
function openMaterialReview(suggId) {
    var s = _matPendingList().filter(function (x) { return x.id === suggId; })[0];
    if (!s) return;
    _matReview = s;
    _matReviewType = s.type || 'standard';
    _matReviewFixed = !!s.fixedSize;
    document.getElementById('mat-review-note').textContent = t('proj_suggested_by', s.createdByName || '?', _projDateStr(s.suggestedAt)) +
        (s.variantOf ? ' · ' + t('mat_review_variant_note') : '');
    document.getElementById('mat-review-name').value = s.name || '';
    document.getElementById('mat-review-name').disabled = !!s.variantOf;
    document.getElementById('mat-review-units').value = (s.allowedUnits || []).join(', ');
    var dp = getKappePlateForProduct('');
    _pe['mat-review-pe'] = [{ length: parseFloat(dp.length), width: parseFloat(dp.width) }];
    _peRender('mat-review-pe');
    _matReviewTypeChanged();
    document.getElementById('mat-review-popup').classList.add('active');
    _anchorReviewPopup('mat-review-popup', ['#mat-review-units-row', '#mat-review-plate-row']);
}
// Plater (isolasjon): «standard» = første plate (som produkter uten tilknytning). Nederst
// «+ Ny plate …»: finnes ikke riktig størrelse, legges den i registeret og velges med en gang
// (bruker 15-11-2026) — admin slipper å gå via Admin › Materialer › Isolasjon › Plater.
// Toppen står fast mens vinduet er åpent (popup-konvensjonen): forankres der den HØYESTE
// varianten (enheter + plate + ny plate) ville vært sentrert; boksen vokser/krymper nedenfra.
function _anchorReviewPopup(popupId, showSelectors) {
    var p = document.getElementById(popupId);
    var sheet = p && p.querySelector('.template-editor-content');
    if (!sheet) return;
    var els = showSelectors.map(function (sel) { return document.querySelector(sel); }).filter(Boolean);
    var was = els.map(function (el) { return el.hidden; });
    els.forEach(function (el) { el.hidden = false; });
    var h = sheet.offsetHeight;
    els.forEach(function (el, i) { el.hidden = was[i]; });
    _applyPopupTopAnchor(popupId, h);
}
// Typeknapp + hvilke felt som vises (enheter: standard, plate: isolasjon). Ny enhet på et
// materiale som finnes → typen er gitt av det som finnes (låst).
function _matReviewTypeChanged() {
    var s = _matReview, type = _matReviewType;
    var btn = document.getElementById('mat-review-type-btn');
    btn.textContent = _matTypeLabel(type, _matReviewFixed);
    btn.disabled = !!(s && s.variantOf);
    document.getElementById('mat-review-units-row').hidden = type !== 'standard';
    // Plate: rader + feltene for ny plate alltid synlige (ingen «+ Ny plate»-knapp, bruker 15-11-2026).
    document.getElementById('mat-review-plate-row').hidden = type !== 'isolasjon';
    _matRenderSimilar();
    if (typeof window.applyKeyboardLayout === 'function') window.applyKeyboardLayout();
}
function openMatReviewTypePicker() {
    if (!_matReview || _matReview.variantOf) return;
    _renderMatTypePicker(_matReviewType, function (newValue, fixedSize) {
        _matReviewType = newValue;
        _matReviewFixed = !!fixedSize && newValue === 'mansjett';
        _matReviewTypeChanged();
    }, true, _matReviewFixed);
}
function closeMaterialReview() {
    _matReview = null;
    document.getElementById('mat-review-popup').classList.remove('active');
    _clearPopupTopAnchor('mat-review-popup');
}
function _matRenderSimilar() {
    var box = document.getElementById('mat-review-similar');
    var s = _matReview;
    var list = (s && !s.variantOf) ? _matSimilar(document.getElementById('mat-review-name').value, _matReviewType) : [];
    box.hidden = !list.length;
    box.innerHTML = list.length ? '<div class="tpl-similar-title">' + escapeHtml(t('mat_similar_review')) + '</div>' + list.map(function (m) {
        return '<div class="tpl-similar-row"><span class="tpl-similar-text"><span class="tpl-similar-name">' + escapeHtml(m.name) + '</span>' +
            '<span class="tpl-similar-sub">' + escapeHtml(_matTypeLabel(m.type, m.fixedSize)) + '</span></span>' +
            '<button type="button" class="tpl-similar-btn" onclick="materialMergeInto(\'' + escapeJsStringAttr(m.name) + '\')">' + escapeHtml(t('proj_merge_btn')) + '</button></div>';
    }).join('') : '';
}
function _matAfterReview(msgKey) {
    closeMaterialReview();
    showNotificationModal(t(msgKey), true);
    _sugLoadPending();
}
function _matDecide(status, extra) {
    var s = _matReview;
    return _projStore.setSugg(s.id, Object.assign({ status: status, decidedAt: new Date().toISOString() }, extra || {}), true);
}
// Godkjenn → inn i den felles lista (materialer eller kappe-katalogen).
function approveMaterialSuggestion() {
    var s = _matReview;
    if (!s) return;
    var name = (document.getElementById('mat-review-name').value || '').trim();
    if (!name) { document.getElementById('mat-review-name').classList.add('settings-input-error'); return; }
    var type = _matReviewType || 'standard';
    var units = String(document.getElementById('mat-review-units').value || '').split(',').map(function (u) { return u.trim(); }).filter(Boolean);
    if (_matIsKappeType(type)) {
        if (!getKappeCatalogProduct(name)) _addKappeProduct(name, type);
        // Isolasjon: produktets plater fra godkjenningsvinduet (første = standard).
        if (type === 'isolasjon') _setKappeProductPlates(name, _pe['mat-review-pe'] || []);
    } else {
        var list = _matShared();
        var ex = list.filter(function (m) { return _matLc(m.name) === _matLc(name); })[0];
        if (ex) {
            var have = (ex.allowedUnits || []).map(function (u) { return _matLc(_matUnitStr(u)); });
            ex.allowedUnits = (ex.allowedUnits || []).concat(units.filter(function (u) { return have.indexOf(_matLc(u)) === -1; }));
        } else {
            list.push({ name: name, type: type, defaultUnit: 'stk', allowedUnits: type === 'standard' ? units : [], fixedSize: type === 'mansjett' && _matReviewFixed });
        }
        list.sort(function (a, b) { return _cmpText(a.name, b.name); });
        _persistMaterialsDoc(list);
        if (typeof settingsMaterials !== 'undefined' && Array.isArray(settingsMaterials)) { settingsMaterials = list.slice(); }
        _matRefreshOptions();
    }
    _matDecide('approved', { approvedName: name }).then(function () { _matAfterReview('mat_approved'); }, function (e) {
        console.error('Godkjenn materiale:', e);
        showNotificationModal(t('proj_action_failed'));
    });
}
function materialMergeInto(targetName) {
    if (!_matReview) return;
    showConfirmModal(t('mat_merge_confirm', targetName), function () {
        _matDecide('merged', { approvedName: targetName }).then(function () { _matAfterReview('proj_merged'); }, function (e) {
            console.error('Slå sammen materiale:', e);
            showNotificationModal(t('proj_action_failed'));
        });
    }, t('proj_merge_btn'), '#E8501A');
}
function rejectMaterialSuggestion() {
    if (!_matReview) return;
    showConfirmModal(t('mat_reject_confirm'), function () {
        _matDecide('rejected').then(function () { _matAfterReview('proj_rejected'); }, function (e) {
            console.error('Avvis materiale:', e);
            showNotificationModal(t('proj_action_failed'));
        });
    }, t('proj_reject_btn'));
}

// ═══ TIL GODKJENNING — admins innboks (prosjekter + materialer) ═══════════════
// Bruker: admin skal fange opp forslag uten å sjekke Prosjekter/Materialer manuelt, og varselet
// skal være i appen (ikke e-post). Derfor ÉN innboks, Admin › Til godkjenning, og varsel tre
// steder: tall på Meny-knappen, tall på innboks-raden og et banner øverst på Hjem. Tallet er
// LIVE (onSnapshot på forslagene som venter), så det dukker opp mens appen er åpen.
var _sugPending = [];
var _sugUnsub = null, _sugLiveFailed = false;
function _matPendingList() { return _sugPending.filter(function (s) { return s.kind === 'material'; }); }
var SUG_CACHE_KEY = 'firesafe_sug_pending';
function _sugSetPending(list, fromCache) {
    _sugPending = list.sort(function (a, b) { return String(a.suggestedAt || '').localeCompare(String(b.suggestedAt || '')); });
    // Siste kjente liste huskes (pr. firma), så tallet og Hjem-banneret står der med en gang
    // etter omlasting — før Firebase har svart (bruker: «når jeg oppdaterer siden så står ikke
    // forslag i hjem siden eller i meny knappen»).
    if (!fromCache) {
        safeSetItem(SUG_CACHE_KEY, JSON.stringify({ firma: _firma(), list: JSON.parse(JSON.stringify(_sugPending)) }));
        // Ferdig tekst for snutten i index.html, som tegner banner + tall FØR appen har startet.
        var bn = _sugIsAdmin() ? _sugPending.length : 0;
        safeSetItem('firesafe_sug_badge', JSON.stringify(Object.assign({ firma: _firma(), n: bn }, _sugBannerTexts(bn))));
    }
    _projPending = _sugPending.filter(function (s) { return (s.kind || 'project') === 'project'; });
    _projUpdateBadges();
    var pg = document.getElementById('settings-page-admin-inbox');
    if (pg && pg.style.display !== 'none') renderAdminInbox();
}
function _sugIsAdmin() { return !!((typeof isAdmin !== 'undefined' && isAdmin) || (typeof _acc !== 'undefined' && _acc.admin)); }
function _sugLoadPending() {
    if (!_sugIsAdmin()) { _sugSetPending([], true); return Promise.resolve(); }
    // Reglene mangler (felles liste kunne ikke leses) → ingenting å hente; behold det vi har.
    if (_projSharedOk === false && !_admDev()) return Promise.resolve();
    return _projStore.listSuggPending().then(_sugSetPending)
        .catch(function (e) { console.warn('Til godkjenning:', e && (e.code || e.message)); });
}
// Live for admin (startes/stoppes fra _accApply når admin-status er kjent). Ved oppstart:
// lagret liste først (straks synlig), så ferskt fra Firebase. Uten live-tilkobling (lokal test,
// eller reglene mangler) hentes lista ved oppstart og hver gang appen kommer i forgrunnen.
var _sugRestored = false, _sugPolledAt = 0;
function _sugRestoreCache() {
    var c = safeParseJSON(SUG_CACHE_KEY, null);
    if (c && c.firma === _firma() && Array.isArray(c.list)) _sugSetPending(c.list, true);
}
function _sugPollMaybe() {
    if (Date.now() - _sugPolledAt < 15000) return;
    _sugPolledAt = Date.now();
    _sugLoadPending();
}
document.addEventListener('visibilitychange', function () {
    if (!document.hidden && !_sugUnsub && typeof isAdmin !== 'undefined' && isAdmin && currentUser) _sugPollMaybe();
});
function _sugLive() {
    var admin = !!(typeof _acc !== 'undefined' && _acc.admin && currentUser);
    if (admin && !_sugRestored) { _sugRestored = true; _sugRestoreCache(); }
    if (!admin) _sugRestored = false;
    var want = !!(admin && db && !_admDev() && !_sugLiveFailed);
    if (admin && !want && !_sugUnsub) _sugPollMaybe();
    if (want && !_sugUnsub) {
        try {
            _sugUnsub = _firmaRef().collection('projectSuggestions').where('status', '==', 'pending').onSnapshot(function (snap) {
                _sugSetPending(_projDocs(snap));
            }, function (e) {
                console.warn('Til godkjenning (live):', e && (e.code || e.message));
                _sugLiveFailed = true; _sugUnsub = null;
                _sugPollMaybe();
            });
        } catch (e) { _sugUnsub = null; }
    } else if (!want && _sugUnsub) { _sugUnsub(); _sugUnsub = null; }
}
function openAdminInbox() {
    if (!document.body.classList.contains('settings-modal-open')) _showSettingsDirectly();
    showSettingsPage('admin-inbox');
}
// Fanen «Hva sendes hit» (bruker 15-11-2026: «jeg ønsker oversikt over hva som blir sendt som et
// forslag»). Bare oversikt — ingen av/på (av = montøren står fast, eller egne ting admin aldri
// ser). Hold i sync med _projSubmit / _matSubmit / _pplSubmit.
function _renderInboxRules() {
    var host = document.getElementById('admin-inbox-rules');
    if (!host) return;
    var row = function (yes, title, sub) {
        return '<div class="inbox-rule"><span class="inbox-rule-ico' + (yes ? ' yes' : '') + '" aria-hidden="true">' + (yes ? '✓' : '–') + '</span>' +
            '<span class="inbox-rule-text"><span class="inbox-rule-title">' + escapeHtml(t(title)) + '</span>' +
            (sub ? '<span class="inbox-rule-sub">' + escapeHtml(t(sub)) + '</span>' : '') + '</span></div>';
    };
    host.innerHTML =
        '<div class="set-section-title">' + escapeHtml(t('inbox_rules_yes')) + '</div>' +
        '<div class="set-card inbox-rules">' +
            row(true, 'inbox_r_proj', 'inbox_r_proj_sub') +
            row(true, 'inbox_r_mat', 'inbox_r_mat_sub') +
            row(true, 'inbox_r_iso', 'inbox_r_iso_sub') +
            row(true, 'inbox_r_fast', 'inbox_r_fast_sub') +
            row(true, 'inbox_r_ppl', 'inbox_r_ppl_sub') +
        '</div>' +
        '<div class="set-foot">' + escapeHtml(t('inbox_rules_yes_foot')) + '</div>' +
        '<div class="set-section"><div class="set-section-title">' + escapeHtml(t('inbox_rules_no')) + '</div>' +
        '<div class="set-card inbox-rules">' +
            row(false, 'inbox_r_dims', 'inbox_r_dims_sub') +
            row(false, 'inbox_r_plate', 'inbox_r_plate_sub') +
            row(false, 'inbox_r_lists', 'inbox_r_lists_sub') +
        '</div></div>';
}
function renderAdminInbox() {
    var host = document.getElementById('admin-inbox-body');
    if (!host) return;
    var projs = _sugPending.filter(function (s) { return (s.kind || 'project') === 'project'; });
    var mats = _matPendingList();
    var ppls = _sugPending.filter(function (s) { return s.kind === 'person'; });
    var h = '';
    if (!projs.length && !mats.length && !ppls.length) {
        h += '<div class="set-card inbox-empty">' + escapeHtml(t('inbox_empty')) + '</div>';
    }
    var row = function (title, sub, by, onclick) {
        return '<div class="adm-user proj-pending-row" onclick="' + onclick + '">' +
            '<span class="adm-main"><span class="adm-name">' + title + '</span>' +
            (sub ? '<span class="adm-sub">' + sub + '</span>' : '') +
            '<span class="adm-sub proj-by">' + by + '</span></span><span class="set-chev">&rsaquo;</span></div>';
    };
    if (projs.length) {
        h += '<div class="set-section-title"><span>' + escapeHtml(t('settings_prosjekter_section')) + '</span> <span class="set-count">' + projs.length + '</span></div>' +
            '<div class="set-card adm-list">' + projs.map(function (s) {
                return row(escapeHtml(s.prosjektnavn) || t('no_name'),
                    [s.prosjektnr, s.oppdragsgiver].filter(Boolean).map(escapeHtml).join(' • '),
                    escapeHtml(t('proj_suggested_by', s.createdByName || '?', _projDateStr(s.suggestedAt))),
                    'openProjectReview(\'' + escapeJsStringAttr(s.id) + '\')');
            }).join('') + '</div>';
    }
    if (mats.length) {
        h += '<div class="set-section' + (projs.length ? '' : ' inbox-first') + '"><div class="set-section-title"><span>' + escapeHtml(t('settings_materials')) + '</span> <span class="set-count">' + mats.length + '</span></div>' +
            '<div class="set-card adm-list">' + mats.map(function (s) {
                var sub = _matTypeLabel(s.type, s.fixedSize) + ((s.allowedUnits || []).length ? ' · ' + s.allowedUnits.join(', ') : '');
                if (s.variantOf) sub = t('mat_new_unit_on', (s.allowedUnits || []).join(', '));
                return row(escapeHtml(s.name), escapeHtml(sub),
                    escapeHtml(t('proj_suggested_by', s.createdByName || '?', _projDateStr(s.suggestedAt))),
                    'openMaterialReview(\'' + escapeJsStringAttr(s.id) + '\')');
            }).join('') + '</div></div>';
    }
    if (ppls.length) {
        h += '<div class="set-section' + (projs.length || mats.length ? '' : ' inbox-first') + '"><div class="set-section-title"><span>' + escapeHtml(t('inbox_people')) + '</span> <span class="set-count">' + ppls.length + '</span></div>' +
            '<div class="set-card adm-list">' + ppls.map(function (s) {
                return row(escapeHtml(s.name), '', escapeHtml(t('proj_suggested_by', s.createdByName || '?', _projDateStr(s.suggestedAt))),
                    'openPersonReview(\'' + escapeJsStringAttr(s.id) + '\')');
            }).join('') + '</div></div>';
    }
    host.innerHTML = h;
    var cnt = document.getElementById('inbox-tab-count');
    if (cnt) cnt.textContent = (projs.length + mats.length + ppls.length) || '';
    _renderInboxRules();
}

// ═══ PERSONER: MONTØRENS KOLLEGER + FORSLAG (15-11-2026) ═════════════════════
// Samme ordning som prosjekter og materialer. Personvelgeren (Arbeidstid) viser de ansatte
// (Admin › Brukere) + personer uten innlogging (innleide, lærlinger …) som admin har godkjent.
//   • Montør skriver bare NAVNET under «Annen person» → føres på bestillingen med en gang og
//     huskes i montørens egen liste (users/{uid}/settings/my_people, MY_PEOPLE_KEY), med
//     «Venter»-merke. Forslag til admin i projectSuggestions (kind:'person').
//   • Admin (Til godkjenning): Godkjenn (kan rette skrivemåten) → «Uten innlogging»-lista
//     (firms/{f}/settings/ansatte_extra), som flettes inn i den felles navnelista (settings/ansatte)
//     → alle kan velge personen. Slå sammen (det er en som finnes) · Avvis (blir hos montøren).
//   • Admin som skriver et nytt navn i velgeren legger det rett i «Uten innlogging».
//   • Lagrede ordresedler endres ikke når admin retter skrivemåten (som materialer).
var MY_PEOPLE_KEY = 'firesafe_my_people';
var ANS_EXTRA_KEY = 'firesafe_ansatte_extra';
var _pplSyncAt = 0;
function _pplKey() { return (typeof _admDev === 'function' && _admDev()) ? MY_PEOPLE_KEY + '_' + _projDevRoleKey() : MY_PEOPLE_KEY; }
function _pplMine() { var d = safeParseJSON(_pplKey(), null); return (d && Array.isArray(d.list)) ? d.list : []; }
function _pplSaveMine(list) {
    safeSetItem(_pplKey(), JSON.stringify({ list: list }));
    if (!_admDev()) enqueueUserDocSet('settings', 'my_people', { list: JSON.parse(JSON.stringify(list)) }, 'My people');
}
function _pplFetchMine() {
    if (!currentUser || !db || _admDev()) return Promise.resolve();
    return db.collection('users').doc(currentUser.uid).collection('settings').doc('my_people').get()
        .then(function (d) { if (d.exists) safeSetItem(MY_PEOPLE_KEY, JSON.stringify({ list: (d.data() || {}).list || [] })); })
        .catch(function (e) { console.warn('Egne personer:', e && (e.code || e.message)); });
}
// Synlige personlige (godkjente/sammenslåtte ligger nå i den felles lista).
function _pplVisible() { return _pplMine().filter(function (p) { return p.forslag !== 'approved' && p.forslag !== 'merged'; }); }
// Alle navn i den felles lista (fullt navn + fornavn), små bokstaver — for «finnes allerede».
function _pplSharedNames() {
    var out = [];
    getAnsatte().forEach(function (a) {
        var f = String(a.fornavn || '').trim(), full = (f + ' ' + String(a.etternavn || '').trim()).trim();
        if (full) out.push(full.toLowerCase());
        if (f) out.push(f.toLowerCase());
    });
    return out;
}
// «Uten innlogging» (admin eier) — cache + firma-dokument.
function _ansExtra() { var d = safeParseJSON(ANS_EXTRA_KEY, null); return (d && Array.isArray(d.list)) ? d.list : []; }
function _ansExtraLoad() {
    if (!currentUser || !db || _admDev()) return Promise.resolve(_ansExtra());
    return _fsSettings('ansatte_extra').get().then(function (d) {
        var list = d.exists ? ((d.data() || {}).list || []) : [];
        safeSetItem(ANS_EXTRA_KEY, JSON.stringify({ list: list }));
        return list;
    }).catch(function () { return _ansExtra(); });
}
function _ansExtraSave(list) {
    list.sort(function (a, b) { return _cmpText(a.navn, b.navn); });
    safeSetItem(ANS_EXTRA_KEY, JSON.stringify({ list: list }));
    var p = (currentUser && db && !_admDev())
        ? _fsSettings('ansatte_extra').set({ list: list }).catch(function (e) { console.warn('Uten innlogging ble ikke lagret:', e && e.code); })
        : Promise.resolve();
    // Den felles navnelista (personvelgeren) bygges av Brukere + denne lista.
    var users = (typeof _admUsers !== 'undefined' && Object.keys(_admUsers).length) ? Promise.resolve(_admUsers)
        : _admStore.load().then(function (res) { _admLastRes = res; _admUsers = _admBuildUsers(res); return _admUsers; });
    users.then(function (u) { _admPublishAnsatte(u); }).catch(function () {});
    return p;
}
function _ansExtraAdd(navn) {
    navn = String(navn || '').trim();
    if (!navn) return false;
    var list = _ansExtra();
    if (list.some(function (x) { return x.navn.toLowerCase() === navn.toLowerCase(); })) return false;
    list.push({ id: Date.now().toString(36), navn: navn });
    _ansExtraSave(list);
    return true;
}
// Velgerens «+»: husk personen (admin → felles lista, montør → egen liste + forslag).
function _pplRemember(navn) {
    navn = String(navn || '').trim();
    if (!navn || !currentUser) return;
    if (_pplSharedNames().indexOf(navn.toLowerCase()) !== -1) return;
    if (isAdmin) { _ansExtraAdd(navn); return; }
    var list = _pplMine();
    if (list.some(function (p) { return p.name.toLowerCase() === navn.toLowerCase() && p.forslag !== 'approved' && p.forslag !== 'merged'; })) return;
    var p = { id: Date.now().toString(36), name: navn, forslag: 'pending', submitted: false, createdAt: new Date().toISOString() };
    list.push(p);
    _pplSaveMine(list);
    _pplSubmit(p);
}
function _pplSubmit(p) {
    if (!_projSharedOk && !_admDev()) return Promise.resolve();   // reglene mangler → sendes ved neste synk
    var me = _projMe();
    return _projStore.setSugg(me + '_p_' + p.id, {
        kind: 'person', templateId: p.id, name: p.name, createdBy: me, createdByName: _projMyName(),
        suggestedAt: new Date().toISOString(), status: 'pending'
    }).then(function () {
        var list = _pplMine();
        list.forEach(function (x) { if (x.id === p.id) x.submitted = true; });
        _pplSaveMine(list);
    }).catch(function (e) { console.warn('Send personforslag:', e && (e.code || e.message)); });
}
// Montør: hent admins avgjørelser + send det som ikke kom fram (maks hvert 30. sekund).
function _pplSync(force) {
    if (isAdmin || !currentUser) return Promise.resolve();
    if (!force && Date.now() - _pplSyncAt < 30000) return Promise.resolve();
    _pplSyncAt = Date.now();
    return _pplFetchMine().then(function () { return _projStore.listSuggMine(); }).then(function (sugs) {
        var list = _pplMine(), changed = false, byId = {};
        sugs.filter(function (s) { return s.kind === 'person'; }).forEach(function (s) {
            byId[s.templateId] = s;
            if (s.status === 'pending') return;
            list.forEach(function (p) { if (p.id === s.templateId) { p.forslag = s.status; p.decidedName = s.approvedName || null; } });
            _projStore.delSugg(s.id).catch(function () {});
            changed = true;
        });
        list.forEach(function (p) { if (p.forslag === 'pending' && !p.submitted && !byId[p.id]) _pplSubmit(p); });
        if (changed) _pplSaveMine(list);
    }).catch(function (e) { console.warn('Personforslag:', e && (e.code || e.message)); });
}

// ── Admin: vurdere en person (popup #ppl-review-popup) ──
var _pplReview = null;
function _pplSimilar(name) {
    var n = _projNorm(name);
    if (n.length < 2) return [];
    var seen = {}, out = [];
    getAnsatte().forEach(function (a) {
        var full = (String(a.fornavn || '') + ' ' + String(a.etternavn || '')).trim();
        var fn = _projNorm(full), first = _projNorm(a.fornavn);
        if (!fn || seen[fn]) return;
        if (fn === n || first === n || (n.length >= 3 && (fn.indexOf(n) !== -1 || n.indexOf(fn) !== -1)) || (n.length >= 5 && _projLev(n, fn) <= 2)) {
            seen[fn] = 1; out.push(full);
        }
    });
    return out.slice(0, 3);
}
var _pplKind = 'extra';
function openPersonReview(suggId) {
    var s = _sugPending.filter(function (x) { return x.id === suggId; })[0];
    if (!s) return;
    _pplReview = s;
    document.getElementById('ppl-review-note').textContent = t('proj_suggested_by', s.createdByName || '?', _projDateStr(s.suggestedAt));
    var parts = String(s.name || '').trim().split(/\s+/).filter(Boolean);
    document.getElementById('ppl-review-fornavn').value = parts.shift() || '';
    document.getElementById('ppl-review-etternavn').value = parts.join(' ');
    _pplSetKind('extra');
    _pplRenderSimilar();
    document.getElementById('ppl-review-popup').classList.add('active');
    _anchorReviewPopup('ppl-review-popup', []);
}
function _pplReviewName() {
    return (String(document.getElementById('ppl-review-fornavn').value || '').trim() + ' ' + String(document.getElementById('ppl-review-etternavn').value || '').trim()).trim();
}
// Uten innlogging (bare navn) eller bruker (hele brukerskjemaet åpnes ved «Videre»).
function _pplSetKind(kind) {
    _pplKind = kind === 'user' ? 'user' : 'extra';
    document.querySelectorAll('#ppl-review-seg .tb-seg-btn').forEach(function (b) { b.classList.toggle('active', b.getAttribute('data-kind') === _pplKind); });
    document.getElementById('ppl-review-hint').textContent = t(_pplKind === 'user' ? 'ppl_hint_user' : 'ppl_review_hint');
    document.getElementById('ppl-review-ok').textContent = t(_pplKind === 'user' ? 'ppl_next_user' : 'proj_approve_btn');
    if (typeof window.applyKeyboardLayout === 'function') window.applyKeyboardLayout();
}
function closePersonReview() {
    _pplReview = null;
    document.getElementById('ppl-review-popup').classList.remove('active');
    _clearPopupTopAnchor('ppl-review-popup');
}
function _pplRenderSimilar() {
    var box = document.getElementById('ppl-review-similar');
    var list = _pplReview ? _pplSimilar(_pplReviewName()) : [];
    box.hidden = !list.length;
    box.innerHTML = list.length ? '<div class="tpl-similar-title">' + escapeHtml(t('ppl_similar_review')) + '</div>' + list.map(function (nm) {
        return '<div class="tpl-similar-row"><span class="tpl-similar-text"><span class="tpl-similar-name">' + escapeHtml(nm) + '</span></span>' +
            '<button type="button" class="tpl-similar-btn" onclick="personMergeInto(\'' + escapeJsStringAttr(nm) + '\')">' + escapeHtml(t('proj_merge_btn')) + '</button></div>';
    }).join('') : '';
}
function _pplDecide(status, extra) {
    return _projStore.setSugg(_pplReview.id, Object.assign({ status: status, decidedAt: new Date().toISOString() }, extra || {}), true);
}
function _pplAfterReview(msgKey) {
    closePersonReview();
    showNotificationModal(t(msgKey), true);
    _sugLoadPending();
    var pg = document.getElementById('settings-page-admin-users');
    if (pg && pg.style.display !== 'none') renderAdminUsers(true);
}
function approvePersonSuggestion() {
    if (!_pplReview) return;
    var name = _pplReviewName();
    if (!name) { document.getElementById('ppl-review-fornavn').classList.add('settings-input-error'); return; }
    if (_pplKind === 'user') {
        // Hele brukerskjemaet (samme som «+ Legg til bruker») med navnet ferdig utfylt. Forslaget
        // regnes som godkjent først når brukeren er lagret (saveAdmUser → _admFromPersonSugg).
        var sugg = _pplReview;
        var fn = String(document.getElementById('ppl-review-fornavn').value || '').trim();
        var en = String(document.getElementById('ppl-review-etternavn').value || '').trim();
        closePersonReview();
        openAdmUser(null);
        _admFromPersonSugg = sugg;
        document.getElementById('adm-f-fornavn').value = fn;
        document.getElementById('adm-f-etternavn').value = en;
        var em = document.getElementById('adm-f-email');
        if (em) setTimeout(function () { em.focus(); }, 50);
        return;
    }
    _ansExtraLoad().then(function () {
        _ansExtraAdd(name);
        return _pplDecide('approved', { approvedName: name });
    }).then(function () { _pplAfterReview('ppl_approved'); }, function (e) {
        console.error('Godkjenn person:', e);
        showNotificationModal(t('proj_action_failed'));
    });
}
function personMergeInto(targetName) {
    if (!_pplReview) return;
    showConfirmModal(t('ppl_merge_confirm', targetName), function () {
        _pplDecide('merged', { approvedName: targetName }).then(function () { _pplAfterReview('proj_merged'); }, function (e) {
            console.error('Slå sammen person:', e);
            showNotificationModal(t('proj_action_failed'));
        });
    }, t('proj_merge_btn'), '#E8501A');
}
function rejectPersonSuggestion() {
    if (!_pplReview) return;
    showConfirmModal(t('ppl_reject_confirm'), function () {
        _pplDecide('rejected').then(function () { _pplAfterReview('proj_rejected'); }, function (e) {
            console.error('Avvis person:', e);
            showNotificationModal(t('proj_action_failed'));
        });
    }, t('proj_reject_btn'));
}

// ── Admin › Brukere › «Uten innlogging» (bare navn: rader + tekstboks + Legg til) ──
function _admExtraHtml() {
    var list = _ansExtra();
    return '<div class="set-section"><div class="set-section-title"><span>' + escapeHtml(t('adm_extra_title')) + '</span> <span class="set-count">' + (list.length ? '(' + list.length + ')' : '') + '</span></div>' +
        '<div class="set-card"><div class="settings-list-container" id="adm-extra-items">' +
        list.map(function (x, i) { return _kappeSettingsItemHtml(x.navn, i, 'editAdmExtra', 'removeAdmExtra'); }).join('') +
        '</div><div class="settings-add-row set-add-row">' +
            '<input type="text" id="adm-extra-new" autocapitalize="words" placeholder="' + escapeHtml(t('adm_extra_ph')) + '" onkeydown="if(event.key===\'Enter\'){event.preventDefault();addAdmExtra();}">' +
            '<button type="button" class="settings-add-btn" onclick="addAdmExtra()">' + escapeHtml(t('btn_add')) + '</button>' +
        '</div></div>' +
        '<div class="set-foot">' + escapeHtml(t('adm_extra_hint')) + '</div></div>';
}
function addAdmExtra() {
    var inp = document.getElementById('adm-extra-new');
    if (!inp) return;
    var v = String(inp.value || '').trim();
    if (!v) return;
    if (!_ansExtraAdd(v)) { showNotificationModal(t('dag_timer_person_exists')); return; }
    renderAdminUsers(true);
}
function editAdmExtra(idx) {
    var list = _ansExtra(), x = list[idx];
    if (!x) return;
    showInputModal(t('adm_extra_title'), x.navn, function (val) {
        val = String(val || '').trim();
        if (!val || val === x.navn) return;
        x.navn = val;
        _ansExtraSave(list).then(function () { renderAdminUsers(true); });
        renderAdminUsers(true);
    });
}
function removeAdmExtra(idx) {
    var list = _ansExtra(), x = list[idx];
    if (!x) return;
    showConfirmModal(t('kappe_settings_remove_confirm') + ' "' + x.navn + '"?', function () {
        list.splice(idx, 1);
        _ansExtraSave(list);
        renderAdminUsers(true);
    }, t('btn_remove'), '#e74c3c');
}


var _bilHistoryRendered = false;
function showTemplateModal() {
    // Uten tilgang til Hjem (ordreseddel/servicebil/kappe) → første del brukeren har.
    if (!_accAllowed('hjem')) { _accGoStart(); return; }
    closeAllModals();
    history.replaceState(null, '', window.location.pathname);

    showView('template-modal');
    document.body.classList.add('template-modal-open');
    updateToolbarState();
    setTimeout(_homeRenderCounts, 0);
}

function autoFillOrderNumber() {
    const nextNr = getNextOrderNumber();
    if (nextNr !== null) {
        document.getElementById('ordreseddel-nr').value = nextNr;
        document.getElementById('mobile-ordreseddel-nr').value = nextNr;
    }
    updateOrderNrRemaining();
}

// Antall ledige (ubrukte, ikke gitt bort) ordrenummer igjen — vises ved
// Ordreseddel nr.-feltet så montøren ser når serien holder på å gå tom.
const ORDRENR_LOW_THRESHOLD = 10;
function getRemainingOrderNumbers() {
    let data = safeParseJSON(SETTINGS_KEY, null);
    if (!data) return null;
    // Backward compat med gammelt enkelt-område-format
    if (!data.ranges && data.nrStart != null) {
        data = { ranges: [{ start: data.nrStart, end: data.nrEnd }], givenAway: [] };
    }
    if (!data.ranges || data.ranges.length === 0) return null;
    if (!data.givenAway) data.givenAway = [];

    const unavailable = getUsedOrderNumbers();
    data.givenAway.forEach(r => {
        for (let n = r.start; n <= r.end; n++) unavailable.add(String(n));
    });
    let remaining = 0;
    data.ranges.forEach(r => {
        for (let n = r.start; n <= r.end; n++) {
            if (!unavailable.has(String(n))) remaining++;
        }
    });
    return remaining;
}

function updateOrderNrRemaining() {
    const el = document.getElementById('ordrenr-remaining');
    if (!el) return;
    const remaining = getRemainingOrderNumbers();
    if (remaining === null) {
        el.textContent = '';
        el.className = 'ordrenr-remaining';
        return;
    }
    if (remaining <= 0) {
        el.textContent = t('ordrenr_remaining_empty');
        el.className = 'ordrenr-remaining empty';
    } else {
        el.textContent = t('ordrenr_remaining', remaining);
        el.className = 'ordrenr-remaining' + (remaining <= ORDRENR_LOW_THRESHOLD ? ' low' : '');
    }
}

function closeTemplateModal() {
    clearForm();
    preNewFormData = null;
    setFormReadOnly(false);
    autoFillOrderNumber();
    autoFillDefaults();

    showView('view-form');
    document.body.classList.remove('template-modal-open');
    updateToolbarState();
    window.location.hash = 'skjema';
    sessionStorage.setItem('firesafe_form_type', 'own');
    document.getElementById('form-header-title').textContent = t('form_title');
    updateOrderDeleteStates();
    sessionStorage.setItem('firesafe_current', JSON.stringify(getFormData()));
    lastSavedData = getFormDataSnapshot();

    // Scroll to top after all content is set
    requestAnimationFrame(function() {
        document.getElementById('view-form').scrollTop = 0;
        window.scrollTo(0, 0);
    });
}


// ============================================
// ORDRESEDDELNUMMER INNSTILLINGER
// ============================================

// In-memory ranges for settings modal editing
let settingsRanges = [];
let settingsGivenAway = [];

async function getOrderNrSettings() {
    let data = null;
    let fromFirebase = false;
    if (currentUser && db) {
        try {
            const doc = await db.collection('users').doc(currentUser.uid).collection('settings').doc('ordrenr').get();
            if (doc.exists) { data = doc.data(); fromFirebase = true; }
        } catch (e) {
            console.error('Settings error:', e);
        }
    }
    if (!data) {
        const stored = localStorage.getItem(SETTINGS_KEY);
        data = stored ? JSON.parse(stored) : null;
    }
    // Backward compat: convert old {nrStart, nrEnd} to {ranges}
    if (data && !data.ranges && data.nrStart != null) {
        data = { ranges: [{ start: data.nrStart, end: data.nrEnd }] };
    }
    if (data && !data.givenAway) data.givenAway = [];
    // Hold localStorage i synk med Firebase
    if (fromFirebase && data) safeSetItem(SETTINGS_KEY, JSON.stringify(data));
    return data;
}

async function syncSettingsToLocal() {
    if (!db || !currentUser) return;
    try {
        const doc = await db.collection('users').doc(currentUser.uid)
            .collection('settings').doc('ordrenr').get();
        if (doc.exists) {
            safeSetItem(SETTINGS_KEY, JSON.stringify(doc.data()));
        }
    } catch (e) { /* localStorage-cache brukes som fallback */ }
}

function buildOrderNrSettings() {
    return { ranges: settingsRanges.slice(), givenAway: settingsGivenAway.slice() };
}

function getSettingsPageTitle(page) {
    const titles = {
        'min-info': t('settings_min_info'),
        'timebok': t('settings_timebok'),
        'form-ordreseddel': t('form_title'),
        'form-autofill': t('settings_autofill_title'),
        'admin-lists': t('settings_admin_lists'),
        'admin-forms': t('settings_admin_forms'),
        templates: t('settings_prosjekter_section'),
        materials: t('settings_materials'),
        'admin-users': t('settings_admin_users'),
        'admin-satser': t('settings_admin_satser'),
        'admin-employers': t('settings_admin_employers'),
        'admin-inbox': t('settings_admin_inbox')
    };
    return titles[page] || '';
}


