// Flaggrad pr. kode — LIK for alle koder og begge arbeidsgivere (brukerens krav: alle
// knapper på alle koder, knappene bestemmer): Lønn/Ferie/Skatt/Reise/Org + «−Normtid»
// (på = timene trekkes fra normtiden og teller ikke som ført; lagres pr. arbeidsgiver i
// settings.norm[emp].codes). Alltid ÉN rad.
function _tbCodeFlagsHtml(tf, def) {
    var flags = _timebokCodeFlags(def, tf);
    var cells = TIMEBOK_FLAGS.map(function (f) {
        return '<button type="button" class="tb-flag' + (_timebokFlagsHas(flags, f) ? ' on' : '') + '" onclick="_tbSatToggleFlag(this, \'rule:' + def.id + '\', \'' + f + '\')">' + _TB_FLAG_LABELS[f] + '</button>';
    });
    // −Normtid gjelder timer: på koder som føres i kr/stk/km står knappen grå og låst
    // (synlig, med forklaring øverst) — aldri en knapp som kan trykkes uten å gjøre noe.
    var isTime = def.input === 'hours' || def.input === 'clock';
    var on = isTime && getTimebokNormSettings(_tbSatEmp()).codes.indexOf(def.id) !== -1;
    cells.push('<button type="button" class="tb-flag tb-flag-norm' + (on ? ' on' : '') + '"' +
        (isTime ? ' onclick="_tbNormToggleChip(this, \'' + def.id + '\')"' : ' disabled title="' + escapeHtml(t('tb_norm_flag_notime')) + '"') + '>' +
        escapeHtml(t('tb_flag_norm')) + '</button>');
    return '<div class="tb-flags">' + cells.join('') + '</div>';
}
function _tbNormToggleChip(btn, id) {
    var on = !btn.classList.contains('on');
    _tbNormSave(function (c) {
        c.codes = c.codes.filter(function (x) { return x !== id; });
        if (on) c.codes.push(id);
    });
    btn.classList.toggle('on', on);
}
// Slå en kode av/på for arbeidsgiveren som vises i Satser (fletter, rører ikke den andre).
function _tbSatToggleCode(id, on) {
    var emp = _tbSatEmp();
    var off = _timebokDisabledCodes(emp).filter(function (x) { return x !== id; });
    if (!on) off.push(id);
    var all = Object.assign({}, _timebokCompanySrc().disabledCodes || {});
    all[emp] = off;
    _timebokSaveCompany({ disabledCodes: all });
    renderTimebokSatser();
    if (typeof renderTimebokSettings === 'function') renderTimebokSettings();
}
function _tbSatSetRate(id, val) {
    _tbSatUpdate(function (t) {
        t.rates = t.rates || {};
        t.rates[id] = _tbNum(val);
        if (id === 'km') delete t.kmRate;   // eldre felt — rates.km er kilden nå
    });
}
function renderTimebokSatser() {
    var tHost = document.getElementById('tb-satser-tariff');
    var cHost = document.getElementById('tb-satser-codes');
    if (!tHost || !cHost) return;
    var emp = _tbSatEmp();
    var list = getTimebokTariffs(emp);
    var tf = _tbSatserTariff();
    if (!tf) { tHost.innerHTML = ''; cHost.innerHTML = ''; return; }
    var active = _timebokTariffFor(_timebokTodayId(), emp);
    var today = _timebokTodayId();
    var status = (active && active.id === tf.id) ? '<span class="tb-sat-status active">● ' + escapeHtml(t('tb_sat_active')) + '</span>'
        : (String(tf.validFrom) > today ? '<span class="tb-sat-status">' + escapeHtml(t('tb_sat_future')) + '</span>'
        : '<span class="tb-sat-status">' + escapeHtml(t('tb_sat_history')) + '</span>');
    // To faner (kort-stil som resten av Innstillinger): TARIFF (velger + trekk og grunnlag) og
    // TILLEGGSKODER (ett kort pr. kodegruppe, samme rekkefølge som i Timebok). Begge gjelder
    // valgt tariff. Firesafe og Damsgård har hver sine tariffer, satser og koder.
    var num = function (field, unit) {
        return '<span class="tb-satc-rate">' + _tbNumInput(tf[field], "_tbSatSet('" + field + "', this.value)") + '<span class="tb-sat-unit">' + unit + '</span></span>';
    };
    var h = '<div class="set-foot set-foot-top">' + escapeHtml(t('tb_sat_sec_tariff_desc')) + '</div>' +
        // Status («● Aktiv i dag» / historikk / fremtidig) står i overskriftslinja.
        '<div class="set-section-title tb-sat-tariffhead">' + escapeHtml(t('tb_sat_tariff')) + status + '</div>' +
        '<div class="set-card tb-sat-card2">' +
        '<div class="tb-sat-tariffrow">' +
            // Navnet skrives rett i feltet (lagres med en gang); ▾ bytter tariff. ▾ er en
            // usynlig <select> over pila — åpnes som appens liste-popup på mobil, native på PC.
            '<div class="tb-sat-namebox">' +
                // Blyant foran navnet: viser at feltet kan skrives i (ikke bare en liste).
                '<svg class="tb-sat-name-pen" viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 013 3L7 19l-4 1 1-4z"/></svg>' +
                '<input type="text" class="tb-sat-name-input" autocapitalize="sentences" autocomplete="off" aria-label="' + escapeHtml(t('tb_sat_name')) + '" value="' + escapeHtml(tf.name) + '" oninput="_tbFitInputText(this)" onchange="_tbSatSetName(this)">' +
                '<span class="tb-sat-name-arrow"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>' +
                    '<select aria-label="' + escapeHtml(t('tb_sat_tariff')) + '" onchange="_tbSatserSelId=this.value;renderTimebokSatser()">' +
                        list.map(function (x) {
                            return '<option value="' + escapeHtml(x.id) + '" data-desc="' + escapeHtml(t('tb_sat_valid_from') + ' ' + _tbFmtDate(x.validFrom)) + '"' + (x.id === tf.id ? ' selected' : '') + '>' + escapeHtml(x.name) + '</option>';
                        }).join('') +
                    '</select></span>' +
            '</div>' +
            // «Fra <dato>» (gyldig fra; kalender ved trykk) på samme linje som knappene.
            '<div class="tb-sat-tariffbar">' +
                '<span class="tb-input tb-exp-date tb-sat-from" title="' + escapeHtml(t('tb_sat_valid_from')) + '"><span>' + escapeHtml(t('tb_sat_from') + ' ' + _tbFmtDate(tf.validFrom)) + '</span><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>' +
                    '<input type="date" value="' + escapeHtml(tf.validFrom) + '" onchange="_tbSatSetValidFrom(this)"></span>' +
                // «+ Ny» (én popup: navn, gyldig fra, valgfri fil) og Eksporter.
                '<span class="tb-sat-minibtns">' +
                    '<button type="button" class="tb-sat-minibtn" onclick="openTbTariffForm()">' + escapeHtml(t('tb_sat_new')) + '</button>' +
                    '<button type="button" class="tb-sat-minibtn" onclick="exportTbTariff()">' + escapeHtml(t('tb_sat_export')) + '</button>' +
                '</span>' +
            '</div>' +
        '</div>' +
        '</div>' +
        '<div class="set-section"><div class="set-section-title">' + escapeHtml(t('tb_sat_deductions')) + '</div>' +
        '<div class="set-card tb-sat-rows">' +
        _tbSatRow('Feriepenger', null, null, num('feriepenger', '%'), '', t('tb_sat_of_ferie')) +
        _tbSatRow('Fagforening', null, null, num('fagforening', '%'), '', t('tb_sat_of_ferie')) +
        _tbSatRow('Overtidsgrunnlag', null, null, num('overtidsgrunnlag', 'kr/t'), '', t('tb_sat_otg_hint')) +
        // Grunnlaget for normtiden (overtid = ført over normtiden i lønnsperioden) — begge arbeidsgivere.
        (function () {
            var nc = getTimebokNormSettings(emp);
            return _tbSatRow(t('tb_norm_day_hours'), null, null,
                    '<span class="tb-satc-rate">' + _tbNumInput(nc.dayHours, "_tbNormSet('dayHours', this.value)") + '<span class="tb-sat-unit">t</span></span>', '', t('tb_norm_day_hours_sub'));
        })() +
        // Forsikring sist: den eneste posten med flagg-knapper.
        _tbSatRow('Forsikring', 'forsikringFlags', tf.forsikringFlags, num('forsikring', 'kr/mnd')) +
        '</div></div>' +
        // Slett tariff: egen rad nederst (rød, med bekreftelse). Den siste tariffen kan ikke slettes.
        '<div class="set-section"><div class="set-card"><button type="button" class="set-danger-row"' + (list.length <= 1 ? ' disabled' : '') + ' onclick="deleteTbTariff()">' + escapeHtml(t('tb_sat_delete')) + '</button></div></div>';
    // Tilleggskodene: ett kort pr. gruppe — samme grupper og rekkefølge som Autofyll i
    // Meny › Timebok. Reisegodtgjørelse sist i Reise (avstandstabellen i raden).
    var box = '<div class="set-foot set-foot-top">' + escapeHtml(t('tb_sat_sec_codes_desc').replace('{0}', tf.name) + ' ' + t('tb_norm_flag_hint')) + '</div>';
    var firstG = true;
    TIMEBOK_CODE_GROUPS.forEach(function (g) {
        var gc = TIMEBOK_CODES.filter(function (c) { return c.group === g; });   // alle — bryter pr. kode
        var rows = gc.map(function (c) { return _tbCodeRowCompact(tf, c); }).join('');
        if (g === 'reise') rows += _tbCodeRowCompact(tf, null);   // Reisegodtgjørelse sist
        if (!rows) return;
        box += '<div class="' + (firstG ? '' : 'set-section') + '"><div class="set-section-title">' + escapeHtml(_timebokGroupTitle(g)) + '</div>' +
            '<div class="set-card tb-sat-rows tb-codes-card" lang="nb">' + rows + '</div></div>';
        firstG = false;
    });
    tHost.innerHTML = h;
    cHost.innerHTML = box;
    _tbFitInputText(tHost.querySelector('.tb-sat-name-input'));
    if (_tbCodePopId) _tbCodePopRender();   // åpen kode-popup følger endringer (f.eks. «Vises for»)
}
// Hele tariffnavnet skal synes: krymp skrifta (14 → min. 11 px) til teksten får plass i
// feltet. Måles med canvas. ResizeObserver: tilpass på nytt når feltet får bredde (fanen
// vises) eller endrer bredde.
function _tbFitInputText(el) {
    if (!el) return;
    if (window.ResizeObserver && !el._tbFitRO) {
        el._tbFitRO = new ResizeObserver(function () {
            if (el.clientWidth && el.clientWidth !== el._tbFitW) _tbFitInputText(el);
        });
        el._tbFitRO.observe(el);
    }
    if (!el.clientWidth) return;
    el._tbFitW = el.clientWidth;
    el.style.fontSize = '';
    var cs = getComputedStyle(el);
    var avail = el.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight) - 2;
    var ctx = (_tbFitInputText._c = _tbFitInputText._c || document.createElement('canvas')).getContext('2d');
    for (var px = parseFloat(cs.fontSize); px >= 11; px -= 0.5) {
        ctx.font = cs.fontWeight + ' ' + px + 'px ' + cs.fontFamily;
        if (ctx.measureText(el.value).width <= avail) break;
    }
    el.style.fontSize = Math.max(px, 11) + 'px';
}
// ── Satser → normtid (likt for begge arbeidsgivere) ──
// «−Normtid»-flagget pr. kode (_tbCodeFlagsHtml) + Normtid pr. dag i Trekk og grunnlag.
// Helligdager er vanlige (betalte) hverdager. Lagres pr. arbeidsgiver i
// settings/timebok_settings → norm[emp] (arbeidsgiveren som vises i Satser).
function _tbNormSave(fn) {
    var all = Object.assign({}, _timebokCompanySrc().norm || {});
    var emp = _tbSatEmp();
    var cur = getTimebokNormSettings(emp);
    fn(cur);
    all[emp] = cur;
    _timebokSaveCompany({ norm: all });
}
function _tbNormSet(field, val) {
    _tbNormSave(function (c) {
        if (field === 'dayHours') { var n = _tbNum(val); c.dayHours = (n != null && n > 0) ? n : TIMEBOK_NORM_DAY_HOURS; }
    });
}

// Legg til / fjern avstand (navn via input-popup).
function _tbSatAdd(kind) {
    showInputModal(t('tb_sat_add_bracket_title'), '', function (val) {
        var name = String(val || '').trim();
        if (!name) return;
        _tbSatUpdate(function (tf) { (tf.brackets = tf.brackets || []).push({ id: _timebokGenId('br'), label: name, rate: null, ratePrivat: null }); });
        renderTimebokSatser();
    });
}
function _tbSatRemove(kind, id) {
    showConfirmModal(t('tb_sat_remove_confirm'), function () {
        _tbSatUpdate(function (tf) { tf.brackets = (tf.brackets || []).filter(function (x) { return x.id !== id; }); });
        renderTimebokSatser();
    });
}

// «+ Ny»: ÉN popup for ny tariff — Navn, Gyldig fra og (valgfritt) en tariff-fil.
// Med fil hentes satsene fra fila (navn/dato fylles inn fra fila, kan endres); uten fil
// kopieres tariffen som vises (samme avstander med samme id-er, så prosjekter og
// registreringer peker riktig). Finnes en tariff med samme dato: spør om å erstatte den.
var _tbNewFileObj = null;
function openTbTariffForm() {
    _tbNewFileObj = null;
    document.getElementById('tb-tariff-name').value = '';
    _tbNewSetDate(_timebokTodayId());
    _tbNewRenderFile();
    document.getElementById('tb-tariff-popup').classList.add('active');
}
function closeTbTariffForm() {
    document.getElementById('tb-tariff-popup').classList.remove('active');
    _tbNewFileObj = null;
}
function _tbNewSetDate(id) {
    document.getElementById('tb-tariff-date').value = id || '';
    document.getElementById('tb-tariff-date-txt').textContent = id ? _tbFmtDate(id) : '';
}
function _tbNewRenderFile() {
    var f = _tbNewFileObj;
    document.getElementById('tb-tariff-file-name').textContent = f ? f.fileName : t('tb_sat_file_pick');
    document.getElementById('tb-tariff-file-btn').classList.toggle('picked', !!f);
    document.getElementById('tb-tariff-file-clear').style.display = f ? '' : 'none';
    var src = _tbSatserTariff();
    document.getElementById('tb-tariff-file-hint').textContent = f ? t('tb_sat_file_hint_file')
        : t('tb_sat_file_hint_copy').replace('{0}', src ? src.name : '');
}
function _tbNewClearFile() { _tbNewFileObj = null; _tbNewRenderFile(); }
function _tbNewPickFile(input) {
    var file = input.files && input.files[0];
    input.value = '';
    if (!file) return;
    var reader = new FileReader();
    reader.onload = function () {
        var obj;
        try { obj = JSON.parse(reader.result); } catch (e) { obj = null; }
        if (!obj || obj.firesafeTariff !== 1) { showNotificationModal(t('tb_sat_import_bad'), false); return; }
        obj.fileName = file.name;
        _tbNewFileObj = obj;
        if (obj.name) document.getElementById('tb-tariff-name').value = String(obj.name);
        if (/^\d{4}-\d{2}-\d{2}$/.test(String(obj.validFrom || ''))) _tbNewSetDate(obj.validFrom);
        _tbNewRenderFile();
    };
    reader.readAsText(file);
}
function confirmTbTariffForm() {
    var name = document.getElementById('tb-tariff-name').value.trim();
    var date = document.getElementById('tb-tariff-date').value;
    if (!name) { document.getElementById('tb-tariff-name').focus(); return; }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) { showNotificationModal(t('required_field', t('tb_sat_valid_from'))); return; }
    var obj = _tbNewFileObj;
    // Fila kan angi arbeidsgiver («employer»); ellers den som vises i Satser.
    var emp = obj && (obj.employer === 'damsgard' || obj.employer === 'firesafe') ? obj.employer : _tbSatEmp();
    var tf;
    if (obj) tf = _tbTariffFromFile(obj, emp);
    else {
        var src = _tbSatserTariff();
        tf = src ? JSON.parse(JSON.stringify(src)) : _timebokNewTariff(name, date, emp);
        tf.id = _timebokGenId('tf');
    }
    tf.name = name; tf.validFrom = date; tf.employer = emp;
    var doSave = function (replaceId) {
        var l2 = getTimebokTariffs(emp).filter(function (x) { return x.id !== replaceId; });
        l2.push(tf);
        _timebokSaveTariffs(l2, emp);
        _tbSatserEmp = emp;
        _tbSatserSelId = tf.id;
        closeTbTariffForm();
        renderTimebokSatser();
        if (typeof _timebokUpdateDayTotals === 'function') _timebokUpdateDayTotals();
        if (obj) showNotificationModal(t('tb_sat_import_ok'), true);
    };
    var same = getTimebokTariffs(emp).filter(function (x) { return x.validFrom === date; })[0];
    if (same) showConfirmModal(t('tb_sat_import_replace').replace('{0}', same.name + ' · ' + _tbFmtDate(same.validFrom)), function () { doSave(same.id); }, t('tb_sat_replace'), '#E8501A');
    else doSave(null);
}
// Navn / Gyldig fra direkte i tariff-boksen.
function _tbSatSetName(input) {
    var v = input.value.trim();
    if (!v) { renderTimebokSatser(); return; }   // tomt navn → tilbake til det lagrede
    _tbSatUpdate(function (t) { t.name = v; });
    renderTimebokSatser();
}
function _tbSatSetValidFrom(input) {
    var v = input.value;
    var taken = getTimebokTariffs(_tbSatEmp()).some(function (x) { return x.id !== _tbSatserSelId && x.validFrom === v; });
    if (!/^\d{4}-\d{2}-\d{2}$/.test(v) || taken) {
        if (taken) showNotificationModal(t('tb_sat_date_taken'));
        renderTimebokSatser();
        return;
    }
    _tbSatUpdate(function (t) { t.validFrom = v; });
    renderTimebokSatser();
}
function deleteTbTariff() {
    var emp = _tbSatEmp();
    if (getTimebokTariffs(emp).length <= 1) return;
    showConfirmModal(t('tb_sat_delete_confirm'), function () {
        _timebokSaveTariffs(getTimebokTariffs(emp).filter(function (x) { return x.id !== _tbSatserSelId; }), emp);
        _tbSatserSelId = null;
        renderTimebokSatser();
        if (typeof _timebokUpdateDayTotals === 'function') _timebokUpdateDayTotals();
    });
}
// Eksporter: tariffen som vises → fil i SAMME format som «+ Ny → fil» leser (se under),
// så en eksportert fil kan importeres igjen uendret. Bare tariffen (trekk, avstander,
// satser, flagg) — personlige valg (bryter, «Vises for», −Normtid) er ikke med.
// Alltid nedlasting (mobil: Nedlastinger-mappa). IKKE Web Share: Chrome på Android
// avviser .json-filer («Permission denied»).
function exportTbTariff() {
    var tf = _tbSatserTariff();
    if (!tf) return;
    var obj = {
        firesafeTariff: 1, employer: tf.employer === 'damsgard' ? 'damsgard' : 'firesafe',
        name: tf.name, validFrom: tf.validFrom,
        feriepenger: tf.feriepenger, fagforening: tf.fagforening,
        forsikring: tf.forsikring, forsikringFlags: tf.forsikringFlags || [],
        overtidsgrunnlag: tf.overtidsgrunnlag,
        brackets: (tf.brackets || []).map(function (b) { return { label: b.label, firma: b.rate, privat: b.ratePrivat }; }),
        bracketFlags: tf.bracketFlags || [],
        rates: tf.rates || {}, rules: tf.rules || {}
    };
    var empName = obj.employer === 'damsgard' ? 'Damsgård' : 'Firesafe';
    var fname = ('Tariff ' + empName + ' - ' + tf.name + ' - ' + _tbFmtDate(tf.validFrom)).replace(/[\\/:*?"<>|]+/g, '-') + '.json';
    var blob = new Blob([JSON.stringify(obj, null, 2)], { type: 'application/json' });
    var download = function () {
        var a = document.createElement('a');
        a.href = URL.createObjectURL(blob); a.download = fname;
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(function () { URL.revokeObjectURL(a.href); }, 2000);
    };
    download();
    showNotificationModal(t('tb_sat_export_ok').replace('{0}', fname), true);
}

// Tariff-fil (JSON) → tariff. Format (laget fra tariff-PDF, eller av Eksporter):
// { "firesafeTariff": 1, "employer": "firesafe"|"damsgard", "name": "...", "validFrom": "YYYY-MM-DD",
//   "feriepenger": 12, "fagforening": 1.8, "forsikring": 99.33, "forsikringFlags": ["lonn","skatt"],
//   "overtidsgrunnlag": 332.31,
//   "brackets": [{ "label": "7,5–15 km", "firma": 70.7, "privat": 114.6 }], "bracketFlags": [...],
//   "rates": { "km": 5, "passasjer": 1, "tilhenger": 1,
//              "bastillegg": 10, "kaffe": 25, "smuss": 5, "matpenger": 120 },
//   "rules": { "<kode-id>": ["lonn","ferie","skatt"], ... } }   (flagg: lonn/ferie/skatt/reise/org)
// Kode-id-ene står i TIMEBOK_CODES (script.js). Eldre filer godtas også: "km",
// "kmFlags", "reiseutgFlags", og "supplements"/"variables" matches på navn mot kodelista.
// Avstander matches på navn mot eksisterende id-er (så prosjekter og gamle
// registreringer fortsatt peker riktig); nye navn får nye id-er.
// Navn og gyldig fra settes av popupen (fylles inn fra fila).
function _tbTariffFromFile(obj, emp) {
    var list = getTimebokTariffs(emp);
    var norm = function (x) { return String(x || '').trim().toLowerCase().replace(/[–—]/g, '-').replace(/\s+/g, ' '); };
    var findId = function (key, label) {
        for (var i = 0; i < list.length; i++) {
            var hit = (list[i][key] || []).filter(function (x) { return norm(x.label) === norm(label); })[0];
            if (hit) return hit.id;
        }
        return null;
    };
    var codeByLabel = function (label) {
        return TIMEBOK_CODES.filter(function (c) { return norm(c.label) === norm(label); })[0] || null;
    };
    var fl = function (a) { return Array.isArray(a) ? a.filter(function (f) { return TIMEBOK_FLAGS.indexOf(f) !== -1; }) : []; };
    var num = function (v) { var n = (typeof v === 'number') ? v : parseLocaleNum(v); return (n == null || isNaN(n)) ? null : n; };
    var tf = _timebokNewTariff(String(obj.name || 'Tariff'), obj.validFrom, emp);
    tf.feriepenger = num(obj.feriepenger); tf.fagforening = num(obj.fagforening);
    tf.forsikring = num(obj.forsikring); tf.forsikringFlags = fl(obj.forsikringFlags);
    tf.overtidsgrunnlag = num(obj.overtidsgrunnlag);
    if (Array.isArray(obj.brackets)) tf.brackets = obj.brackets.map(function (b) {
        return { id: findId('brackets', b.label) || _timebokGenId('br'), label: String(b.label || ''), rate: num(b.firma), ratePrivat: num(b.privat) };
    });
    if (obj.bracketFlags) tf.bracketFlags = fl(obj.bracketFlags);
    var isCode = function (id) { return TIMEBOK_CODES.some(function (c) { return c.id === id; }); };
    // Eldre format.
    if (obj.km != null) tf.rates.km = num(obj.km);
    if (obj.kmFlags) tf.rules.km = fl(obj.kmFlags);
    if (obj.reiseutgFlags) tf.rules.reiseutg = fl(obj.reiseutgFlags);
    (obj.supplements || []).concat(obj.variables || []).forEach(function (sp) {
        var c = codeByLabel(sp.label);
        if (!c) return;
        if (c.own && sp.rate != null) tf.rates[c.id] = num(sp.rate);
        if (sp.flags) tf.rules[c.id] = fl(sp.flags);
    });
    // Nytt format.
    if (obj.rates && typeof obj.rates === 'object') Object.keys(obj.rates).forEach(function (k) { if (isCode(k)) tf.rates[k] = num(obj.rates[k]); });
    if (obj.rules && typeof obj.rules === 'object') Object.keys(obj.rules).forEach(function (k) { if (isCode(k)) tf.rules[k] = fl(obj.rules[k]); });
    return tf;
}

// ── Timebok-prosjekter = Prosjekter & lager ──
// Timebok har ingen egen prosjektliste lenger: getTimebokProjects() leser malene, og
// reiseavstanden lagres på malen (`timebokBracketId`). Nytt/rediger går via samme
// prosjektskjema som Innstillinger → Prosjekter & lager (showTemplateEditor).

// Oppdater én mal lokalt (cache + minne) og i Firestore (merge).
// Felles prosjekt: reiseavstanden er personlig (_projSaveOverride), prosjektet røres ikke.
function _timebokPatchTemplate(id, patch) {
    var list = safeParseJSON(TEMPLATE_KEY, []);
    var isShared = list.some(function (tpl) { return tpl.id === id && tpl._shared; });
    list.forEach(function (tpl) { if (tpl.id === id) Object.assign(tpl, patch); });
    safeSetItem(TEMPLATE_KEY, JSON.stringify(list));
    (window.loadedTemplates || []).forEach(function (tpl) { if (tpl.id === id) Object.assign(tpl, patch); });
    if (isShared) { if ('timebokBracketId' in patch) _projSaveOverride(id, patch.timebokBracketId); return; }
    _projStore.setOwn(id, patch, true);
}

// Frisk kopi av ALLE maler fra Firestore inn i TEMPLATE_KEY (velgeren åpnes →
// andre enheter kan ha lagt til/endret prosjekter). Sortert som getTemplates.
function _timebokFetchAllTemplates() {
    if (!(currentUser && db)) return Promise.resolve(null);
    return _projFetchAll().then(function (list) { _projCache(list); return list; });
}

// Engangs-flytting: den gamle egne Timebok-prosjektlista (settings/timebok_projects)
// flyttes inn i Prosjekter & lager. Finnes prosjektet der fra før (samme navn), får
// det bare reiseavstanden. Ellers opprettes det med SAMME id som i Timebok, så
// dagene som peker på projectId fortsatt treffer (og en ny kjøring på en annen
// enhet skriver samme dokument — aldri duplikat). Etterpå tømmes den gamle lista.
// Navnet beholdes for kallet i innloggings-flyten (script.js).
var _timebokMigrating = false;
function syncTimebokProjectsFromForms() {
    var legacy = safeParseJSON(TIMEBOK_PROJECTS_KEY, null);
    var old = legacy && Array.isArray(legacy.list) ? legacy.list : [];
    if (!old.length || _timebokMigrating) return;
    _timebokMigrating = true;
    var run = function (templates) {
        var byId = {}, byName = {};
        templates.forEach(function (tpl) {
            byId[tpl.id] = tpl;
            var nm = String(tpl.prosjektnavn || '').trim().toLowerCase();
            if (nm && !byName[nm]) byName[nm] = tpl;
        });
        var created = [];
        old.forEach(function (p) {
            var nm = String(p.name || '').trim();
            if (!nm) return;
            var tpl = byId[p.id] || byName[nm.toLowerCase()];
            if (tpl) {
                if (p.bracketId && !tpl.timebokBracketId) _timebokPatchTemplate(tpl.id, { timebokBracketId: p.bracketId });
                return;
            }
            var data = {
                id: p.id, prosjektnavn: nm, prosjektnr: '', oppdragsgiver: '', kundensRef: '',
                fakturaadresse: '', leveringsadresse: '', timebokBracketId: p.bracketId || null,
                active: true, createdAt: new Date().toISOString(), createdBy: currentUser ? currentUser.uid : 'local'
            };
            byName[nm.toLowerCase()] = data;
            created.push(data);
            if (window.loadedTemplates) window.loadedTemplates.push(Object.assign({}, data));
            enqueueUserDocSet('templates', data.id, data, 'Timebok project → template', { merge: true });
        });
        // Leses ETTER løkka — _timebokPatchTemplate over har allerede skrevet til cachen.
        var local = safeParseJSON(TEMPLATE_KEY, []).concat(created);
        local.sort(function (a, b) { return _cmpText(String(a.prosjektnavn || ''), String(b.prosjektnavn || '')); });
        safeSetItem(TEMPLATE_KEY, JSON.stringify(local));
        _syncTimebokSetting(TIMEBOK_PROJECTS_KEY, 'timebok_projects', { list: [], migratedToTemplates: true });
        if (typeof _renderSettingsTemplateListFromData === 'function' && document.getElementById('settings-template-list')) {
            _renderSettingsTemplateListFromData(local);
        }
    };
    // Innlogget: sammenlign mot ALLE maler i Firestore (ikke bare cachen), ellers
    // kunne et prosjekt utenfor cachen blitt opprettet på nytt. Feiler hentingen
    // (offline) prøves det igjen neste gang — den gamle lista står urørt til da.
    var p = (currentUser && db) ? _timebokFetchAllTemplates() : Promise.resolve(safeParseJSON(TEMPLATE_KEY, []));
    p.then(function (templates) { run(templates || []); })
        .catch(function (e) { console.error('Timebok project migration:', e); })
        .then(function () { _timebokMigrating = false; });
}

// Cache-first helpers for settings
function _getCachedOrderNrSettings() {
    var stored = localStorage.getItem(SETTINGS_KEY);
    var data = stored ? JSON.parse(stored) : null;
    if (data && !data.ranges && data.nrStart != null)
        data = { ranges: [{ start: data.nrStart, end: data.nrEnd }] };
    if (data && !data.givenAway) data.givenAway = [];
    return data;
}

function _applyOrderNrSettings(settings) {
    settingsRanges = (settings && settings.ranges) ? settings.ranges.slice() : [];
    settingsGivenAway = (settings && settings.givenAway) ? settings.givenAway.slice() : [];
    renderSettingsRanges();
    renderGivenAwayRanges();
    updateSettingsStatus();
}

function _getCachedRequiredSettings() {
    var stored = localStorage.getItem(REQUIRED_KEY);
    if (stored) {
        try {
            var data = JSON.parse(stored);
            var defaults = getDefaultRequiredSettings();
            return {
                save: Object.assign({}, defaults.save, data.save || {}),
                template: Object.assign({}, defaults.template, data.template || {}),
                service: Object.assign({}, defaults.service, data.service || {}),
                kappe: Object.assign({}, defaults.kappe, data.kappe || {}),
                sjekkliste: Object.assign({}, defaults.sjekkliste, data.sjekkliste || {})
            };
        } catch (e) {}
    }
    return getDefaultRequiredSettings();
}

// ============================================
// MATERIALER OG ENHETER INNSTILLINGER
// ============================================

let settingsMaterials = [];

function normalizeAllowedUnits(arr, defaultUnit) {
    if (!arr || arr.length === 0) return [];
    return arr.map(function(u) {
        if (typeof u === 'string') return u;
        // Convert {singular, plural} objects to just the plural string (backward compat)
        return u.plural || u.singular || '';
    }).filter(function(u) { return u; });
}

function normalizeMaterialData(data) {
    if (!data) return { materials: [], units: [] };
    let materials = data.materials || [];
    if (materials.length > 0 && typeof materials[0] === 'string') {
        materials = materials.map(name => ({ name: name, type: 'standard', defaultUnit: '', allowedUnits: [] }));
    } else {
        materials = materials.map(m => {
            // Migrate old types to new system
            var type = m.type || 'standard';
            if (type === 'pipe' || type === 'collar' || type === 'runmeter') type = 'brannpakning';
            if (type === 'dimension') type = 'kabelhylse';
            if (!m.type) {
                if (m.hasRunningMeter || m.isPipe) type = 'brannpakning';
                else if (m.needsSpec || m.hasDimensions) type = 'kabelhylse';
            }
            var allowedUnits = normalizeAllowedUnits(m.allowedUnits, m.defaultUnit || '');
            var defaultUnit = m.defaultUnit || '';
            // Cleanup: orphan defaultUnit (variant ble fjernet, defaultUnit henger igjen).
            // For standard-materialer uten varianter skal defaultUnit være tom.
            if (type === 'standard' && allowedUnits.length === 0 && defaultUnit && defaultUnit !== 'stk') {
                defaultUnit = '';
            }
            // Cleanup: defaultUnit peker på en variant som ikke finnes lenger
            // (typisk etter at varianten ble DØPT OM — sletting re-peker allerede
            // i removeMaterialUnit). Da falt ingen variant ut som standard i
            // Innstillinger, OG materialvelgeren viste det gamle navnet, fordi
            // den bruker `defaultUnit || allowedUnits[0]` og en foreldreløs
            // streng er sann. Fall tilbake til første variant, som er samme
            // regel som brukes for kappe-produkter (script.js:373).
            if (allowedUnits.length > 0 && defaultUnit
                && !allowedUnits.some(function(u) { return u.toLowerCase() === defaultUnit.toLowerCase(); })) {
                defaultUnit = allowedUnits[0];
            }
            // fixedSize: produktet kommer i FASTE størrelser (ferdige mansjetter),
            // ikke på rull. Da er løpemeter meningsløst — se getRunningMeterInfo.
            // MÅ også med i saveMaterialSettings, ellers forsvinner feltet ved lagring.
            //
            // KUN mansjett kan være fast størrelse. Brannpakning fantes en periode i
            // begge varianter, men kombinasjonen var meningsløs: meter-omregningen
            // (omkrets × lag × antall) MODELLERER at man vikler en lengde rundt et
            // rør — altså selve definisjonen på et rullprodukt. «Fast størrelse» slo
            // av nettopp den beregningen og etterlot en type med Lag-felt uten noe å
            // bruke laget til. Alle brannpakninger kommer på rull.
            // Migreringen ligger HER fordi normalizeMaterialData er eneste
            // innlastingspunkt — både Firestore og localStorage går via den, så et
            // gammelt flagg kan ikke overleve på noen enhet.
            var fixedSize = !!m.fixedSize && type === 'mansjett';
            return {
                name: m.name,
                type: type,
                defaultUnit: defaultUnit,
                allowedUnits: allowedUnits,
                fixedSize: fixedSize
            };
        });
    }
    return { materials, units: [] };
}

async function getMaterialSettings() {
    if (currentUser && db) {
        try {
            const doc = await _fsSettings('materials').get();
            if (doc.exists) {
                const normalized = normalizeMaterialData(doc.data());
                // Hold localStorage i synk med Firebase
                safeSetItem(MATERIALS_KEY, JSON.stringify(normalized));
                return normalized;
            }
        } catch (e) {
            console.error('Materials settings error:', e);
        }
    }
    const stored = localStorage.getItem(MATERIALS_KEY);
    return normalizeMaterialData(stored ? JSON.parse(stored) : null);
}

function saveMaterialSettings() {
    if (!isAdmin) return;
    // fixedSize MÅ være med her — normalizeMaterialData leser den ved innlasting,
    // men uten den her ville flagget gått tapt ved neste lagring.
    const data = { materials: settingsMaterials.map(m => ({ name: m.name, type: m.type || 'standard', defaultUnit: m.defaultUnit || '', allowedUnits: m.allowedUnits || [], fixedSize: !!m.fixedSize })), units: [] };
    // localStorage + cache first (optimistic)
    safeSetItem(MATERIALS_KEY, JSON.stringify(data));
    cachedMaterialOptions = data.materials.slice();
    cachedMaterialOptions.sort(function(a, b) { return _cmpText(a.name, b.name); });

    // Firebase in background
    if (currentUser && db) {
        _fsSettings('materials').set(data)
            .catch(function(e) { console.error('Save materials settings error:', e); });
    }
}

// Sorter materiallista: standard først (alfabetisk på navn), deretter spec-materialer
// gruppert på TYPE (brannpakning/kabelhylse/mansjett alfabetisk) og så navn innen hver
// type — så Type-kolonnen blir ryddig. Kappe-produkter legges til etterpå.
function _sortSettingsMaterials(arr) {
    arr.sort(function(a, b) {
        var aSpec = !!(a.type && a.type !== 'standard');
        var bSpec = !!(b.type && b.type !== 'standard');
        if (aSpec !== bSpec) return aSpec ? 1 : -1;        // standard før spec
        if (aSpec) {
            var tc = _cmpText((a.type || ''), b.type || '');
            if (tc !== 0) return tc;                        // spec: type alfabetisk
        }
        return _cmpText(a.name, b.name);          // så navn
    });
    return arr;
}

function renderMaterialSettingsItems() {
    const container = document.getElementById('settings-material-items');
    if (!container) return;
    // Remember which groups were expanded
    const expandedSet = new Set();
    container.querySelectorAll('.settings-material-group.expanded').forEach(el => {
        const name = el.querySelector('.settings-material-name-display');
        if (name) {
            expandedSet.add(name.textContent);
        }
    });
    var materialsHtml = settingsMaterials.map((item, idx) => {
        const unitLocked = item.type !== 'standard';
        const variants = unitLocked ? [] : (item.allowedUnits || []);
        const variantsHtml = variants.map((u, ui) => {
            const label = typeof u === 'string' ? u : (u.plural || u.singular || '');
            const isDefault = label === (item.defaultUnit || '') || (!item.defaultUnit && ui === 0);
            const starIcon = isDefault ? '<span class="settings-material-unit-star" title="Standard">★</span>' : '<span class="settings-material-unit-star empty" title="Sett som standard" onclick="event.stopPropagation();setDefaultVariant(' + idx + ',' + ui + ')">☆</span>';
            const removeBtn = `<button class="settings-material-unit-remove" onclick="event.stopPropagation();removeMaterialUnit(${idx},${ui})">${deleteIcon}</button>`;
            // Trykk på enheten = rediger (ingen blyant).
            return `<div class="settings-material-unit-item settings-row-tap" onclick="if(!event.target.closest('button,.settings-material-unit-star'))editMaterialUnit(${idx},${ui},this)">
                ${starIcon}<span class="settings-material-unit-text">${escapeHtml(label)}</span>${removeBtn}</div>`;
        }).join('');
        const addRow = unitLocked ? '' : `<div class="settings-material-unit-add" onclick="addMaterialUnit(${idx})">+ Legg til enhet</div>`;
        const isExpanded = expandedSet.has(item.name);
        const matType = item.type || 'standard';
        const bodyContent = unitLocked ? '' : `${variantsHtml}${addRow}`;
        const variantCount = (!unitLocked && item.allowedUnits) ? item.allowedUnits.length : 0;
        const countBadge = variantCount > 0 ? `<span class="settings-material-variant-count" title="${variantCount} ${variantCount === 1 ? 'enhet' : 'enheter'}">${variantCount}</span>` : '';
        return `<div class="settings-material-group${isExpanded ? ' expanded' : ''}">
            <div class="settings-material-header"${unitLocked ? '' : ' onclick="toggleMaterialExpand(this)"'}>
                <div class="settings-material-name-wrap" onclick="event.stopPropagation();if(!this.querySelector('input'))editSettingsMaterial(${idx})">
                    <span class="settings-material-name-display">${escapeHtml(item.name)}</span>
                    ${countBadge}
                </div>
                <button class="settings-material-type-btn" onclick="event.stopPropagation();openMatTypeDropdown(this,${idx})" data-value="${matType}" data-fixed="${item.fixedSize ? '1' : '0'}">${t('material_type_' + matType) + _matTypeSubLabel(matType, item.fixedSize)}</button>
                <button class="settings-delete-btn" onclick="event.stopPropagation();removeSettingsMaterial(${idx})" title="${t('btn_remove')}">${deleteIcon}</button>
                <span class="settings-material-expand"${unitLocked ? ' style="visibility:hidden"' : ''}>&rsaquo;</span>
            </div>
            <div class="settings-material-body">${bodyContent}</div>
        </div>`;
    }).join('');
    // Isolasjon og festemidler (kappe-katalogen) har egne faner (15-11-2026) — _renderKappeProductLists.
    container.innerHTML = materialsHtml;
    if (typeof _renderKappeProductLists === 'function') _renderKappeProductLists();
}


function toggleMaterialExpand(headerEl) {
    const group = headerEl.closest('.settings-material-group');
    if (group) group.classList.toggle('expanded');
}

function addMaterialUnit(idx) {
    if (!isAdmin) return;
    const mat = settingsMaterials[idx];
    if (!mat.allowedUnits) mat.allowedUnits = [];
    const container = document.getElementById('settings-material-items');
    const group = container.children[idx];
    const addRow = group.querySelector('.settings-material-unit-add');
    if (!addRow) return;

    // Check if already editing
    if (group.querySelector('.settings-material-unit-edit')) return;

    const editRow = document.createElement('div');
    editRow.className = 'settings-material-unit-edit';
    const inputV = document.createElement('input');
    inputV.type = 'text';
    inputV.placeholder = 'Enhetsnavn';
    inputV.autocapitalize = 'sentences';
    var okBtn = document.createElement('button');
    okBtn.className = 'settings-unit-save settings-unit-save-ok';
    okBtn.textContent = 'OK';
    var cancelBtn = document.createElement('button');
    cancelBtn.className = 'settings-unit-save settings-unit-cancel';
    cancelBtn.textContent = '✕';
    editRow.appendChild(inputV);
    editRow.appendChild(okBtn);
    editRow.appendChild(cancelBtn);
    addRow.before(editRow);
    addRow.style.display = 'none';
    inputV.focus();
    editRow.scrollIntoView({ behavior: 'smooth', block: 'nearest' });

    function save() {
        const variant = inputV.value.trim();
        if (variant && !mat.allowedUnits.some(u => (typeof u === 'string' ? u : (u.plural || u.singular || '')).toLowerCase() === variant.toLowerCase())) {
            mat.allowedUnits.push(variant);
            saveMaterialSettings();
        }
        renderMaterialSettingsItems();
    }
    function cancel() { renderMaterialSettingsItems(); }
    okBtn.addEventListener('click', save);
    cancelBtn.addEventListener('click', cancel);
    function handleKey(e) {
        if (e.key === 'Enter') { e.preventDefault(); save(); }
        if (e.key === 'Escape') { cancel(); }
    }
    inputV.addEventListener('keydown', handleKey);
}

function editMaterialUnit(idx, unitIdx, itemEl) {
    if (!isAdmin) return;
    const mat = settingsMaterials[idx];
    const units = mat.allowedUnits || [];
    const oldUnit = units[unitIdx] || '';
    const oldValue = typeof oldUnit === 'string' ? oldUnit : (oldUnit.plural || oldUnit.singular || '');

    const editRow = document.createElement('div');
    editRow.className = 'settings-material-unit-edit';
    const inputV = document.createElement('input');
    inputV.type = 'text';
    inputV.value = oldValue;
    inputV.placeholder = 'Enhetsnavn';
    var okBtn = document.createElement('button');
    okBtn.className = 'settings-unit-save settings-unit-save-ok';
    okBtn.textContent = 'OK';
    var cancelBtn = document.createElement('button');
    cancelBtn.className = 'settings-unit-save settings-unit-cancel';
    cancelBtn.textContent = '✕';
    editRow.appendChild(inputV);
    editRow.appendChild(okBtn);
    editRow.appendChild(cancelBtn);
    // itemEl er blyantKNAPPEN (onclick sender this) — erstatt hele RADEN, ikke
    // knappen. Uten .closest() ble stjernen og variantnavnet stående igjen ved
    // siden av input-feltet, så navnet vistes to ganger under redigering.
    // Samme mønster som editKappeProductUnit.
    (itemEl.closest('.settings-material-unit-item') || itemEl).replaceWith(editRow);
    inputV.focus();
    inputV.select();

    function save() {
        const variant = inputV.value.trim();
        if (variant && variant !== oldValue) {
            if (!mat.allowedUnits) mat.allowedUnits = units.slice();
            mat.allowedUnits[unitIdx] = variant;
            // Var den omdøpte varianten standard, skal den FORTSATT være det —
            // det er samme variant, bare nytt navn. Uten dette ble defaultUnit
            // hengende på det gamle navnet (samme opprydning som
            // removeMaterialUnit gjør ved sletting).
            if (mat.defaultUnit === oldValue) mat.defaultUnit = variant;
            saveMaterialSettings();
        }
        renderMaterialSettingsItems();
    }
    function cancel() { renderMaterialSettingsItems(); }
    okBtn.addEventListener('click', save);
    cancelBtn.addEventListener('click', cancel);
    function handleKey(e) {
        if (e.key === 'Enter') { e.preventDefault(); save(); }
        if (e.key === 'Escape') { cancel(); }
    }
    inputV.addEventListener('keydown', handleKey);
}

function setDefaultVariant(idx, unitIdx) {
    if (!isAdmin) return;
    var mat = settingsMaterials[idx];
    if (!mat.allowedUnits) return;
    var variant = mat.allowedUnits[unitIdx];
    var label = typeof variant === 'string' ? variant : (variant.plural || variant.singular || '');
    mat.defaultUnit = label;
    renderMaterialSettingsItems();
    saveMaterialSettings();
}

function removeMaterialUnit(idx, unitIdx) {
    if (!isAdmin) return;
    const mat = settingsMaterials[idx];
    if (!mat.allowedUnits) return;
    var removed = mat.allowedUnits[unitIdx];
    var removedLabel = typeof removed === 'string' ? removed : (removed && (removed.plural || removed.singular) || '');
    mat.allowedUnits.splice(unitIdx, 1);
    if (mat.defaultUnit && mat.defaultUnit === removedLabel) {
        var next = mat.allowedUnits[0];
        mat.defaultUnit = next ? (typeof next === 'string' ? next : (next.plural || next.singular || '')) : '';
    }
    renderMaterialSettingsItems();
    saveMaterialSettings();
}


// Faner på en innstillingsside (.set-tabs + .set-tab-panel[data-tab]): viser bare valgt del,
// så siden holdes kort. Generelt — gjelder alle undersider som bruker mønsteret.
// Admin › Skjemaoppsett: skjema velges i en nedtrekksliste (5 skjemaer får ikke plass som
// faner på 360 px) — samme .set-tab-panel-mekanikk som fanene.
function setAdminFormsTab(key) {
    var page = document.getElementById('settings-page-admin-forms');
    if (!page) return;
    var sel = document.getElementById('adm-forms-sel');
    if (sel && sel.value !== key) sel.value = key;
    page.querySelectorAll('.set-tab-panel').forEach(function (p) { p.hidden = p.getAttribute('data-tab') !== key; });
    if (window.applyKeyboardLayout) window.applyKeyboardLayout();
}
function setSettingsTab(btn, noScroll) {
    var page = btn.closest('.settings-page');
    if (!page) return;
    var tab = btn.getAttribute('data-tab');
    page.querySelectorAll('.set-tabs .tb-seg-btn').forEach(function (b) { b.classList.toggle('active', b === btn); });
    page.querySelectorAll('.set-tab-panel').forEach(function (p) { p.hidden = p.getAttribute('data-tab') !== tab; });
    if (!noScroll) {
        var mb = page.closest('.modal-body');
        if (mb) mb.scrollTop = 0;
    }
    // Modal-body byttes via hidden (ikke klasse) — MutationObserveren ser det ikke, så
    // tastatur-laget må få beskjed (CLAUDE.md: tab-switch i modal-views).
    if (window.applyKeyboardLayout) window.applyKeyboardLayout();
}


function updateSettingsUnitFields() {
    var type = document.getElementById('settings-new-material-type').value;
    var variantField = document.getElementById('settings-new-material-variant');
    var variantContainer = variantField ? variantField.closest('.settings-add-unit-fields') : null;
    var fixedUnit = type !== 'standard';
    if (variantContainer) {
        variantContainer.style.display = fixedUnit ? 'none' : '';
    }
    if (fixedUnit && variantField) {
        variantField.value = '';
    }
}

async function addSettingsMaterial() {
    if (!isAdmin) return;
    const input = document.getElementById('settings-new-material');
    const variantInput = document.getElementById('settings-new-material-variant');
    const val = input.value.trim();
    const typeSelect = document.getElementById('settings-new-material-type');
    const type = typeSelect.value;
    const variant = variantInput.value.trim();

    // Validate required fields
    if (!val) {
        input.classList.add('settings-input-error');
        setTimeout(() => {
            input.classList.remove('settings-input-error');
        }, 1500);
        return;
    }
    // Kappe-produkt (isolasjon/festemiddel) → kappe-katalogen, ikke materialliste.
    if (type === 'isolasjon' || type === 'festemiddel') {
        var rk = _addKappeProduct(val, type);
        if (!rk.ok) { showNotificationModal(t('kappe_settings_duplicate')); return; }
        input.value = '';
        variantInput.value = '';
        typeSelect.value = 'standard';
        updateSettingsUnitFields();
        renderMaterialSettingsItems();
        showNotificationModal(t('settings_material_added'), true);
        return;
    }
    if (settingsMaterials.some(m => m.name.toLowerCase() === val.toLowerCase())) {
        showNotificationModal(t('settings_material_exists'));
        return;
    }
    const allowedUnits = [];
    let defaultUnit = 'stk';
    if (type === 'standard' && variant) {
        allowedUnits.push(variant);
    }
    if (type !== 'standard') {
        defaultUnit = 'stk';
    }
    // fixedSize fra type-knappens data-fixed (satt av openNewMatTypePicker).
    var newFixed = (function() {
        var b = document.getElementById('settings-new-material-type-btn');
        return !!(b && b.dataset.fixed === '1' && type === 'mansjett');
    })();
    settingsMaterials.push({ name: val, type: type, defaultUnit: defaultUnit, allowedUnits: allowedUnits, fixedSize: newFixed });
    _sortSettingsMaterials(settingsMaterials);
    input.value = '';
    variantInput.value = '';
    typeSelect.value = 'standard';
    updateSettingsUnitFields();
    renderMaterialSettingsItems();
    await saveMaterialSettings();
    showNotificationModal(t('settings_material_added'), true);
}

// ── Legg til materiale direkte fra material-pickeren ─────────────────────────
// Speiler "Nytt materiale"-skjemaet i Innstillinger, men jobber mot
// cachedMaterialOptions (alltid lastet når pickeren er åpen) i stedet for
// settingsMaterials (som kun fylles når Innstillinger-siden åpnes). Begge skriver
// til SAMME kilde: localStorage 'firesafe_materials' + Firestore settings/materials.

// Delt persist for materialliste (samme dokument/format som saveMaterialSettings).
function _persistMaterialsDoc(materials) {
    var data = {
        materials: materials.map(function(m) {
            // fixedSize må med her også — dette er den TREDJE skriveren av
            // settings/materials (picker-ens «+ Nytt materiale» går hit).
            return { name: m.name, type: m.type || 'standard', defaultUnit: m.defaultUnit || '', allowedUnits: m.allowedUnits || [], fixedSize: !!m.fixedSize };
        }),
        units: []
    };
    safeSetItem(MATERIALS_KEY, JSON.stringify(data));
    if (currentUser && db) {
        _fsSettings('materials').set(data)
            .catch(function(e) { console.error('Persist materials error:', e); });
    }
}

// Legger til et kappe-produkt (type isolasjon/festemiddel) i kappe-katalogen.
// Samme logikk som addKappeProduct i kappe-innstillinger, men kallbar fra de
// felles "Nytt materiale"-skjemaene (picker + Materialer-innstillinger).
// Returnerer { ok:true } eller { ok:false, error:'dup' }.
function _addKappeProduct(name, type) {
    var val = (name || '').trim();
    var products = getKappeCatalogProducts();
    if (products.some(function(p) { return (p.name || '').toLowerCase() === val.toLowerCase(); })) {
        return { ok: false, error: 'dup' };
    }
    var units = type === 'festemiddel' ? ['stk', 'eske'] : ['meter', 'stk'];
    var np = { name: val, type: type, units: units, defaultUnit: units[0], usesDimensions: true };
    // Isolasjon: starter med standard-platen (første i registeret / global), kan endres i produktet.
    if (type !== 'festemiddel') { var dp = getKappePlateForProduct(''); np.plates = [{ length: parseFloat(dp.length), width: parseFloat(dp.width) }]; }
    products.push(np);
    _saveKappeProducts(products, getKappeDimensions());
    return { ok: true };
}

// HTML for add-skjemaet nederst i pickeren (gjenbruker settings-klasser for stil).
// Er hurtig-skjemaet i velgeren utfoldet? Må ligge utenfor funksjonen fordi
// renderPickerList() bygger lista på nytt ved hver render — ellers ville skjemaet
// klappet igjen hver gang noe endres i lista.
var _pickerAddMatOpen = false;

// Velgerens jobb er å vise REGISTRERTE materialer. «Nytt materiale» er en
// snarvei så admin slipper å gå via Innstillinger, men den skal ikke ta plass
// fra lista — derfor sammenslått til én rad som folder ut ved trykk.
// Skjemaet står nå alltid åpent (bruker 16-11-2026: «hvorfor ikke ha den ekspandert hele tiden?»
// — det ligger nederst og tar ikke plass fra lista). Kallet beholdes for eldre lenker: fokus i navnet.
function _togglePickerAddMaterial() {
    var wrap = document.getElementById('picker-add-material-wrap');
    var inp = document.getElementById('picker-new-material');
    if (inp) inp.focus();
    if (wrap && wrap.scrollIntoView) wrap.scrollIntoView({ block: 'nearest' });
}

function _pickerAddMaterialFormHtml() {
    // Alltid åpent nederst, skilt fra lista med samme grå stripe som seksjonene.
    return '<div class="picker-section-gap" aria-hidden="true"></div>' +
    '<div class="picker-add-material-wrap picker-add-mat--open" id="picker-add-material-wrap">' +
    '<div class="settings-add-material-row picker-add-material" id="picker-add-material-body">' +
        '<div class="settings-add-material-row-top">' +
            '<div class="settings-add-material-field">' +
                '<label class="settings-add-label">' + escapeHtml(t('placeholder_new_material')) + ' <span class="spec-required-star">*</span></label>' +
                '<input type="text" id="picker-new-material" autocapitalize="sentences">' +
            '</div>' +
        '</div>' +
        '<div class="settings-add-material-row-bottom">' +
            '<div class="settings-add-material-field">' +
                '<label class="settings-add-label">Type <span class="spec-required-star">*</span></label>' +
                // Samme egendefinerte type-velger som Innstillinger (knapp + skjult select).
                '<button type="button" id="picker-new-material-type-btn" class="settings-material-type-btn" data-value="standard" onclick="event.stopPropagation();openPickerMatTypePicker()">' + t('material_type_standard') + '</button>' +
                '<select id="picker-new-material-type" style="display:none" onchange="_updatePickerVariantField()">' +
                    '<option value="standard">' + t('material_type_standard') + '</option>' +
                    '<option value="mansjett">' + t('material_type_mansjett') + '</option>' +
                    '<option value="brannpakning">' + t('material_type_brannpakning') + '</option>' +
                    '<option value="kabelhylse">' + t('material_type_kabelhylse') + '</option>' +
                    '<option value="isolasjon">' + t('kappe_product_type_isolasjon') + '</option>' +
                    '<option value="festemiddel">' + t('kappe_product_type_festemiddel') + '</option>' +
                '</select>' +
            '</div>' +
            '<div class="settings-add-unit-fields" id="picker-variant-field">' +
                '<label class="settings-add-label">Enhet (valgfri)</label>' +
                // Kortere placeholder enn i Innstillinger: feltet deler linje med
                // Type, så «f.eks. patron, plate» ble klippet på 360px.
                '<input type="text" id="picker-new-material-variant" autocapitalize="sentences" placeholder="f.eks. patron">' +
            '</div>' +
        '</div>' +
        '<button type="button" class="settings-add-btn" onclick="addPickerMaterial()">' + t('btn_add') + '</button>' +
    '</div>' +
    '</div>';
}

// Åpner den egendefinerte type-velgeren (samme som Innstillinger) for picker-skjemaet.
// includeKappe=true → isolasjon/festemiddel er med. Oppdaterer skjult select + knapp-label.
function openPickerMatTypePicker() {
    var sel = document.getElementById('picker-new-material-type');
    if (!sel || typeof _renderMatTypePicker !== 'function') return;
    var btnP = document.getElementById('picker-new-material-type-btn');
    _renderMatTypePicker(sel.value, function(newValue, fixedSize) {
        sel.value = newValue;
        var btn = document.getElementById('picker-new-material-type-btn');
        if (btn) {
            var lblKey = (newValue === 'isolasjon' || newValue === 'festemiddel')
                ? ('kappe_product_type_' + newValue)
                : ('material_type_' + newValue);
            btn.dataset.value = newValue;
            btn.dataset.fixed = fixedSize ? '1' : '0';
            btn.textContent = t(lblKey) + _matTypeSubLabel(newValue, fixedSize);
        }
        if (typeof _updatePickerVariantField === 'function') _updatePickerVariantField();
    }, true, btnP && btnP.dataset.fixed === '1');
}

// Variant-feltet gjelder kun for type 'standard' (som i Innstillinger).
function _updatePickerVariantField() {
    var typeEl = document.getElementById('picker-new-material-type');
    var field = document.getElementById('picker-variant-field');
    if (!typeEl || !field) return;
    var isStandard = typeEl.value === 'standard';
    field.style.display = isStandard ? '' : 'none';
    if (!isStandard) {
        var v = document.getElementById('picker-new-material-variant');
        if (v) v.value = '';
    }
}

async function addPickerMaterial() {
    var nameEl = document.getElementById('picker-new-material');
    var typeEl = document.getElementById('picker-new-material-type');
    var variantEl = document.getElementById('picker-new-material-variant');
    if (!nameEl || !typeEl) return;
    var val = (nameEl.value || '').trim();
    var type = typeEl.value || 'standard';
    var variant = variantEl ? (variantEl.value || '').trim() : '';
    if (!val) {
        nameEl.classList.add('settings-input-error');
        setTimeout(function() { nameEl.classList.remove('settings-input-error'); }, 1500);
        return;
    }
    // Montør: eget materiale med en gang + forslag til admin (MONTØRENS MATERIALER).
    if (!isAdmin) {
        var fixedM = (function() {
            var b = document.getElementById('picker-new-material-type-btn');
            return !!(b && b.dataset.fixed === '1' && type === 'mansjett');
        })();
        var rm = _matAddMine(val, type, variant, fixedM);
        if (!rm.ok) { showNotificationModal(t(_matIsKappeType(type) ? 'kappe_settings_duplicate' : 'settings_material_exists')); return; }
        nameEl.value = '';
        if (variantEl) variantEl.value = '';
        typeEl.value = 'standard';
        _pickerAddMatOpen = false;
        _pickerUseNewMaterial(val, type, variant);
        return;
    }
    // Kappe-produkt (isolasjon/festemiddel) → kappe-katalogen, ikke materialliste.
    if (type === 'isolasjon' || type === 'festemiddel') {
        var rk = _addKappeProduct(val, type);
        if (!rk.ok) { showNotificationModal(t('kappe_settings_duplicate')); return; }
        nameEl.value = '';
        if (variantEl) variantEl.value = '';
        typeEl.value = 'standard';
        _pickerAddMatOpen = false;   // Lukk snarveien — lista skal ha fokus igjen.
        _pickerUseNewMaterial(val, type, '');
        return;
    }
    var current = Array.isArray(cachedMaterialOptions) ? cachedMaterialOptions : [];
    var existing = current.find(function(m) { return (m.name || '').toLowerCase() === val.toLowerCase(); });
    if (existing) {
        // Materialet finnes. Er en variant oppgitt → LEGG den til på det
        // eksisterende materialet (så du kan utvide et materiale du nettopp la
        // til). Uten variant, eller hvis varianten finnes → «finnes allerede».
        var variantExists = (existing.allowedUnits || []).some(function(u) {
            return (typeof u === 'string' ? u : (u.plural || u.singular || '')).toLowerCase() === variant.toLowerCase();
        });
        if (type === 'standard' && variant && !variantExists) {
            existing.allowedUnits = (existing.allowedUnits || []).concat([variant]);
            var updatedV = current.slice();
            cachedMaterialOptions = updatedV;
            if (typeof settingsMaterials !== 'undefined' && Array.isArray(settingsMaterials)) settingsMaterials = updatedV.slice();
            _persistMaterialsDoc(updatedV);
            nameEl.value = '';
            if (variantEl) variantEl.value = '';
            typeEl.value = 'standard';
            _pickerAddMatOpen = false;   // Lukk snarveien — lista skal ha fokus igjen.
            _pickerUseNewMaterial(existing.name, type, variant);
            return;
        }
        showNotificationModal(t('settings_material_exists'));
        return;
    }
    var allowedUnits = [];
    if (type === 'standard' && variant) allowedUnits.push(variant);
    // fixedSize fra type-knappens data-fixed (satt av openPickerMatTypePicker).
    var fixedSize = (function() {
        var b = document.getElementById('picker-new-material-type-btn');
        return !!(b && b.dataset.fixed === '1' && type === 'mansjett');
    })();
    var newMat = { name: val, type: type, defaultUnit: 'stk', allowedUnits: allowedUnits, fixedSize: fixedSize };
    var updated = current.slice();
    updated.push(newMat);
    updated.sort(function(a, b) { return _cmpText(a.name, b.name); });
    cachedMaterialOptions = updated;
    // Hold settings-arrayet i synk hvis det finnes (Innstillinger reloader uansett ved åpning).
    if (typeof settingsMaterials !== 'undefined' && Array.isArray(settingsMaterials)) {
        settingsMaterials = updated.slice();
    }
    _persistMaterialsDoc(updated);
    nameEl.value = '';
    if (variantEl) variantEl.value = '';
    typeEl.value = 'standard';
    _pickerAddMatOpen = false;   // Lukk snarveien — lista skal ha fokus igjen.
    _pickerUseNewMaterial(val, type, variant);
}
// Bruker 15-11-2026: «montører legger ikke til et nytt produkt med mindre de faktisk skal bruke
// det» → det nye materialet tas i bruk med en gang (gjelder admin og montør likt). Vinduet for
// størrelsen åpnes direkte: isolasjon → isolasjonskortet med en ny gruppe og tykkelsesvelgeren,
// festemiddel → festemiddelvelgeren med lengdene, mansjett/brannpakning/kabelhylse → målvinduet,
// standard → raden vises med Antall-feltet i fokus (valgt så snart antall er skrevet, som før).
// Selve åpningen ligger i velgeren (pickerUseNewFn, script.js) — den eier pickerState.
function _pickerUseNewMaterial(name, type, variant) {
    showNotificationModal(t(isAdmin ? 'settings_material_added' : 'mat_saved_pending'), true);
    if (typeof pickerUseNewFn === 'function') pickerUseNewFn(name, type, variant);
    else if (typeof pickerRenderFn === 'function') pickerRenderFn();
}


function removeSettingsMaterial(idx) {
    if (!isAdmin) return;
    const item = settingsMaterials[idx];
    showConfirmModal(t('settings_material_remove', item.name), async function() {
        settingsMaterials.splice(idx, 1);
        renderMaterialSettingsItems();
        await saveMaterialSettings();
    });
}


function editSettingsMaterial(idx) {
    if (!isAdmin) return;
    const container = document.getElementById('settings-material-items');
    const item = container.children[idx];
    const span = item.querySelector('.settings-material-name-display');
    if (!span) return;
    const oldVal = settingsMaterials[idx].name;
    const input = document.createElement('input');
    input.type = 'text';
    input.className = 'settings-list-edit-input';
    input.value = oldVal;
    input.onclick = function(e) { e.stopPropagation(); };
    span.replaceWith(input);
    input.focus();
    input.select();
    let saved = false;
    async function save() {
        if (saved) return;
        saved = true;
        const newVal = input.value.trim();
        if (!newVal || newVal === oldVal) {
            const newSpan = document.createElement('span');
            newSpan.className = 'settings-material-name-display';
            newSpan.textContent = oldVal;
            if (input.parentNode) input.replaceWith(newSpan);
            return;
        }
        if (settingsMaterials.some((m, i) => i !== idx && m.name.toLowerCase() === newVal.toLowerCase())) {
            showNotificationModal(t('settings_material_exists'));
            renderMaterialSettingsItems();
            return;
        }
        settingsMaterials[idx].name = newVal;
        _sortSettingsMaterials(settingsMaterials);
        renderMaterialSettingsItems();
        await saveMaterialSettings();
    }
    input.addEventListener('blur', save);
    input.addEventListener('keydown', function(e) {
        if (e.key === 'Enter') { e.preventDefault(); input.blur(); }
        if (e.key === 'Escape') { saved = true; renderMaterialSettingsItems(); }
    });
}

// «· rull» / «· fast»-suffiks på type-KNAPPENE. KUN mansjett har dette skillet
// (ferdigstøpte mansjetter i faste størrelser vs. rull); øvrige typer, inkludert
// brannpakning, får tom streng. Se normalizeMaterialData for hvorfor brannpakning
// ikke lenger deles.
//
// KORTFORMEN brukes her med vilje: knappen står ved siden av produktnavnet i
// Materialer-lista, og «· fast størrelse» presset navnet ut («Promasto…»).
// Kortformen gjør dessuten «fast» og «rull» like brede, så knappe-kolonnen ikke
// hopper mellom radene. Den lange formen finnes fortsatt og brukes av
// type-VELGEREN (_renderMatTypePicker, egen sub()-helper) — der er det plass, og
// hvert valg har en forklarende linje under seg.
function _matTypeSubLabel(type, fixedSize) {
    if (type !== 'mansjett') return '';
    return ' · ' + t('material_subtype_' + (fixedSize ? 'fast' : 'rull') + '_short');
}

// Felles popup-renderer for type-velger. Brukes både for eksisterende materiale
// (changeMaterialType) og for nytt materiale (oppdaterer skjult select + button-label).
// currentFixed: gjeldende fixedSize-flagg. KUN mansjett står som to oppføringer —
// «rull» (kappes, gir meter-total) og «fast størrelse» (ferdigstøpte mansjetter,
// bestilles i stk, ingen meter-total). Internt er typen den samme for begge, så
// gruppering/prikkfarge/popup/felt er uendret; det er kun fixedSize som skiller dem.
// Brannpakning hadde samme deling, men alle brannpakninger kommer på rull — se
// normalizeMaterialData. onSelect kalles med (type, fixedSize).
function _renderMatTypePicker(currentValue, onSelect, includeKappe, currentFixed) {
    const existing = document.querySelector('.mat-type-backdrop');
    if (existing) { closeMatTypeDropdown(); return; }

    const sub = (key) => ' · ' + t('material_subtype_' + key);
    const types = [
        { value: 'standard', icon: '#', desc: t('material_type_standard_desc'), lm: false },
        { value: 'mansjett', icon: '○', fixedSize: false, desc: t('material_type_mansjett_desc'), lm: true,
          label: t('material_type_mansjett') + sub('rull') },
        { value: 'mansjett', icon: '●', fixedSize: true, desc: t('material_type_mansjett_desc'), lm: false,
          label: t('material_type_mansjett') + sub('fast') },
        // Brannpakning har INGEN rull/fast-deling: alle kommer på rull, og
        // meter-omregningen (omkrets × lag) er det som definerer typen.
        // fixedSize utelates med vilje — isActive-testen under godtar da enhver
        // lagret verdi, så et gammelt «fast»-produkt vises som aktivt her mens
        // normalizeMaterialData rydder flagget bort.
        { value: 'brannpakning', icon: '◎', desc: t('material_type_brannpakning_desc'), lm: true },
        { value: 'kabelhylse', icon: '⬡', desc: t('material_type_kabelhylse_desc'), lm: false }
    ];
    // Kappe-typer tas kun med i ADD-skjemaet (ikke ved type-bytte på et eksisterende
    // materiale — de tilhører et annet datasystem og kan ikke "byttes til").
    if (includeKappe) {
        types.push({ value: 'isolasjon', icon: '▤', desc: _getKappeProductTypeDesc('isolasjon'), lm: false, label: _getKappeProductTypeLabel('isolasjon') });
        types.push({ value: 'festemiddel', icon: '⌗', desc: _getKappeProductTypeDesc('festemiddel'), lm: false, label: _getKappeProductTypeLabel('festemiddel') });
    }

    const backdrop = document.createElement('div');
    backdrop.className = 'mat-type-backdrop';
    backdrop.onclick = () => closeMatTypeDropdown();

    const dropdown = document.createElement('div');
    dropdown.className = 'mat-type-dropdown';

    types.forEach(({ value, icon, desc, lm, label, fixedSize }) => {
        // Aktiv-markering må sammenligne BEGGE dimensjonene, ellers ville både
        // «rull» og «fast» vist hake for et mansjett-produkt.
        const fx = !!fixedSize;
        const isActive = value === currentValue && (fixedSize === undefined || fx === !!currentFixed);
        const item = document.createElement('div');
        item.className = 'mat-type-dropdown-item' + (isActive ? ' active' : '');
        const lmBadge = lm ? '<span class="mat-type-lm-badge">→ løpemeter</span>' : '';
        item.innerHTML = `
            <div class="mat-type-icon">${icon}</div>
            <div class="mat-type-text">
                <div class="mat-type-label">${label || t('material_type_' + value)}${lmBadge}</div>
                <div class="mat-type-desc">${desc.split(' — ')[1] || desc}</div>
            </div>
            <div class="mat-type-check">${isActive ? '✓' : ''}</div>
        `;
        item.onclick = (e) => {
            e.stopPropagation();
            closeMatTypeDropdown();
            if (!isActive) onSelect(value, fx);
        };
        dropdown.appendChild(item);
    });

    document.body.appendChild(backdrop);
    document.body.appendChild(dropdown);
    requestAnimationFrame(() => {
        backdrop.classList.add('visible');
        dropdown.classList.add('visible');
    });
}

function openMatTypeDropdown(btn, idx) {
    _renderMatTypePicker(btn.dataset.value, function(value, fixedSize) {
        changeMaterialType(idx, value, fixedSize);
    }, false, btn.dataset.fixed === '1');
}

// Åpne picker for nytt-materiale type-knappen. Oppdaterer den skjulte select-en
// og knappens label, og kaller updateSettingsUnitFields for å vise/skjule variant-felt.
function openNewMatTypePicker() {
    var sel = document.getElementById('settings-new-material-type');
    if (!sel) return;
    var btn0 = document.getElementById('settings-new-material-type-btn');
    // includeKappe=false: isolasjon og festemidler har egne faner med egen «+» (15-11-2026).
    _renderMatTypePicker(sel.value, function(newValue, fixedSize) {
        sel.value = newValue;
        var btn = document.getElementById('settings-new-material-type-btn');
        if (btn) {
            var lblKey = (newValue === 'isolasjon' || newValue === 'festemiddel')
                ? ('kappe_product_type_' + newValue)
                : ('material_type_' + newValue);
            btn.dataset.value = newValue;
            btn.dataset.fixed = fixedSize ? '1' : '0';
            btn.textContent = t(lblKey) + _matTypeSubLabel(newValue, fixedSize);
            // data-i18n fjernes når suffikset er med: applyTranslations ville ellers
            // overskrevet hele teksten med bare type-navnet ved språk-bytte.
            if (_matTypeSubLabel(newValue, fixedSize)) btn.removeAttribute('data-i18n');
            else btn.setAttribute('data-i18n', lblKey);
        }
        if (typeof updateSettingsUnitFields === 'function') updateSettingsUnitFields();
    }, false, btn0 && btn0.dataset.fixed === '1');
}

function closeMatTypeDropdown() {
    // ALLE (ikke bare den første): en liste som aldri ble fjernet, ville ligget igjen som et
    // mørkt lag over appen.
    const backdrops = document.querySelectorAll('.mat-type-backdrop');
    const dropdowns = document.querySelectorAll('.mat-type-dropdown');
    if (!backdrops.length) return;
    backdrops.forEach(b => b.classList.remove('visible'));
    dropdowns.forEach(d => d.classList.remove('visible'));
    setTimeout(() => {
        backdrops.forEach(b => b.remove());
        dropdowns.forEach(d => d.remove());
    }, 150);
}

// ── Mobil-nedtrekksliste for <select> (hele appen) ──
// På mobil/nettbrett (ingen html.device-pc) åpnes ALLE <select> som appens egen
// liste-popup (samme utseende som Type-velgeren over) i stedet for nettleserens
// PC-liste. Native <select> beholdes som datakilde: valg setter .value og sender
// 'change', så eksisterende onchange-kode virker uendret. PC beholder native liste.
// Unntak: <select data-native> (ingen i dag).
function _openSelectSheet(sel) {
    if (!sel || sel.disabled || document.querySelector('.mat-type-backdrop')) return;
    // Som native: et åpent tastatur lukkes når lista åpnes.
    var ae = document.activeElement;
    if (ae && ae !== sel && ae.blur && /^(INPUT|TEXTAREA)$/.test(ae.tagName)) ae.blur();
    // Tittel = feltets etikett: omsluttende <label> sin første span, ellers nærmeste
    // forrige søsken som er en etikett (label / *-label-klasse).
    var lbl = sel.closest('label'), titleEl = lbl ? lbl.querySelector('span') : null;
    for (var p = sel.previousElementSibling; !titleEl && p; p = p.previousElementSibling) {
        if (p.tagName === 'LABEL' || /label/.test(p.className)) titleEl = p;
    }
    var title = titleEl ? titleEl.textContent.trim() : (sel.getAttribute('aria-label') || '');
    var backdrop = document.createElement('div');
    backdrop.className = 'mat-type-backdrop';
    backdrop.onclick = function () { closeMatTypeDropdown(); };
    var dd = document.createElement('div');
    dd.className = 'mat-type-dropdown select-sheet';
    if (title) {
        var th = document.createElement('div');
        th.className = 'mat-type-dropdown-title';
        th.textContent = title;
        dd.appendChild(th);
    }
    var list = document.createElement('div');
    list.className = 'select-sheet-list';
    Array.prototype.forEach.call(sel.children, function (node) {
        var opts = node.tagName === 'OPTGROUP' ? node.children : [node];
        if (node.tagName === 'OPTGROUP') {
            var g = document.createElement('div');
            g.className = 'mat-type-dropdown-title';
            g.textContent = node.label;
            list.appendChild(g);
        }
        Array.prototype.forEach.call(opts, function (o) {
            if (o.tagName !== 'OPTION' || o.hidden) return;
            var active = o.selected;
            var item = document.createElement('div');
            item.className = 'mat-type-dropdown-item' + (active ? ' active' : '') + (o.disabled ? ' disabled' : '');
            item.innerHTML = '<div class="mat-type-text"><div class="mat-type-label"></div></div><div class="mat-type-check">' + (active ? '✓' : '') + '</div>';
            item.querySelector('.mat-type-label').textContent = o.textContent;
            // data-desc på <option> = grå undertekst i lista (f.eks. tariffens gyldig-fra).
            if (o.getAttribute('data-desc')) {
                var desc = document.createElement('div');
                desc.className = 'mat-type-desc';
                desc.textContent = o.getAttribute('data-desc');
                item.querySelector('.mat-type-text').appendChild(desc);
            }
            item.onclick = function (e) {
                e.stopPropagation();
                if (o.disabled) return;
                closeMatTypeDropdown();
                if (active) return;
                sel.value = o.value;
                sel.dispatchEvent(new Event('input', { bubbles: true }));
                sel.dispatchEvent(new Event('change', { bubbles: true }));
            };
            list.appendChild(item);
        });
    });
    dd.appendChild(list);
    document.body.appendChild(backdrop);
    document.body.appendChild(dd);
    var act = list.querySelector('.active');
    if (act) list.scrollTop = Math.max(0, act.offsetTop - list.clientHeight / 2 + act.offsetHeight / 2);
    requestAnimationFrame(function () {
        backdrop.classList.add('visible');
        dd.classList.add('visible');
    });
}
(function () {
    // Nettleserens liste kan ikke stoppes pålitelig i en touch-hendelse (Chrome Android
    // åpner den uansett). Derfor er <select> gjort utrykkbar på mobil/nettbrett i CSS
    // (html:not(.device-pc) select { pointer-events: none }) — trykket lander på
    // forelderen, og vi finner selecten under fingeren via posisjon.
    function useSheet(sel) {
        return sel && !sel.multiple && !sel.disabled && !sel.hasAttribute('data-native') && !document.documentElement.classList.contains('device-pc');
    }
    document.addEventListener('click', function (e) {
        if (document.documentElement.classList.contains('device-pc') || !e.target || !e.target.querySelectorAll) return;
        var x = e.clientX, y = e.clientY;
        var cands = e.target.tagName === 'SELECT' ? [e.target] : e.target.querySelectorAll('select');
        for (var i = 0; i < cands.length; i++) {
            var sel = cands[i];
            if (!useSheet(sel)) continue;
            var r = sel.getBoundingClientRect();
            if (r.width && x >= r.left && x <= r.right && y >= r.top && y <= r.bottom) {
                e.preventDefault();   // label-klikk skal ikke fokusere selecten
                _openSelectSheet(sel);
                return;
            }
        }
    }, true);
    // Tastatur (Enter/Space/Alt+pil) på fokusert select.
    document.addEventListener('keydown', function (e) {
        var sel = e.target && e.target.tagName === 'SELECT' ? e.target : null;
        if (!useSheet(sel)) return;
        if (e.key === 'Enter' || e.key === ' ' || (e.altKey && (e.key === 'ArrowDown' || e.key === 'ArrowUp'))) {
            e.preventDefault();
            _openSelectSheet(sel);
        }
    }, true);
})();

async function changeMaterialType(idx, type, fixedSize) {
    if (!isAdmin) return;
    settingsMaterials[idx].type = type;
    // fixedSize gjelder bare MANSJETT — nullstilles for øvrige typer så et gammelt
    // flagg ikke henger igjen og påvirker en type det ikke gjelder for. Brannpakning
    // sto her tidligere; se normalizeMaterialData for hvorfor den er ute.
    settingsMaterials[idx].fixedSize = (type === 'mansjett') ? !!fixedSize : false;
    if (type !== 'standard') {
        settingsMaterials[idx].defaultUnit = 'stk';
        settingsMaterials[idx].allowedUnits = [{ singular: 'stk', plural: 'stk' }];
    }
    renderMaterialSettingsItems();
    await saveMaterialSettings();
}



