async function getPlanSettings() {
    if (currentUser && db) {
        try {
            var doc = await _fsSettings('plans').get();
            if (doc.exists) {
                var plans = doc.data().plans || [];
                // Hold localStorage i synk med Firebase
                safeSetItem(PLANS_KEY, JSON.stringify(plans));
                return plans;
            }
        } catch (e) { console.error('Plan settings error:', e); }
    }
    var stored = localStorage.getItem(PLANS_KEY);
    return stored ? JSON.parse(stored) : [];
}

// ÉN persisterings-vei for etasjer: localStorage + Firestore + begge cachene.
// Skilt ut fordi etasjer nå kan legges til fra TO steder (Innstillinger og
// etasje-velgeren i Arbeidstid), og de må skrive likt.
function _persistPlanList(list) {
    var sorted = sortPlans((list || []).slice());
    settingsPlans = sorted.slice();
    cachedPlanOptions = sorted.slice();
    safeSetItem(PLANS_KEY, JSON.stringify(sorted));
    if (currentUser && db) {
        _fsSettings('plans').set({ plans: sorted })
            .catch(function(e) { console.error('Save plan settings error:', e); });
    }
}

function savePlanSettings() {
    if (!isAdmin) return;
    _persistPlanList(settingsPlans);
}

// Legg til etasje direkte fra etasje-velgeren, uten å gå via Innstillinger.
//
// Bygger på cachedPlanOptions, IKKE settingsPlans. Det er kritisk: settingsPlans
// fylles bare når Innstillinger-siden åpnes, så for en bruker som går rett til
// skjemaet er den tom — og en lagring basert på den ville skrevet en liste med
// kun den nye etasjen til Firestore og slettet alle de andre.
// Etasje som ikke finnes i lista. Admin: legges i den faste lista (felles). Montør: hukes av for
// DETTE skjemaet, men legges ikke i lista — som egne tykkelser (valglister eies av admin, se
// CLAUDE.md «Montørforslag»). Begge ser feltet og blir aldri stående fast.
function addPlanFromPicker() {
    var input = document.getElementById('plan-popup-new');
    if (!input) return;
    var val = String(input.value || '').trim().toUpperCase();
    if (!val) {
        input.classList.add('settings-input-error');
        setTimeout(function() { input.classList.remove('settings-input-error'); }, 1500);
        return;
    }
    var base = (cachedPlanOptions || []).slice();
    var exists = base.some(function(p) { return String(p).toUpperCase() === val; });
    if (!exists && isAdmin) {
        base.push(val);
        _persistPlanList(base);
    }
    input.value = '';
    // Den nye etasjen hukes av med én gang — man legger den jo til fordi den
    // skal brukes nå. keepState bevarer det brukeren alt hadde valgt.
    _planPickerState[val] = true;
    if (typeof _renderPlanPickerList === 'function' && _planPickerDisplay) {
        _renderPlanPickerList(_planPickerDisplay, true);
    }
    if (typeof renderPlanSettingsItems === 'function' && document.getElementById('settings-plan-items')) {
        renderPlanSettingsItems();
    }
}
window.addPlanFromPicker = addPlanFromPicker;

function renderPlanSettingsItems() {
    var container = document.getElementById('settings-plan-items');
    if (settingsPlans.length === 0) {
        container.innerHTML = '';
        return;
    }
    container.innerHTML = settingsPlans.map(function(name, idx) {
        return _kappeSettingsItemHtml(name, idx, 'editSettingsPlan', 'removeSettingsPlan');
    }).join('');
}

function sortPlans(plans) {
    return plans.sort(function(a, b) {
        var aUp = a.toUpperCase(), bUp = b.toUpperCase();
        var aIsU = aUp.match(/^U(\d*)$/), bIsU = bUp.match(/^U(\d*)$/);
        var aIsNum = aUp.match(/^\d+$/), bIsNum = bUp.match(/^\d+$/);
        // U-etasjer først, synkende (U3 før U1, bare "U" sist blant U-ene)
        if (aIsU && bIsU) {
            var aNum = aIsU[1] === '' ? 0 : parseInt(aIsU[1]);
            var bNum = bIsU[1] === '' ? 0 : parseInt(bIsU[1]);
            return bNum - aNum;
        }
        if (aIsU) return -1;
        if (bIsU) return 1;
        // Tall i stigende rekkefølge
        if (aIsNum && bIsNum) return parseInt(aIsNum[0]) - parseInt(bIsNum[0]);
        if (aIsNum) return -1;
        if (bIsNum) return 1;
        // Resten alfabetisk
        return _cmpText(aUp, bUp);
    });
}

function addSettingsPlan() {
    if (!isAdmin) return;
    var input = document.getElementById('settings-new-plan');
    var val = input.value.trim().toUpperCase();
    if (!val) return;
    if (settingsPlans.some(function(p) { return p.toUpperCase() === val; })) {
        showNotificationModal(t('settings_plan_exists'));
        return;
    }
    settingsPlans.push(val);
    sortPlans(settingsPlans);
    input.value = '';
    renderPlanSettingsItems();
    savePlanSettings();
    // Scroll to the newly added item
    var idx = settingsPlans.indexOf(val);
    var container = document.getElementById('settings-plan-items');
    if (container.children[idx]) {
        container.children[idx].scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
}

function editSettingsPlan(idx) {
    if (!isAdmin) return;
    var cur = settingsPlans[idx];
    if (cur === undefined) return;
    var container = document.getElementById('settings-plan-items');
    var item = container ? container.children[idx] : null;
    var span = item ? item.querySelector('.settings-list-item-name') : null;
    if (!span) return;
    var input = document.createElement('input');
    input.type = 'text';
    input.className = 'settings-list-edit-input';
    input.value = cur;
    input.autocapitalize = 'characters';
    input.onclick = function(e) { e.stopPropagation(); };
    span.replaceWith(input);
    input.focus();
    input.select();
    var saved = false;

    function save() {
        if (saved) return;
        saved = true;
        var newName = (input.value || '').trim().toUpperCase();
        if (!newName || newName === cur) {
            renderPlanSettingsItems();
            return;
        }
        if (settingsPlans.some(function(p, i) { return i !== idx && p.toUpperCase() === newName; })) {
            showNotificationModal(t('settings_plan_exists'));
            renderPlanSettingsItems();
            return;
        }
        settingsPlans[idx] = newName;
        sortPlans(settingsPlans);
        renderPlanSettingsItems();
        savePlanSettings();
    }
    input.addEventListener('blur', save);
    input.addEventListener('keydown', function(e) {
        if (e.key === 'Enter') { e.preventDefault(); input.blur(); }
        if (e.key === 'Escape') { saved = true; renderPlanSettingsItems(); }
    });
}

function removeSettingsPlan(idx) {
    if (!isAdmin) return;
    var name = settingsPlans[idx];
    showConfirmModal(t('settings_plan_remove', name), function() {
        settingsPlans.splice(idx, 1);
        renderPlanSettingsItems();
        savePlanSettings();
    });
}

async function loadPlanOptions() {
    // Show cached immediately
    var stored = localStorage.getItem(PLANS_KEY);
    cachedPlanOptions = stored ? sortPlans(JSON.parse(stored)) : [];
    // Refresh from Firebase
    var plans = await getPlanSettings();
    cachedPlanOptions = sortPlans(plans);
    safeSetItem(PLANS_KEY, JSON.stringify(cachedPlanOptions));
}

