var _editingTemplateId = null;
// Ble prosjekt-editoren åpnet fra «Velg prosjekt» (ikke fra Innstillinger)?
// Styrer om velgeren skal tilbake ved avbryt, og om det nye prosjektet skal
// tas i bruk med én gang ved lagring.
var _templateEditorFromPicker = false;

function _findSettingsTemplateItem(templateId) {
    var items = document.querySelectorAll('.settings-template-item[data-id]');
    for (var i = 0; i < items.length; i++) {
        if (items[i].getAttribute('data-id') === String(templateId)) return items[i];
    }
    return null;
}

function _renderSettingsTemplateListFromData(templates) {
    var listEl = document.getElementById('settings-template-list');
    if (!listEl) return;
    // Felles liste virker: admins egne (ikke felles ennå) står under «Til godkjenning».
    if (_projSharedOk && templates) templates = templates.filter(function (p) { return !p._own; });

    if (!templates || templates.length === 0) {
        listEl.innerHTML = '';
        return;
    }

    listEl.innerHTML = templates.map(function(tpl) {
        var isActive = tpl.active !== false;
        var name = escapeHtml(tpl.prosjektnavn) || t('no_name');
        var detail = [tpl.oppdragsgiver, tpl.prosjektnr].filter(function(x) { return x; }).map(escapeHtml).join(' \u2022 ');
        var idAttr = escapeHtml(tpl.id);
        var idJs = escapeJsStringAttr(tpl.id);

        var duplicateBtn = isActive
            ? '<button class="settings-template-duplicate-btn" onclick="event.stopPropagation(); duplicateTemplateFromSettings(\'' + idJs + '\')" title="' + t('duplicate_btn') + '">'
            : '<button class="settings-template-duplicate-btn disabled" onclick="event.stopPropagation()" title="' + t('duplicate_btn') + '">';
        var delBtn = isActive
            ? '<button class="settings-template-delete-btn" onclick="event.stopPropagation(); deleteTemplateFromSettings(\'' + idJs + '\')" title="' + t('delete_btn') + '">'
            : '<button class="settings-template-delete-btn disabled" onclick="event.stopPropagation()" title="' + t('delete_btn') + '">';

        return '<div class="settings-template-item' + (isActive ? '' : ' inactive') + '" data-id="' + idAttr + '" onclick="showTemplateEditor(\'' + idJs + '\')">' +
            '<div class="settings-template-item-info">' +
                '<div class="settings-template-item-row1">' + name + '</div>' +
                (detail ? '<div class="settings-template-item-row2">' + detail + '</div>' : '') +
            '</div>' +
            '<div class="settings-template-item-actions">' +
                duplicateBtn + duplicateIcon + '</button>' +
                delBtn +
                    deleteIcon +
                '</button>' +
            '</div>' +
        '</div>';
    }).join('');
}

async function renderSettingsTemplateList() {
    var templates = [];
    if (currentUser && db) {
        try {
            templates = await _projFetchAll();
            _projCache(templates);
        } catch (e) {
            console.error('Load templates for settings:', e);
            templates = safeParseJSON(TEMPLATE_KEY, []);
        }
    } else {
        templates = safeParseJSON(TEMPLATE_KEY, []);
    }
    _renderSettingsTemplateListFromData(templates);
    _projRenderPending();
    _projLoadPending();
}

var LAGER_FIELDS = ['veiadresse', 'postnr', 'poststed'];
var _lagerInlineInited = false;

function _loadLagerInline() {
    var lager = (typeof getLager === 'function') ? getLager() : null;
    LAGER_FIELDS.forEach(function(f) {
        var el = document.getElementById('lager-inline-' + f);
        if (el) el.value = (lager && lager[f]) || '';
    });
    if (_lagerInlineInited) return;
    _lagerInlineInited = true;
    LAGER_FIELDS.forEach(function(f) {
        var el = document.getElementById('lager-inline-' + f);
        if (!el) return;
        // Dirty-check: lagre kun hvis verdien faktisk endret seg mellom
        // focus og blur. Uten dette skrives det til Firebase ved hver
        // tilfeldig tap-inn-tap-ut, og senere kunne en suksess-toast feilaktig
        // dukke opp uten endring. Site-wide mønster (se mininfo nedenfor).
        var _initialValue = '';
        el.addEventListener('focus', function() { _initialValue = el.value; });
        el.addEventListener('blur', function() {
            if (el.value === _initialValue) return;
            _saveLagerInline();
        });
    });
}

function _saveLagerInline() {
    var data = {};
    LAGER_FIELDS.forEach(function(f) {
        var el = document.getElementById('lager-inline-' + f);
        data[f] = el ? el.value.trim() : '';
    });
    _saveLagerLocalOnly(data);
    enqueueUserDocSet('settings', 'lager', data, 'Save lager');
}

function openProsjektLeveringsadressePicker() {
    var listEl = document.getElementById('prosjekt-lev-picker-list');
    var templates = (window.loadedTemplates || []).filter(function(t) { return t.active !== false && t.leveringsadresse; }).slice();
    if (!templates.length) {
        var local = (safeParseJSON(TEMPLATE_KEY, []) || []).filter(function(t) { return t.active !== false && t.leveringsadresse; });
        templates = local;
    }
    if (!templates.length) {
        listEl.innerHTML = '<div style="padding:16px;color:#999;text-align:center">' + t('no_prosjekt_leveringsadresser') + '</div>';
    } else {
        templates.sort(function(a, b) { return _cmpText((a.prosjektnavn || ''), b.prosjektnavn || ''); });
        listEl.innerHTML = templates.map(function(item) {
            var id = escapeHtml(item.id);
            var name = escapeHtml(item.prosjektnavn || t('no_name'));
            var addr = escapeHtml(item.leveringsadresse);
            return '<div class="plan-popup-row" onclick="_selectProsjektLeveringsadresse(\'' + id + '\')" style="flex-direction:column;align-items:stretch">' +
                '<span class="plan-popup-name">' + name + '</span>' +
                '<span style="font-size:12px;color:#666;margin-top:2px">' + addr + '</span>' +
            '</div>';
        }).join('');
    }
    document.getElementById('prosjekt-lev-picker-popup').classList.add('active');
}

function closeProsjektLeveringsadressePicker() {
    document.getElementById('prosjekt-lev-picker-popup').classList.remove('active');
}

function _selectProsjektLeveringsadresse(id) {
    closeProsjektLeveringsadressePicker();
    _findTemplateById(id).then(function(tpl) {
        if (!tpl || !tpl.leveringsadresse || typeof parseFakturaadresse !== 'function') return;
        var parsed = parseFakturaadresse(tpl.leveringsadresse);
        var v = document.getElementById('kappe-veiadresse');
        var p = document.getElementById('kappe-postnr');
        var s = document.getElementById('kappe-poststed');
        if (v) v.value = parsed.gate || '';
        if (p) p.value = parsed.postnr || '';
        if (s) s.value = parsed.poststed || '';
        var card = document.getElementById('kappe-delivery-card');
        if (card) {
            var wrap = card.querySelector('.mobile-order-body-wrap');
            if (wrap && !wrap.classList.contains('expanded')) {
                var header = card.querySelector('.mobile-order-header');
                if (header) toggleKappeDeliverySection(header);
            }
        }
    });
}

function useLagerInKappe() {
    var lager = (typeof getLager === 'function') ? getLager() : null;
    if (!lager || !lager.veiadresse) {
        showNotificationModal(t('lager_not_set'));
        return;
    }
    LAGER_FIELDS.forEach(function(f) {
        var el = document.getElementById('kappe-' + f);
        if (el) el.value = lager[f] || '';
    });
    var card = document.getElementById('kappe-delivery-card');
    if (card) {
        var wrap = card.querySelector('.mobile-order-body-wrap');
        if (wrap && !wrap.classList.contains('expanded')) {
            var header = card.querySelector('.mobile-order-header');
            if (header) toggleKappeDeliverySection(header);
        }
    }
}

// review = { sugg } / { own } når admin vurderer et forslag (openProjectReview).
function _tplFill(tpl) {
    document.getElementById('tpl-edit-prosjektnavn').value = tpl.prosjektnavn || '';
    document.getElementById('tpl-edit-prosjektnr').value = tpl.prosjektnr || '';
    document.getElementById('tpl-edit-oppdragsgiver').value = tpl.oppdragsgiver || '';
    document.getElementById('tpl-edit-kundensRef').value = tpl.kundensRef || '';
    document.getElementById('tpl-edit-fakturaadresse').value = tpl.fakturaadresse || '';
    updateFakturaadresseDisplay('tpl-fakturaadresse-display-text', tpl.fakturaadresse || '');
    document.getElementById('tpl-edit-leveringsadresse').value = tpl.leveringsadresse || '';
    updateFakturaadresseDisplay('tpl-leveringsadresse-display-text', tpl.leveringsadresse || '');
    document.getElementById('tpl-edit-timebok-dist').innerHTML = _timebokDistOptionsHtml(tpl.timebokBracketId || null);
}
// Forklaring øverst i skjemaet (felles / eget / til godkjenning). Tom = skjult.
function _tplSetNote(text) {
    var n = document.getElementById('tpl-note');
    if (!n) return;
    n.textContent = text || '';
    n.hidden = !text;
}
// Felles prosjekt åpnet av montør: alt låst unntatt reiseavstanden (den er personlig).
function _tplSetLocked(locked) {
    var body = document.querySelector('#template-editor-overlay .template-editor-body');
    if (body) body.classList.toggle('tpl-locked', !!locked);
    ['tpl-edit-prosjektnavn', 'tpl-edit-prosjektnr', 'tpl-edit-oppdragsgiver', 'tpl-edit-kundensRef'].forEach(function (id) {
        document.getElementById(id).disabled = !!locked;
    });
}
var _tplSimilarBound = false;
function showTemplateEditor(templateId, review) {
    _editingTemplateId = templateId || null;
    _projReview = review || null;
    var overlay = document.getElementById('template-editor-overlay');
    var titleEl = document.getElementById('template-editor-title');
    var saveBtn = overlay.querySelector('.template-editor-save-btn');
    var rejectBtn = document.getElementById('tpl-reject-btn');

    // Clear fields
    _tplFill({});
    _tplSetLocked(false);
    _tplSetNote('');
    if (saveBtn) saveBtn.textContent = t('toolbar_save');
    if (rejectBtn) rejectBtn.style.display = 'none';
    var simBox = document.getElementById('tpl-similar');
    if (simBox) { simBox.hidden = true; simBox.innerHTML = ''; }
    if (!_tplSimilarBound) {
        _tplSimilarBound = true;
        ['tpl-edit-prosjektnavn', 'tpl-edit-prosjektnr'].forEach(function (id) {
            document.getElementById(id).addEventListener('input', function () { if (!_editingTemplateId) _projRenderSimilar(); });
        });
    }

    // Mark required fields
    var reqSettings = cachedRequiredSettings || getDefaultRequiredSettings();
    var templateReqs = reqSettings.template || {};
    var tplFieldMap = {
        prosjektnavn: 'tpl-edit-prosjektnavn',
        prosjektnr: 'tpl-edit-prosjektnr',
        oppdragsgiver: 'tpl-edit-oppdragsgiver',
        kundensRef: 'tpl-edit-kundensRef',
        fakturaadresse: 'tpl-edit-fakturaadresse',
        leveringsadresse: 'tpl-edit-leveringsadresse'
    };
    for (var key in tplFieldMap) {
        var label = document.getElementById(tplFieldMap[key]).closest('label');
        if (templateReqs[key]) label.classList.add('field-required');
        else label.classList.remove('field-required');
    }

    // Vis/skjul deaktiver-knapp (kun admin, i redigeringsmodus)
    var deactBtn = document.getElementById('tpl-deactivate-btn');
    if (deactBtn) deactBtn.style.display = templateId ? '' : 'none';
    var sharedOn = _projSharedOk === true;

    if (review) {
        // Admin vurderer et forslag / sitt eget prosjekt: kan rette alt før godkjenning.
        var src = review.sugg || review.own;
        titleEl.textContent = t(review.sugg ? 'proj_review_title' : 'proj_review_own_title');
        _tplFill(src);
        if (review.sugg) {
            // Montørens reiseavstand er hans egen — admin velger ikke for ham.
            document.getElementById('tpl-edit-timebok-dist').innerHTML = _timebokDistOptionsHtml(null);
            _tplSetNote(t('proj_review_note', review.sugg.createdByName || '?', _projDateStr(review.sugg.suggestedAt)));
        } else {
            _tplSetNote(t('proj_review_own_note', _firmaName(_firma())));
        }
        if (saveBtn) saveBtn.textContent = t(review.sugg ? 'proj_approve_btn' : 'proj_share_btn');
        if (rejectBtn) rejectBtn.style.display = review.sugg ? '' : 'none';
        if (deactBtn) deactBtn.style.display = 'none';
        _projRenderSimilar();
    } else if (templateId) {
        titleEl.textContent = t('settings_edit_template');
        // Find template and fill fields + set deactivate button text
        _findTemplateById(templateId).then(function(tpl) {
            if (tpl) {
                _tplFill(tpl);
                if (sharedOn && tpl._shared && !isAdmin) {
                    _tplSetLocked(true);
                    _tplSetNote(t('proj_shared_locked_note'));
                } else if (sharedOn && tpl._pending) {
                    _tplSetNote(t('proj_pending_note'));
                } else if (sharedOn && tpl._own && !isAdmin) {
                    _tplSetNote(t('proj_own_note'));
                }
                if (deactBtn) {
                    deactBtn.textContent = tpl.active === false ? t('settings_template_activate') : t('settings_template_deactivate');
                    if (sharedOn && tpl._shared && !isAdmin) deactBtn.style.display = 'none';
                }
            }
        });
    } else {
        titleEl.textContent = t('settings_new_template');
        if (sharedOn && !isAdmin) _tplSetNote(t('proj_new_montor_note'));
    }

    overlay.classList.add('active');
}

function closeTemplateEditor() {
    _editingTemplateId = null;
    _projReview = null;
    document.getElementById('template-editor-overlay').classList.remove('active');
    // Avbrutt fra «Velg prosjekt» → vis velgeren igjen. Uten dette ville avbryt
    // etterlate brukeren i skjemaet, uten lista de faktisk sto i.
    if (_templateEditorFromPicker) {
        _templateEditorFromPicker = false;
        _setTemplatePickerHidden(false);
    }
    // Avbrutt fra Timebok-velgeren → tilbake til den (blokk-målet er beholdt).
    if (_templateEditorFromTimebok) {
        _templateEditorFromTimebok = false;
        if (_timebokPickerTarget) _timebokShowProjectPicker();
    }
}

async function duplicateTemplateFromSettings(templateId) {
    var tpl = await _findTemplateById(templateId);
    if (!tpl) return;
    showTemplateEditor();
    _tplFill(tpl);
}

async function toggleActiveFromEditor() {
    if (!_editingTemplateId) return;
    await toggleTemplateActive(_editingTemplateId);
    closeTemplateEditor();
    await renderSettingsTemplateList();
}

async function _findTemplateById(id) {
    // Check in-memory first (instant)
    var inMem = (window.loadedTemplates || []).find(function(t) { return t.id === id; });
    if (inMem) return inMem;
    // Then localStorage
    var templates = safeParseJSON(TEMPLATE_KEY, []);
    var local = templates.find(function(t) { return t.id === id; });
    if (local) return local;
    // Last resort: Firebase
    if (currentUser && db) {
        try {
            if (_projSharedOk && !_admDev()) {
                var sdoc = await _firmaRef().collection('projects').doc(id).get();
                if (sdoc.exists) return Object.assign({ id: sdoc.id }, sdoc.data(), { _shared: true });
            }
            var doc = await db.collection('users').doc(currentUser.uid).collection('templates').doc(id).get();
            if (doc.exists) return Object.assign({ id: doc.id }, doc.data());
        } catch (e) {
            console.error('Find template error:', e);
        }
    }
    return null;
}

// ============================================================================
// PROSJEKT-RETTELSE → PROPAGERING (gjelder HELE appen)
// ============================================================================
// Et prosjekt fra Innstillinger → Prosjekter & lager KOPIERES inn i skjemaene som
// løse verdier (se _applyTemplateToForm) — skjemaet har ingen referanse tilbake til
// prosjektet. Retter man derfor en skrivefeil i prosjektet («Framo fusa» →
// «Framo Fusa»), ville alle allerede lagrede skjemaer beholdt feilen.
//
// Rettelsen skrives ut til ALLE steder som har en kopi:
//   ordreseddel  → forms / archive               (prosjektnr, navn, oppdragsgiver, ref, faktura)
//   servicebil   → serviceforms / serviceArchive  (prosjekt ligger pr. rad i entries[])
//   kappeskjema  → kappeforms / kappeArchive      (prosjektnr + navn)
//   timebok      → prosjektlista + dag-docs (projects[].name)
//   åpent skjema → input-feltene som står på skjermen nå
// Bil-historikk (uttak) og Timer-oversikt har INGEN egen lagring — de leser fra
// skjemaene over og følger derfor automatisk.
//
// TO REGLER kjøres i samme gjennomgang (se _buildProjectCorrectionRules):
//   1. Rettelsen: gammel verdi → ny verdi.
//   2. Normalisering: samme prosjekt (prosjektnr + navn likt uansett store/små
//      bokstaver) får prosjektets nøyaktige skrivemåte. Denne reparerer prosjekter
//      som ble rettet FØR denne mekanismen fantes — det holder å lagre prosjektet
//      på nytt. Den er idempotent, så den skriver ingenting når alt allerede stemmer.
//
// To bevisste begrensninger (dokumentert fordi de er unntak, jf. CLAUDE.md):
//  a. Vi treffer kun snapshots som faktisk hadde de gamle verdiene
//     (_projectSnapshotMatches) — et annet delprosjekt som deler prosjektnr, men har
//     eget navn, røres ikke.
//  b. Vi skriver kun i felt som allerede har innhold. Dette er en RETTELSE, ikke en
//     utfylling: et felt brukeren lot stå tomt skal forbli tomt.

// Ordreseddel kopierer hele prosjektkortet; servicebil/kappeskjema kun identiteten
// (se _applyTemplateToForm — samme kilde, så listene her må følge den).
var _PROJECT_SNAPSHOT_FIELDS = ['prosjektnr', 'prosjektnavn', 'oppdragsgiver', 'kundensRef', 'fakturaadresse'];
var _PROJECT_IDENTITY_FIELDS = ['prosjektnr', 'prosjektnavn'];

// localStorage-cache + Firestore-samling for hvert sted et prosjekt-snapshot bor.
// `inEntries`: prosjektet ligger pr. rad i entries[] (servicebil) — da kan det ikke
// spørres på i Firestore og dokumentene må skannes.
function _projectSnapshotStores() {
    return [
        { key: STORAGE_KEY,         col: 'forms',          fields: _PROJECT_SNAPSHOT_FIELDS },
        { key: ARCHIVE_KEY,         col: 'archive',        fields: _PROJECT_SNAPSHOT_FIELDS },
        { key: SERVICE_STORAGE_KEY, col: 'serviceforms',   fields: _PROJECT_IDENTITY_FIELDS, inEntries: true },
        { key: SERVICE_ARCHIVE_KEY, col: 'serviceArchive', fields: _PROJECT_IDENTITY_FIELDS, inEntries: true },
        { key: KAPPE_STORAGE_KEY,   col: 'kappeforms',     fields: _PROJECT_IDENTITY_FIELDS },
        { key: KAPPE_ARCHIVE_KEY,   col: 'kappeArchive',   fields: _PROJECT_IDENTITY_FIELDS },
        { key: KVITTERING_STORAGE_KEY, col: 'kvitteringer',      fields: _PROJECT_IDENTITY_FIELDS },
        { key: KVITTERING_ARCHIVE_KEY, col: 'kvitteringArchive', fields: _PROJECT_IDENTITY_FIELDS }
    ];
}

function _projTrim(v) { return v == null ? '' : String(v).trim(); }

// Er dette snapshotet det samme prosjektet som regelen leter etter?
// Prosjektnr er den stabile identiteten; navnet brukes som kontroll (og som eneste
// nøkkel når prosjektet ikke har nummer). Navn sammenlignes uten hensyn til
// store/små bokstaver — ellers ville nettopp en case-feil gjort at vi ikke fant den.
function _projectSnapshotMatches(obj, match) {
    if (!obj) return false;
    var matchNr = _projTrim(match.prosjektnr);
    var matchNavn = _projTrim(match.prosjektnavn);
    var nr = _projTrim(obj.prosjektnr);
    var navn = _projTrim(obj.prosjektnavn);
    if (matchNr) {
        if (nr !== matchNr) return false;
        // Navnet må stemme når BEGGE har navn — hindrer at et annet delprosjekt
        // som deler prosjektnr blir døpt om ved et uhell.
        if (matchNavn && navn && navn.toLowerCase() !== matchNavn.toLowerCase()) return false;
        return true;
    }
    if (!matchNavn) return false;
    return !!navn && navn.toLowerCase() === matchNavn.toLowerCase();
}

// Sammenlignings-normalisering: samme tekst bortsett fra store/små bokstaver og
// mellomrom. Brukes av `from`-vernet i _applyProjectCorrection.
function _projNorm(v) { return _projTrim(v).replace(/\s+/g, ' ').toLowerCase(); }

// Skriv rettelsen inn i ett snapshot. Returnerer true hvis noe faktisk endret seg.
//
// `from` er vernet mot å overskrive brukerens egne verdier: et felt rettes KUN når
// det fortsatt inneholder det `from` sier det skal — altså at det er en urørt kopi av
// prosjektet. Har brukeren skrevet noe annet i feltet (typisk en ordre-spesifikk
// kundens ref eller fakturaadresse), matcher det ikke og feltet røres aldri.
// Sammenligningen er skrivemåte-uavhengig, så nettopp en case-feil ikke sperrer.
function _applyProjectCorrection(obj, changes, fields, from) {
    var changed = false;
    for (var i = 0; i < fields.length; i++) {
        var k = fields[i];
        if (!Object.prototype.hasOwnProperty.call(changes, k)) continue;
        if (!_projTrim(obj[k])) continue;                        // tomt felt → ikke fyll ut
        if (from && _projNorm(obj[k]) !== _projNorm(from[k])) continue;
        if (_projTrim(obj[k]) === _projTrim(changes[k])) continue;
        obj[k] = changes[k];
        changed = true;
    }
    return changed;
}

// Kjør alle regler mot ett snapshot-objekt (flatt skjema eller én service-rad).
function _applyProjectRules(obj, rules, fields) {
    var changed = false;
    for (var i = 0; i < rules.length; i++) {
        if (!_projectSnapshotMatches(obj, rules[i].match)) continue;
        if (_applyProjectCorrection(obj, rules[i].changes, fields, rules[i].from)) changed = true;
    }
    return changed;
}

// Ett lagret skjema. Håndterer både flate skjemaer (ordreseddel/kappeskjema) og
// skjemaer med prosjekt pr. rad (servicebil).
function _correctProjectInForm(form, rules, fields) {
    if (!form) return false;
    if (Array.isArray(form.entries)) {
        var entryChanged = false;
        form.entries.forEach(function(e) {
            if (_applyProjectRules(e, rules, fields)) entryChanged = true;
        });
        return entryChanged;
    }
    return _applyProjectRules(form, rules, fields);
}

// ── localStorage-cachene + de innlastede listene i minnet ──
function _correctProjectInLocalStores(rules) {
    _projectSnapshotStores().forEach(function(store) {
        var list = safeParseJSON(store.key, []);
        if (!Array.isArray(list) || !list.length) return;
        var changed = false;
        list.forEach(function(f) {
            if (_correctProjectInForm(f, rules, store.fields)) changed = true;
        });
        if (changed) safeSetItem(store.key, JSON.stringify(list));
    });
    // Listene rendres fra disse in-memory-arrayene, ikke fra localStorage — uten
    // dette ville lista vist gammelt navn til neste fulle refresh.
    (window.loadedForms || []).forEach(function(f) { _correctProjectInForm(f, rules, _PROJECT_SNAPSHOT_FIELDS); });
    (window.loadedServiceForms || []).forEach(function(f) { _correctProjectInForm(f, rules, _PROJECT_IDENTITY_FIELDS); });
    (window.loadedKappeForms || []).forEach(function(f) { _correctProjectInForm(f, rules, _PROJECT_IDENTITY_FIELDS); });
    (window.loadedKvitteringForms || []).forEach(function(f) { _correctProjectInForm(f, rules, _PROJECT_IDENTITY_FIELDS); });
}

// ── Timebok ──
// Prosjektlista ER malene (getTimebokProjects), men dag-docene lagrer navnet som
// snapshot ved siden av projectId — det må rettes her.
// `renames` = [{ from: <gammelt navn>, to: <nytt navn> }] — `from` matches uten
// hensyn til store/små bokstaver, så normaliseringsregelen (from === to) også virker.
function _applyTimebokRenames(obj, renames) {
    var name = _projTrim(obj.name);
    if (!name) return false;
    for (var i = 0; i < renames.length; i++) {
        var r = renames[i];
        if (!r.from || !r.to) continue;
        if (name.toLowerCase() !== r.from.toLowerCase()) continue;
        if (name === r.to) return false;
        obj.name = r.to;
        return true;
    }
    return false;
}

function _correctProjectInTimebokLocal(renames) {
    var anyChanged = false;
    if (typeof _timebokGetCache === 'function' && typeof _timebokSetCache === 'function') {
        var cache = _timebokGetCache();
        var cacheChanged = false;
        cache.forEach(function(day) {
            (day && Array.isArray(day.projects) ? day.projects : []).forEach(function(p) {
                if (_applyTimebokRenames(p, renames)) cacheChanged = true;
            });
        });
        if (cacheChanged) { _timebokSetCache(cache); anyChanged = true; }
    }
    return anyChanged;
}

// ── Åpent skjema (input-feltene på skjermen) ──
// Uten dette ville skjemaet brukeren står i beholde feilen, og et lagringsklikk
// skrive den rett tilbake til basen vi nettopp rettet.
function _correctProjectInOpenForms(rules) {
    var k, el, dirtyBefore = false;
    try { dirtyBefore = (typeof hasUnsavedChanges === 'function') && hasUnsavedChanges(); } catch (e) {}

    // Ordreseddel — mobil- og desktop-feltet holdes i synk av appen, så vi leser det
    // som har verdi og skriver tilbake til begge.
    var ORD_IDS = {
        prosjektnr: 'prosjektnr',
        prosjektnavn: 'prosjektnavn',
        oppdragsgiver: 'oppdragsgiver',
        kundensRef: 'kundens-ref',
        fakturaadresse: 'fakturaadresse'
    };
    var ord = {};
    for (k in ORD_IDS) {
        var mob = document.getElementById('mobile-' + ORD_IDS[k]);
        var desk = document.getElementById(ORD_IDS[k]);
        ord[k] = (mob && _projTrim(mob.value)) ? mob.value : (desk ? desk.value : '');
    }
    var ordChanged = _applyProjectRules(ord, rules, _PROJECT_SNAPSHOT_FIELDS);
    if (ordChanged) {
        for (k in ORD_IDS) {
            el = document.getElementById(ORD_IDS[k]);             if (el) el.value = ord[k];
            el = document.getElementById('mobile-' + ORD_IDS[k]);  if (el) el.value = ord[k];
        }
        if (typeof updateFakturaadresseDisplay === 'function') {
            updateFakturaadresseDisplay('fakturaadresse-display-text', ord.fakturaadresse || '');
        }
    }

    // Kappeskjema
    var KAPPE_IDS = { prosjektnr: 'kappe-prosjektnr', prosjektnavn: 'kappe-prosjektnavn' };
    var kappe = {};
    for (k in KAPPE_IDS) { el = document.getElementById(KAPPE_IDS[k]); kappe[k] = el ? el.value : ''; }
    var kappeChanged = _applyProjectRules(kappe, rules, _PROJECT_IDENTITY_FIELDS);
    if (kappeChanged) {
        for (k in KAPPE_IDS) { el = document.getElementById(KAPPE_IDS[k]); if (el) el.value = kappe[k]; }
        if (typeof renumberKappeLines === 'function') renumberKappeLines();
    }

    // Servicebil — prosjekt pr. bestillingskort
    var serviceChanged = false;
    document.querySelectorAll('#service-entries .service-entry-card').forEach(function(card) {
        var nrEl = card.querySelector('.service-entry-prosjektnr');
        var navnEl = card.querySelector('.service-entry-prosjektnavn');
        var entry = { prosjektnr: nrEl ? nrEl.value : '', prosjektnavn: navnEl ? navnEl.value : '' };
        if (!_applyProjectRules(entry, rules, _PROJECT_IDENTITY_FIELDS)) return;
        if (nrEl) nrEl.value = entry.prosjektnr;
        if (navnEl) navnEl.value = entry.prosjektnavn;
        serviceChanged = true;
    });
    if (serviceChanged && typeof renumberServiceEntries === 'function') renumberServiceEntries();

    // Kvittering
    var KV_IDS = { prosjektnr: 'kvittering-prosjektnr', prosjektnavn: 'kvittering-prosjektnavn' };
    var kv = {};
    for (k in KV_IDS) { el = document.getElementById(KV_IDS[k]); kv[k] = el ? el.value : ''; }
    var kvChanged = _applyProjectRules(kv, rules, _PROJECT_IDENTITY_FIELDS);
    if (kvChanged) {
        for (k in KV_IDS) { el = document.getElementById(KV_IDS[k]); if (el) el.value = kv[k]; }
        if (typeof _kvSessionPersist === 'function') _kvSessionPersist();
    }

    if (!ordChanged && !kappeChanged && !serviceChanged && !kvChanged) return;

    // Sesjons-gjenopprettingen holder sin egen kopi av skjemaet.
    try {
        if (serviceChanged && typeof getServiceFormData === 'function') {
            sessionStorage.setItem('firesafe_service_current', JSON.stringify(getServiceFormData()));
        }
        if (ordChanged && typeof getFormData === 'function') {
            sessionStorage.setItem('firesafe_current', JSON.stringify(getFormData()));
        }
    } catch (e) {}

    // Ulagret-baseline: vi rettet BÅDE skjemaet og den lagrede kopien, så et skjema
    // som var rent skal fortsatt være rent. Var det allerede skittent, lar vi
    // baselinen stå — ellers ville brukerens egne ulagrede endringer blitt «glemt».
    if (dirtyBefore) return;
    try {
        if (ordChanged && typeof lastSavedData !== 'undefined' && lastSavedData !== null && typeof getFormDataSnapshot === 'function') {
            lastSavedData = getFormDataSnapshot();
        }
        if (serviceChanged && _serviceLastSavedData !== null && typeof getServiceFormDataSnapshot === 'function') {
            _serviceLastSavedData = getServiceFormDataSnapshot();
            sessionStorage.setItem('firesafe_service_current', _serviceLastSavedData);
        }
        if (kappeChanged && _kappeLastSavedData !== null && typeof getKappeFormDataSnapshot === 'function') {
            _kappeLastSavedData = getKappeFormDataSnapshot();
            sessionStorage.setItem('firesafe_kappe_current', _kappeLastSavedData);
        }
        if (kvChanged && _kvLastSavedData !== null && typeof getKvitteringFormDataSnapshot === 'function') {
            _kvLastSavedData = getKvitteringFormDataSnapshot();
        }
    } catch (e) {}
}

// ── Firestore ──
// localStorage cacher bare de nyeste ~50 skjemaene; fasiten ligger i Firestore, så
// eldre skjemaer må rettes der. Samlingene er per bruker og små — full skanning er
// samme mønster som syncOrderNumberIndex.
async function _commitProjectCorrectionWrites(writes) {
    for (var i = 0; i < writes.length; i += 400) {
        var batch = db.batch();
        writes.slice(i, i + 400).forEach(function(w) { batch.update(w.ref, w.patch); });
        await batch.commit();
    }
}

async function _correctProjectInFirestore(rules, renames) {
    if (!currentUser || !db) return;
    var base = db.collection('users').doc(currentUser.uid);
    // Kan vi spørre smalt? Kun når ALLE regler leter etter samme prosjektnr — ellers
    // må vi skanne, siden en where-spørring bare tar ett nummer.
    var queryNr = '';
    for (var r = 0; r < rules.length; r++) {
        var nr = _projTrim(rules[r].match.prosjektnr);
        if (!nr) { queryNr = ''; break; }
        if (queryNr && queryNr !== nr) { queryNr = ''; break; }
        queryNr = nr;
    }
    var stores = _projectSnapshotStores();

    for (var i = 0; i < stores.length; i++) {
        var store = stores[i];
        try {
            // Flate skjemaer har prosjektnr på dokumentet → smal spørring. Servicebil
            // har det i entries[] (array) og må skannes.
            var query = (queryNr && !store.inEntries)
                ? base.collection(store.col).where('prosjektnr', '==', queryNr)
                : base.collection(store.col);
            var snap = await query.get();
            var writes = [];
            snap.docs.forEach(function(doc) {
                var data = doc.data();
                // Kopi av verdiene FØR rettelsen, så patchen kun inneholder felt som
                // faktisk endret seg (ingen unødvendige skrivinger til Firestore).
                var before = {};
                store.fields.forEach(function(f) { before[f] = data[f]; });
                if (!_correctProjectInForm(data, rules, store.fields)) return;
                var patch = {};
                if (store.inEntries) {
                    patch.entries = data.entries;
                } else {
                    store.fields.forEach(function(f) { if (data[f] !== before[f]) patch[f] = data[f]; });
                }
                if (Object.keys(patch).length) writes.push({ ref: doc.ref, patch: patch });
            });
            if (writes.length) await _commitProjectCorrectionWrites(writes);
        } catch (e) {
            console.error('Project correction (' + store.col + '):', e);
        }
    }

    // Timebok-dagene: navn-snapshot ved siden av projectId.
    try {
        var daySnap = await base.collection('timebok').get();
        var dayWrites = [];
        daySnap.docs.forEach(function(doc) {
            var data = doc.data();
            if (!Array.isArray(data.projects)) return;
            var changed = false;
            data.projects.forEach(function(p) { if (_applyTimebokRenames(p, renames)) changed = true; });
            if (changed) dayWrites.push({ ref: doc.ref, patch: { projects: data.projects } });
        });
        if (dayWrites.length) await _commitProjectCorrectionWrites(dayWrites);
    } catch (e) {
        console.error('Project correction (timebok):', e);
    }
}

// Rendre listene på nytt hvis de står åpne, så rettelsen er synlig med én gang.
// Hver liste gates på om DEN er synlig — ikke bare på at Hent-visningen er åpen.
// Fanene deler window.loaded*-arrayene (bil-historikken fyller f.eks.
// loadedServiceForms med sin egen kombinerte liste), så å rendre en skjult fane
// ville risikert å tegne feil datasett inn i den.
function _isListVisible(id) {
    var el = document.getElementById(id);
    // getClientRects() framfor offsetParent: offsetParent er null også for elementer
    // inne i position:fixed-kontekster, som views'ene er.
    return !!el && el.getClientRects().length > 0;
}

function _rerenderListsAfterProjectCorrection() {
    try {
        // KRITISK: bare re-rendre lister som FAKTISK har data. Dette er en kosmetisk
        // oppfriskning, og den må aldri kunne bytte ut ekte innhold med tomt.
        // window.loadedForms nullstilles til [] i auth.onAuthStateChanged (script.js),
        // som fyrer under sidelasting mens den cachede lista alt står på skjermen —
        // uten .length-sjekken rendret vi da «Ingen lagrede skjemaer» oppå den, helt
        // til Firestore-refreshen kom og fylte den igjen. Det ga et synlig blink.
        if (_isListVisible('saved-list') && typeof renderSavedFormsList === 'function'
            && window.loadedForms && window.loadedForms.length) {
            renderSavedFormsList(window.loadedForms, false, _savedHasMore || _sentHasMore);
        }
        if (_isListVisible('service-list') && typeof renderServiceFormsList === 'function'
            && window.loadedServiceForms && window.loadedServiceForms.length) {
            renderServiceFormsList(window.loadedServiceForms);
        }
        if (_isListVisible('kappe-list') && typeof renderKappeFormsList === 'function'
            && window.loadedKappeForms && window.loadedKappeForms.length) {
            renderKappeFormsList(window.loadedKappeForms);
        }
        if (_isListVisible('bil-history-list') && typeof renderBilHistory === 'function') renderBilHistory();
        if (document.body.classList.contains('timebok-view-open') && typeof renderTimebok === 'function' && !_timebokIsDirty()) renderTimebok();
    } catch (e) {
        console.error('Rerender after project correction:', e);
    }
}

// ── FASIT-SYNK VED VISNING (ingen «lagre på nytt» kreves) ────────────────────
// Prosjektet i Innstillinger er fasit for skrivemåten. Hver gang en liste eller et
// skjema fylles med lagret data, synkroniseres kopien mot prosjektene FØR den vises.
// Selvreparerende: retter data som drev fra hverandre før denne mekanismen fantes,
// uten migrering og uten at brukeren må gjøre noe.
//
// Reglene har `from` = prosjektets egne verdier, så de retter bare SKRIVEMÅTEN
// (store/små bokstaver, mellomrom). Et felt der brukeren har skrevet noe reelt annet
// — typisk en ordre-spesifikk kundens ref eller fakturaadresse — matcher ikke og blir
// aldri overskrevet.
// Reelle innholds-endringer i et prosjekt håndteres av _propagateProjectCorrection
// ved lagring, som kjenner både gammel og ny verdi og derfor trygt kan skille
// «urørt kopi» fra «brukerens egen endring».
var _PROJECT_FIELD_KINDS = { full: _PROJECT_SNAPSHOT_FIELDS, identity: _PROJECT_IDENTITY_FIELDS };

function _projectFasitRules() {
    // Union av minne og localStorage-cachen (dedupet på id): begge kildene er
    // begrenset til én side (PAGE_SIZE), og de kan inneholde ulike prosjekter.
    var templates = [];
    var seenTplIds = {};
    [(window.loadedTemplates || []), safeParseJSON(TEMPLATE_KEY, [])].forEach(function(src) {
        (src || []).forEach(function(tpl) {
            if (!tpl) return;
            var id = tpl.id != null ? String(tpl.id) : '';
            if (id) {
                if (seenTplIds[id]) return;
                seenTplIds[id] = true;
            }
            templates.push(tpl);
        });
    });
    var rules = [], renames = [];
    (templates || []).forEach(function(tpl) {
        if (!tpl) return;
        var identity = { prosjektnr: _projTrim(tpl.prosjektnr), prosjektnavn: _projTrim(tpl.prosjektnavn) };
        if (!identity.prosjektnr && !identity.prosjektnavn) return;
        var changes = {};
        _PROJECT_SNAPSHOT_FIELDS.forEach(function(f) {
            var v = _projTrim(tpl[f]);
            if (v) changes[f] = v;
        });
        // from = prosjektets egne verdier → kun skrivemåte rettes.
        rules.push({ match: identity, changes: changes, from: changes });
        if (identity.prosjektnavn) renames.push({ from: identity.prosjektnavn, to: identity.prosjektnavn });
    });
    return { rules: rules, renames: renames };
}

// Heling av LAGRET data (localStorage + Firestore). Debounced og kjøres bare når
// visningen faktisk fant et avvik — etter første heling er det ingenting å gjøre,
// så dette er en engangskostnad, ikke noe som skjer ved hver listeåpning.
var _projectHealTimer = null;
var _projectHealRunning = false;
function _scheduleProjectHeal() {
    if (_projectHealRunning || _projectHealTimer) return;
    _projectHealTimer = setTimeout(function() {
        _projectHealTimer = null;
        _projectHealRunning = true;
        var built = _projectFasitRules();
        try {
            _correctProjectInLocalStores(built.rules);
            _correctProjectInTimebokLocal(built.renames);
        } catch (e) { console.error('Project heal (lokalt):', e); }
        _correctProjectInFirestore(built.rules, built.renames)
            .catch(function(e) { console.error('Project heal (Firestore):', e); })
            .then(function() { _projectHealRunning = false; });
    }, 600);
}

// Kalles med lista som skal vises. Retter skrivemåten i objektene som faktisk
// rendres, så rettelsen er synlig med én gang — også før helingen har rukket å
// skrive til Firestore.
function syncFormsWithProjects(forms, kind) {
    if (!Array.isArray(forms) || !forms.length) return forms;
    var fields = _PROJECT_FIELD_KINDS[kind] || _PROJECT_SNAPSHOT_FIELDS;
    var built = _projectFasitRules();
    if (!built.rules.length) return forms;
    var changed = false;
    forms.forEach(function(f) { if (_correctProjectInForm(f, built.rules, fields)) changed = true; });
    if (changed) _scheduleProjectHeal();
    return forms;
}

// Samme, for ett enkelt skjema (åpning av lagret skjema / sesjons-gjenoppretting).
function syncOneFormWithProjects(form, kind) {
    if (!form) return form;
    var fields = _PROJECT_FIELD_KINDS[kind] || _PROJECT_SNAPSHOT_FIELDS;
    var built = _projectFasitRules();
    if (built.rules.length && _correctProjectInForm(form, built.rules, fields)) _scheduleProjectHeal();
    return form;
}

// Timebok lagrer prosjektnavnet som tekst i både prosjektlista og dag-docene.
function syncTimebokProjectNames() {
    var built = _projectFasitRules();
    if (!built.renames.length) return;
    if (_correctProjectInTimebokLocal(built.renames)) _scheduleProjectHeal();
}

window.syncFormsWithProjects = syncFormsWithProjects;
window.syncOneFormWithProjects = syncOneFormWithProjects;
window.syncTimebokProjectNames = syncTimebokProjectNames;

// Bygg reglene: (1) den faktiske rettelsen, (2) normalisering av skrivemåte.
function _buildProjectCorrectionRules(oldTpl, newTpl) {
    var rules = [];
    var renames = [];
    if (oldTpl) {
        var changes = {};
        _PROJECT_SNAPSHOT_FIELDS.forEach(function(f) {
            if (_projTrim(oldTpl[f]) !== _projTrim(newTpl[f])) changes[f] = _projTrim(newTpl[f]);
        });
        if (Object.keys(changes).length) {
            // from = de gamle prosjektverdiene → kun skjemaer som fortsatt har en
            // urørt kopi oppdateres. Har brukeren overstyrt feltet i ett skjema,
            // beholder det skjemaet sin egen verdi.
            rules.push({ match: oldTpl, changes: changes, from: oldTpl });
            if (Object.prototype.hasOwnProperty.call(changes, 'prosjektnavn')) {
                renames.push({ from: _projTrim(oldTpl.prosjektnavn), to: _projTrim(newTpl.prosjektnavn) });
            }
        }
    }
    // Normaliseringsregelen: match = prosjektet slik det ER nå (navn matches uten
    // hensyn til store/små bokstaver), changes = nøyaktig skrivemåte. Reparerer
    // prosjekter som ble rettet før denne mekanismen fantes; ellers en no-op.
    var identity = { prosjektnr: _projTrim(newTpl.prosjektnr), prosjektnavn: _projTrim(newTpl.prosjektnavn) };
    if (identity.prosjektnr || identity.prosjektnavn) {
        rules.push({ match: identity, changes: identity, from: identity });
        if (identity.prosjektnavn) renames.push({ from: identity.prosjektnavn, to: identity.prosjektnavn });
    }
    return { rules: rules, renames: renames };
}

// Inngangspunkt: kalles når et prosjekt er lagret i Innstillinger.
function _propagateProjectCorrection(oldTpl, newTpl) {
    if (!newTpl) return;
    var built = _buildProjectCorrectionRules(oldTpl, newTpl);
    if (!built.rules.length) return;

    _correctProjectInLocalStores(built.rules);
    _correctProjectInOpenForms(built.rules);
    if (built.renames.length) _correctProjectInTimebokLocal(built.renames);
    _rerenderListsAfterProjectCorrection();

    // Firestore i bakgrunnen — lokalt er allerede rettet, så UI-et er oppdatert
    // uansett hvor lenge skanningen tar.
    _correctProjectInFirestore(built.rules, built.renames)
        .catch(function(e) { console.error('Propagate project correction:', e); });
}


async function saveTemplateFromEditor() {
    var data = {
        prosjektnavn: document.getElementById('tpl-edit-prosjektnavn').value.trim(),
        prosjektnr: document.getElementById('tpl-edit-prosjektnr').value.trim(),
        oppdragsgiver: document.getElementById('tpl-edit-oppdragsgiver').value.trim(),
        kundensRef: document.getElementById('tpl-edit-kundensRef').value.trim(),
        fakturaadresse: document.getElementById('tpl-edit-fakturaadresse').value.trim(),
        leveringsadresse: document.getElementById('tpl-edit-leveringsadresse').value.trim(),
        timebokBracketId: document.getElementById('tpl-edit-timebok-dist').value || null
    };
    // Validate required template fields
    var reqSettings = cachedRequiredSettings || getDefaultRequiredSettings();
    var templateReqs = reqSettings.template || {};
    var validationKeys = {
        prosjektnavn: 'validation_prosjektnavn',
        prosjektnr: 'validation_prosjektnr',
        oppdragsgiver: 'validation_oppdragsgiver',
        kundensRef: 'validation_kundens_ref',
        fakturaadresse: 'validation_fakturaadresse',
        leveringsadresse: 'kappe_section_delivery'
    };
    for (var key in validationKeys) {
        if (templateReqs[key] && !data[key]) {
            showNotificationModal(t('required_field', t(validationKeys[key])));
            return;
        }
    }

    // Admin vurderer et forslag → Godkjenn (felles prosjekt).
    if (_projReview) { _projApprove(data); return; }

    // Verdiene FØR rettelsen — nøkkelen som finner igjen prosjektet i alle lagrede
    // skjemaer. Må hentes før localStorage/minnet skrives over. Kopi, ikke referanse:
    // _findTemplateById kan returnere objektet fra window.loadedTemplates, som vi
    // oppdaterer lenger ned.
    var oldTemplate = _editingTemplateId ? await _findTemplateById(_editingTemplateId) : null;
    if (oldTemplate) oldTemplate = Object.assign({}, oldTemplate);

    // Hvor lagres det? (se FELLES PROSJEKTER) Felles liste virker → admin skriver felles,
    // montør skriver eget + forslag. Ellers (reglene mangler) → eget, som før.
    var sharedOn = _projSharedOk === true;
    var dist = data.timebokBracketId || null;
    var item;
    if (_editingTemplateId) {
        if (sharedOn && oldTemplate && oldTemplate._shared) {
            if (isAdmin) {
                _projStore.setShared(_editingTemplateId, data, true).catch(function (e) {
                    console.error('Update shared project:', e);
                    showNotificationModal(t('proj_action_failed'));
                });
            } else {
                // Montør: bare reiseavstanden (personlig) — feltene er låst.
                data = Object.assign(_projStrip(oldTemplate), { timebokBracketId: dist });
                delete data.id;
            }
            _projSaveOverride(_editingTemplateId, dist);
            item = Object.assign({}, oldTemplate, data, { id: _editingTemplateId, timebokBracketId: dist, _shared: true });
        } else {
            _projStore.setOwn(_editingTemplateId, data, true);
            item = Object.assign({}, oldTemplate || {}, data, { id: _editingTemplateId });
            // Venter på godkjenning → admin skal se det rettede forslaget.
            if (sharedOn && oldTemplate && oldTemplate.forslag === 'pending') _projSubmit(item);
        }
        _projCacheUpsert(item);
        showNotificationModal(t('template_updated'), true);
        // Rettelsen må slå igjennom overalt prosjektet er brukt — skjemaene har bare
        // en kopi av verdiene, ingen referanse tilbake hit.
        _propagateProjectCorrection(oldTemplate, data);
    } else {
        // Create new template
        data.createdAt = new Date().toISOString();
        data.createdBy = currentUser ? currentUser.uid : 'local';
        data.active = true;
        data.id = Date.now().toString();
        if (sharedOn && isAdmin) {
            _projStore.setShared(data.id, data).catch(function (e) {
                console.error('Create shared project:', e);
                showNotificationModal(t('proj_action_failed'));
            });
            if (dist) _projSaveOverride(data.id, dist);
            item = Object.assign({}, data, { _shared: true });
            showNotificationModal(t('template_save_success'), true);
        } else if (sharedOn) {
            // Montør: eget prosjekt med en gang + forslag til admin.
            data.forslag = 'pending';
            _projStore.setOwn(data.id, data);
            _projSubmit(data);
            item = Object.assign({}, data, { _own: true, _pending: true });
            showNotificationModal(t('proj_saved_pending'), true);
        } else {
            _projStore.setOwn(data.id, data);
            item = Object.assign({}, data);
            showNotificationModal(t('template_save_success'), true);
        }
        _projCacheUpsert(item);
    }
    var templates = safeParseJSON(TEMPLATE_KEY, []);

    // Nullstilles FØR closeTemplateEditor, ellers ville den vist velgeren igjen
    // et øyeblikk før vi lukker den — en synlig blink.
    var fromPicker = _templateEditorFromPicker;
    _templateEditorFromPicker = false;
    var fromTimebok = _templateEditorFromTimebok;
    _templateEditorFromTimebok = false;
    var editedId = _editingTemplateId;
    closeTemplateEditor();
    _renderSettingsTemplateListFromData(templates);
    if (fromTimebok) _timebokAfterTemplateSave(!editedId, Object.assign({ id: editedId || data.id }, data), oldTemplate ? oldTemplate.prosjektnavn : '');
    // Opprettet fra «Velg prosjekt»: ta det i bruk med det samme. Man åpner jo
    // velgeren fordi et prosjekt skal brukes NÅ — samme resonnement som
    // addPlanFromPicker, der den nye etasjen hukes av direkte.
    // _applyTemplateToForm treffer riktig skjema (ordreseddel/service/kappe) og
    // lukker velgeren selv.
    if (fromPicker) {
        _setTemplatePickerHidden(false);
        _applyTemplateToForm(data);
    }
}

async function toggleTemplateActive(templateId) {
    var tpl = await _findTemplateById(templateId);
    if (!tpl) return;

    var newActive = tpl.active === false ? true : false;

    // Update visual state + localStorage immediately (optimistic)
    var itemEl = _findSettingsTemplateItem(templateId);
    if (itemEl) {
        if (newActive) itemEl.classList.remove('inactive');
        else itemEl.classList.add('inactive');
    }
    var templates = safeParseJSON(TEMPLATE_KEY, []);
    var idx = templates.findIndex(function(t) { return t.id === templateId; });
    if (idx !== -1) {
        templates[idx].active = newActive;
        _projCache(templates);
    }

    if (tpl._shared && _projSharedOk) {
        _projStore.setShared(templateId, { active: newActive }, true).catch(function (e) { console.error('Toggle shared project:', e); });
    } else {
        _projStore.setOwn(templateId, { active: newActive }, true);
    }
}

async function deleteTemplateFromSettings(templateId) {
    var tpl = await _findTemplateById(templateId);
    if (!tpl) return;
    showConfirmModal(t('template_delete_confirm'), function() {
        // Optimistic removal: update local state + DOM immediately
        var arrIdx = window.loadedTemplates.findIndex(function(t) { return t.id === templateId; });
        if (arrIdx !== -1) window.loadedTemplates.splice(arrIdx, 1);
        var lsList = safeParseJSON(TEMPLATE_KEY, []);
        var lsIdx = lsList.findIndex(function(t) { return t.id === templateId; });
        if (lsIdx !== -1) { lsList.splice(lsIdx, 1); safeSetItem(TEMPLATE_KEY, JSON.stringify(lsList)); }
        // Remove DOM element
        var el = _findSettingsTemplateItem(templateId);
        if (el) el.remove();
        // Show empty message if no items left
        var listEl = document.getElementById('settings-template-list');
        if (listEl && !listEl.querySelector('.settings-template-item')) {
            listEl.innerHTML = '';
        }

        // Felles prosjekt (admin) → borte for alle i firmaet; eget → bare mitt.
        if (tpl._shared && _projSharedOk) _projStore.delShared(templateId).catch(function (e) { console.error('Delete shared project:', e); });
        else _projStore.delOwn(templateId);
    });
}

function updateRequiredIndicators() {
    if (typeof _sjUpdateRequiredIndicators === 'function') _sjUpdateRequiredIndicators();
    const settings = cachedRequiredSettings || getDefaultRequiredSettings();
    const saveReqs = settings.save || {};

    // Update text input fields
    for (const [key, inputId] of Object.entries(REQUIRED_FIELD_IDS)) {
        const input = document.getElementById(inputId);
        if (!input) continue;
        const field = input.closest('.mobile-field');
        if (!field) continue;

        if (saveReqs[key]) {
            field.classList.add('field-required');
        } else {
            field.classList.remove('field-required');
        }
    }

    // Order description fields (dynamic order cards)
    document.querySelectorAll('#mobile-orders .mobile-order-desc').forEach(function(desc) {
        const field = desc.closest('.mobile-field');
        if (!field) return;
        if (saveReqs.beskrivelse !== false) {
            field.classList.add('field-required');
        } else {
            field.classList.remove('field-required');
        }
    });

    // Materials and Timer labels in order cards
    document.querySelectorAll('#mobile-orders .mobile-order-card').forEach(function(card) {
        // Materials section — toggle field-required class (CSS adds star via ::after)
        var matSection = card.querySelector('.mobile-order-materials-section');
        if (matSection) {
            matSection.classList.toggle('field-required', !!saveReqs.materialer);
            // Fjern gammel inline span hvis eksisterer (backward compat ved live toggle)
            var oldStar = matSection.querySelector('.required-star');
            if (oldStar) oldStar.remove();
        }
        // Dager & tid (Arbeidstid) field
        var dagTimerDisplay = card.querySelector('.dag-timer-display');
        if (dagTimerDisplay) {
            var dagerField = dagTimerDisplay.closest('.mobile-field');
            if (dagerField) {
                if (saveReqs.dager) {
                    dagerField.classList.add('field-required');
                } else {
                    dagerField.classList.remove('field-required');
                }
            }
        }
        // Merknad field
        var merknadInput = card.querySelector('.mobile-order-merknad');
        if (merknadInput) {
            var merknadField = merknadInput.closest('.mobile-field');
            if (merknadField) {
                if (saveReqs.merknad) {
                    merknadField.classList.add('field-required');
                } else {
                    merknadField.classList.remove('field-required');
                }
            }
        }
    });

    // Signature field
    const sigPreview = document.getElementById('mobile-signature-preview');
    if (sigPreview) {
        const sigField = sigPreview.closest('.mobile-field');
        if (sigField) {
            if (saveReqs.signatur) {
                sigField.classList.add('field-required');
            } else {
                sigField.classList.remove('field-required');
            }
        }
    }

    // Service form required indicators
    const serviceReqs = settings.service || {};

    // Service montør field
    const serviceMontor = document.getElementById('service-montor');
    if (serviceMontor) {
        const serviceMontorField = serviceMontor.closest('.mobile-field');
        if (serviceMontorField) {
            if (serviceReqs.montor !== false) {
                serviceMontorField.classList.add('field-required');
            } else {
                serviceMontorField.classList.remove('field-required');
            }
        }
    }

    // Service signature field
    const serviceSigPreview = document.getElementById('service-signature-preview');
    if (serviceSigPreview) {
        const serviceSigField = serviceSigPreview.closest('.mobile-field');
        if (serviceSigField) {
            if (serviceReqs.signatur) {
                serviceSigField.classList.add('field-required');
            } else {
                serviceSigField.classList.remove('field-required');
            }
        }
    }

    // Service entry card fields (dynamic)
    document.querySelectorAll('#service-entries .service-entry-card').forEach(function(card) {
        var datoField = card.querySelector('.service-entry-dato');
        if (datoField) {
            var f = datoField.closest('.mobile-field');
            if (f) f.classList.toggle('field-required', serviceReqs.dato !== false);
        }
        var pnrField = card.querySelector('.service-entry-prosjektnr');
        if (pnrField) {
            var f = pnrField.closest('.mobile-field');
            if (f) f.classList.toggle('field-required', serviceReqs.prosjektnr !== false);
        }
        var pnavnField = card.querySelector('.service-entry-prosjektnavn');
        if (pnavnField) {
            var f = pnavnField.closest('.mobile-field');
            if (f) f.classList.toggle('field-required', serviceReqs.prosjektnavn !== false);
        }
        // Materials section
        var matSection = card.querySelector('.mobile-order-materials-section');
        if (matSection) {
            matSection.classList.toggle('field-required', serviceReqs.materialer !== false);
        }
    });

    // Kappe form required indicators
    if (document.getElementById('kappe-view')) {
        updateKappeRequiredIndicators();
    }
}

