            while (i < lines.length && /^([-*•]|\d+[.)])\s+/.test(lines[i].trim()) && /^\d/.test(lines[i].trim()) === ol) items.push(lines[i++].trim().replace(/^([-*•]|\d+[.)])\s+/, ''));
            out.push('<' + (ol ? 'ol' : 'ul') + ' class="docs-ai-list-md">' + items.map(function (x) { return '<li>' + inline(x) + '</li>'; }).join('') + '</' + (ol ? 'ol' : 'ul') + '>');
