        var i = chat.turns.indexOf(turn);
        var el = document.getElementById('ai-turn-' + chat.id + '-' + i);
        if (el) el.outerHTML = _docsAiAnswerHtml(Object.assign({ docName: chat.docName, _cid: chat.id + '-' + i }, turn));
